import React, { useMemo } from 'react';
import { Gift, MapPin, Users, Heart, ArrowRight, UserPlus, Calendar } from 'lucide-react';
import { Contact, Address, ContactType } from '../types';

interface DashboardProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ contacts, addresses, types, onContactClick }) => {
  const upcomingBirthdays = useMemo(() => {
    const today = new Date();
    return contacts
      .filter(c => c.birthDate)
      .map(c => {
        const bday = new Date(c.birthDate!);
        const currentYearBday = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
        const nextBday = currentYearBday < today 
          ? new Date(today.getFullYear() + 1, bday.getMonth(), bday.getDate())
          : currentYearBday;

        const diff = Math.ceil((nextBday.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        const age = nextBday.getFullYear() - bday.getFullYear();

        return { ...c, daysUntil: diff, nextAge: age };
      })
      .sort((a, b) => a.daysUntil - b.daysUntil)
      .slice(0, 5);
  }, [contacts]);

  const stats = [
    { label: 'Totaal Contacten', value: contacts.length, icon: <Users />, color: 'bg-blue-500' },
    { label: 'Unieke Adressen', value: addresses.length, icon: <MapPin />, color: 'bg-emerald-500' },
    { label: 'Favorieten', value: contacts.filter(c => c.isFavorite).length, icon: <Heart />, color: 'bg-red-500' },
    { label: 'Jarigen deze maand', value: contacts.filter(c => c.birthDate && new Date(c.birthDate).getMonth() === new Date().getMonth()).length, icon: <Gift />, color: 'bg-amber-500' },
  ];

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div>
        <h2 className="text-3xl font-bold text-gray-900 mb-1">Welkom terug!</h2>
        <p className="text-gray-500">Hier is een overzicht van je netwerk op dit moment.</p>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 group hover:shadow-md transition-shadow">
            <div className={`p-3 rounded-2xl ${stat.color} text-white shadow-inner group-hover:scale-110 transition-transform`}>
              {React.cloneElement(stat.icon as React.ReactElement, { size: 24 })}
            </div>
            <div>
              <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
              <p className="text-2xl font-black text-gray-900">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Birthday Widget */}
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              <Gift className="text-amber-500" /> Komende Verjaardagen
            </h3>
            <button className="text-blue-600 font-bold text-sm hover:underline flex items-center gap-1">
              Volledige Kalender <ArrowRight size={14} />
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {upcomingBirthdays.length > 0 ? upcomingBirthdays.map(c => (
              <div 
                key={c.id} 
                onClick={() => onContactClick(c.id)}
                className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4 cursor-pointer hover:bg-gray-50 hover:border-blue-200 transition-all group"
              >
                <div className="relative">
                  <img src={c.photoUrl || 'https://picsum.photos/60'} className="w-16 h-16 rounded-2xl object-cover ring-4 ring-blue-50" />
                  <div className="absolute -bottom-1 -right-1 bg-amber-500 text-white p-1 rounded-lg">
                    <Gift size={12} />
                  </div>
                </div>
                <div className="flex-1">
                  <p className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{c.firstName} {c.lastName}</p>
                  <p className="text-xs text-gray-500 font-medium">Wordt {c.nextAge} jaar</p>
                  <div className="mt-2 flex items-center gap-1">
                    <span className="text-[10px] bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full font-black uppercase">
                      Over {c.daysUntil} {c.daysUntil === 1 ? 'dag' : 'dagen'}
                    </span>
                  </div>
                </div>
              </div>
            )) : (
              <div className="col-span-2 p-10 bg-gray-50 rounded-3xl border border-dashed border-gray-200 flex flex-col items-center text-gray-400">
                <Calendar size={48} className="mb-2 opacity-20" />
                <p>Geen verjaardagen bekend</p>
              </div>
            )}
          </div>
        </div>

        {/* Recent Activity / Quick Add */}
        <div className="space-y-6">
          <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
            <UserPlus className="text-blue-500" /> Snel Acties
          </h3>
          <div className="bg-blue-600 rounded-3xl p-6 text-white shadow-xl shadow-blue-200 relative overflow-hidden group">
            <div className="absolute -top-10 -right-10 w-40 h-40 bg-blue-500 rounded-full opacity-50 group-hover:scale-125 transition-transform" />
            <div className="relative z-10">
              <h4 className="text-lg font-bold mb-2">Netwerk uitbreiden?</h4>
              <p className="text-blue-100 text-sm mb-6">Voeg snel nieuwe vrienden of zakenrelaties toe aan je overzicht.</p>
              <button className="bg-white text-blue-600 px-6 py-2.5 rounded-2xl font-bold text-sm shadow-lg hover:bg-blue-50 transition-colors">
                Nieuw Contact
              </button>
            </div>
          </div>

          <div className="bg-white rounded-3xl p-6 border border-gray-100 shadow-sm space-y-4">
            <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Recente Favorieten</h4>
            <div className="space-y-3">
              {contacts.filter(c => c.isFavorite).slice(0, 3).map(c => (
                <div 
                  key={c.id} 
                  className="flex items-center gap-3 cursor-pointer p-2 rounded-xl hover:bg-gray-50 transition-colors"
                  onClick={() => onContactClick(c.id)}
                >
                  <img src={c.photoUrl || 'https://picsum.photos/40'} className="w-10 h-10 rounded-full object-cover" />
                  <div>
                    <p className="text-sm font-bold text-gray-900">{c.firstName} {c.lastName}</p>
                    <p className="text-[10px] text-gray-400 font-medium">Laatst bijgewerkt: {new Date(c.updatedAt).toLocaleDateString()}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

