                <input placeholder="Soort" className="flex-1 px-3 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-sm" value={newPet.type} onChange={e => setNewPet({...newPet, type: e.target.value})} />
                <input placeholder="Naam" className="flex-1 px-3 py-1.5 bg-gray-50 border border-gray-200 rounded-lg text-sm" value={newPet.name} onChange={e => setNewPet({...newPet, name: e.target.value})} />
                <button 
                  type="button"
                  onClick={() => {
                    if (newPet.name) {
                      setFormData({...formData, pets: [...(formData.pets || []), newPet]});
