          <button onClick={() => onDelete(contact.id)} className="p-2 bg-red-500/80 hover:bg-red-500 backdrop-blur-md text-white rounded-full transition-all"><Trash2 size={18} /></button>
        </div>

        {/* Avatar Positioned Overlap */}
        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
