export default ContactDetails;

import React, { useState, useEffect, useRef } from 'react';
import { X, Save, Camera, Plus, Trash, RefreshCw, Image as ImageIcon, Upload, Loader2, Heart } from 'lucide-react';
import { Contact, Address, ContactType, Pet } from '../types';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  initialCoords: [number, number] | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, initialCoords, onClose, onSave 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingAddress, setIsLoadingAddress] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');

  const [formData, setFormData] = useState<Partial<Contact>>(
    contact || {
      firstName: '',
      lastName: '',
      phones: [''],
      emails: [''],
      typeId: types[0].id,
      notes: '',
      isFavorite: false,
      pets: [],
      hobbies: [],
      photoUrl: ''
    }
  );

  const [addrData, setAddrData] = useState<Partial<Address>>(
    addresses.find(a => a.id === contact?.addressId) || {
      street: '',
      houseNumber: '',
      postalCode: '',
      city: '',
      lat: initialCoords ? initialCoords[0] : 52.37,
      lng: initialCoords ? initialCoords[1] : 4.89,
      country: 'Nederland'
    }
  );

  const [newPet, setNewPet] = useState<Pet>({ type: '', name: '' });

  // Handle address geocoding using Nominatim API when initialCoords changes (map click)
  useEffect(() => {
    if (initialCoords) {
      const [lat, lng] = initialCoords;
      setIsLoadingAddress(true);

      // Fetch address details from OpenStreetMap Nominatim
      fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&addressdetails=1`)
        .then(res => res.json())
        .then(data => {
          const addr = data.address;
          setAddrData(prev => ({
            ...prev,
            street: addr.road || addr.pedestrian || addr.suburb || addr.neighbourhood || '',
            houseNumber: addr.house_number || '',
            postalCode: addr.postcode || '',
            city: addr.city || addr.town || addr.village || addr.municipality || '',
            lat,
            lng
          }));
        })
        .catch(err => {
          console.error("Geocoding failed:", err);
          // Fallback if API fails
          setAddrData(prev => ({ ...prev, lat, lng }));
        })
        .finally(() => setIsLoadingAddress(false));
    }
  }, [initialCoords]);

  const generateRandomPhoto = () => {
    const randomId = Math.floor(Math.random() * 70);
    setFormData({ ...formData, photoUrl: `https://i.pravatar.cc/300?u=${randomId}` });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, photoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const addHobby = () => {
    const tag = hobbyInput.trim();
    if (tag && !formData.hobbies?.includes(tag)) {
      setFormData({
        ...formData,
        hobbies: [...(formData.hobbies || []), tag]
      });
      setHobbyInput('');
    }
  };

  const handleHobbyKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      addHobby();
    }
  };

  const removeHobby = (index: number) => {
    setFormData({
      ...formData,
      hobbies: formData.hobbies?.filter((_, i) => i !== index)
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const addressId = addrData.id || `addr-${Date.now()}`;
    const contactId = contact?.id || `c-${Date.now()}`;

    const finalAddress: Address = {
      ...addrData as Address,
      id: addressId
    };

    const finalContact: Contact = {
      ...formData as Contact,
      id: contactId,
      addressId,
      updatedAt: new Date().toISOString(),
      createdAt: contact?.createdAt || new Date().toISOString(),
      interactions: contact?.interactions || []
    };

    onSave(finalContact, finalAddress);
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between bg-white sticky top-0 z-10">
          <h2 className="text-xl font-bold text-gray-900">{contact ? 'Contact Bewerken' : 'Nieuw Contact Toevoegen'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><X size={20} /></button>
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-8 space-y-8">
          {/* Section: Profile Photo */}
          <section className="flex flex-col sm:flex-row items-center gap-6">
            <div className="relative group shrink-0">
              <div className="w-28 h-28 rounded-full bg-gray-100 border-4 border-white shadow-lg overflow-hidden flex items-center justify-center relative">
                {formData.photoUrl ? (
                  <img src={formData.photoUrl} alt="Preview" className="w-full h-full object-cover" />
                ) : (
                  <Camera size={32} className="text-gray-300" />
                )}
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute inset-0 bg-black/40 text-white opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-[10px] font-bold"
                >
                  <Upload size={20} className="mb-1" />
                  UPLOAD
                </button>
              </div>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileUpload} 
                accept="image/*" 
                className="hidden" 
              />
            </div>
            <div className="flex-1 space-y-3 w-full">
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Profielfoto</h3>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <ImageIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                  <input 
                    type="url" 
                    placeholder="Of plak een afbeeldings-URL..."
                    value={formData.photoUrl?.startsWith('data:') ? '' : formData.photoUrl}
                    onChange={e => setFormData({ ...formData, photoUrl: e.target.value })}
                    className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm"
                  />
                </div>
                <button 
                  type="button"
                  onClick={generateRandomPhoto}
                  className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl font-semibold text-xs flex items-center gap-2 hover:bg-blue-100 transition-colors shrink-0"
                >
                  <RefreshCw size={14} />
                  <span className="hidden sm:inline">Willekeurig</span>
                </button>
              </div>
              <p className="text-[10px] text-gray-400 italic">Upload een bestand, plak een URL of gebruik een willekeurige avatar.</p>
            </div>
          </section>

          {/* Section: Basic Info */}
          <section className="space-y-4 pt-4 border-t border-gray-100">
            <div className="flex items-center justify-between">
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">Persoonlijke Gegevens</h3>
              <label className="flex items-center gap-2 cursor-pointer group">
                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest group-hover:text-red-400 transition-colors">Favoriet</span>
                <input 
                  type="checkbox" 
                  checked={formData.isFavorite} 
                  onChange={e => setFormData({...formData, isFavorite: e.target.checked})}
                  className="hidden"
                />
                <Heart size={20} className={`transition-all ${formData.isFavorite ? 'fill-red-500 text-red-500 scale-110' : 'text-gray-300 hover:text-red-200'}`} />
              </label>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Voornaam *</label>
                <input 
                  required
                  type="text" 
                  value={formData.firstName}
                  onChange={e => setFormData({ ...formData, firstName: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Achternaam *</label>
                <input 
                  required
                  type="text" 
                  value={formData.lastName}
                  onChange={e => setFormData({ ...formData, lastName: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Geboortedatum</label>
                <input 
                  type="date" 
                  value={formData.birthDate}
                  onChange={e => setFormData({ ...formData, birthDate: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Contacttype</label>
                <select 
                  value={formData.typeId}
                  onChange={e => setFormData({ ...formData, typeId: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all appearance-none"
                >
                  {types.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                </select>
              </div>
            </div>
          </section>

          {/* Section: Address */}
          <section className="space-y-4 pt-4 border-t border-gray-100">
            <div className="flex items-center justify-between">
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Locatie & Adres</h3>
              {isLoadingAddress && (
                <div className="flex items-center gap-2 text-blue-500 animate-pulse">
                  <Loader2 size={14} className="animate-spin" />
                  <span className="text-[10px] font-bold">Adres ophalen...</span>
                </div>
              )}
            </div>
            <div className="grid grid-cols-4 gap-4">
              <div className="col-span-3">
                <label className="block text-sm font-semibold text-gray-700 mb-1">Straatnaam *</label>
                <input 
                  required
                  type="text" 
                  value={addrData.street}
                  onChange={e => setAddrData({ ...addrData, street: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Nr *</label>
                <input 
                  required
                  type="text" 
                  value={addrData.houseNumber}
                  onChange={e => setAddrData({ ...addrData, houseNumber: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Postcode</label>
                <input 
                  type="text" 
                  value={addrData.postalCode}
                  onChange={e => setAddrData({ ...addrData, postalCode: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Woonplaats *</label>
                <input 
                  required
                  type="text" 
                  value={addrData.city}
                  onChange={e => setAddrData({ ...addrData, city: e.target.value })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            </div>
          </section>

          {/* Section: Contact Details */}
          <section className="space-y-4 pt-4 border-t border-gray-100">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Contactgegevens</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Telefoonnummer</label>
                <input 
                  type="tel" 
                  value={formData.phones?.[0] || ''}
                  onChange={e => setFormData({ ...formData, phones: [e.target.value] })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">E-mailadres</label>
                <input 
                  type="email" 
                  value={formData.emails?.[0] || ''}
                  onChange={e => setFormData({ ...formData, emails: [e.target.value] })}
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            </div>
          </section>

          {/* Section: Extras (Pets & Hobbies) */}
          <section className="space-y-6 pt-4 border-t border-gray-100">
            <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Extra Informatie</h3>

            {/* Hobbies Tag Input */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
                <Heart size={14} className="text-purple-500" /> Hobby's
              </label>
              <div className="flex gap-2 mb-3">
                <input 
                  placeholder="Typ een hobby en druk op Enter..." 
                  className="flex-1 px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-purple-500 transition-all" 
                  value={hobbyInput} 
                  onChange={e => setHobbyInput(e.target.value)}
                  onKeyDown={handleHobbyKeyDown}
                />
                <button 
                  type="button"
                  onClick={addHobby}
                  className="p-2 bg-purple-100 text-purple-600 rounded-xl hover:bg-purple-200 transition-colors"
                >
                  <Plus size={20} />
                </button>
              </div>
              <div className="flex flex-wrap gap-2 min-h-[32px]">
                {formData.hobbies?.map((hobby, i) => (
                  <span key={i} className="flex items-center gap-1 bg-purple-100 text-purple-700 px-3 py-1 rounded-full text-xs font-bold border border-purple-200 animate-in zoom-in-50 duration-200">
                    {hobby}
                    <button type="button" onClick={() => removeHobby(i)} className="hover:text-purple-900 transition-colors">
                      <X size={12}/>
                    </button>
                  </span>
                ))}
                {(!formData.hobbies || formData.hobbies.length === 0) && (
                  <span className="text-xs text-gray-400 italic">Nog geen hobby's toegevoegd.</span>
                )}
              </div>
            </div>

            {/* Huisdieren */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Huisdieren</label>
              <div className="flex gap-2 mb-3">
                <input placeholder="Soort (bijv. Hond)" className="flex-1 px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm" value={newPet.type} onChange={e => setNewPet({...newPet, type: e.target.value})} />
                <input placeholder="Naam" className="flex-1 px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl text-sm" value={newPet.name} onChange={e => setNewPet({...newPet, name: e.target.value})} />
                <button 
                  type="button"
                  onClick={() => {
                    if (newPet.name) {
                      setFormData({...formData, pets: [...(formData.pets || []), newPet]});
                      setNewPet({type:'', name:''});
                    }
                  }}
                  className="p-2 bg-blue-100 text-blue-600 rounded-xl hover:bg-blue-200 transition-colors"
                ><Plus size={20}/></button>
              </div>
              <div className="flex flex-wrap gap-2 min-h-[32px]">
                {formData.pets?.map((p, i) => (
                  <span key={i} className="flex items-center gap-1 bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold border border-blue-200">
                    {p.name} ({p.type})
                    <button type="button" onClick={() => setFormData({...formData, pets: formData.pets?.filter((_, idx) => idx !== i)})} className="hover:text-blue-900 transition-colors">
                      <X size={12}/>
                    </button>
                  </span>
                ))}
                {(!formData.pets || formData.pets.length === 0) && (
                  <span className="text-xs text-gray-400 italic">Nog geen huisdieren toegevoegd.</span>
                )}
              </div>
            </div>

            {/* Notes */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Notities / Bijzonderheden</label>
              <textarea 
                rows={3}
                value={formData.notes}
                onChange={e => setFormData({ ...formData, notes: e.target.value })}
                className="w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none"
                placeholder="Bijv. eet geen varkensvlees, allergisch voor pollen..."
              />
            </div>
          </section>
        </form>

        <div className="p-6 border-t border-gray-100 flex items-center justify-end gap-3 bg-white sticky bottom-0 z-10">
          <button 
            type="button"
            onClick={onClose}
            className="px-6 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-700 transition-colors"
          >
            Annuleren
          </button>
          <button 
            onClick={handleSubmit}
            className="px-8 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-bold text-sm transition-all shadow-lg flex items-center gap-2 active:scale-95"
          >
            <Save size={18} />
            Opslaan
          </button>
        </div>
      </div>
    </div>
  );
};

export default ContactForm;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Map as MapIcon, 
  Users, 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Plus, 
  Search, 
  Filter,
  LogOut,
  Bell,
  Settings,
  ChevronRight,
  ChevronLeft
} from 'lucide-react';
import { Contact, Address, ContactType, ViewMode, Relation } from './types';
import { DEFAULT_TYPES, INITIAL_CONTACTS, INITIAL_ADDRESSES } from './constants';
import MapView from './components/MapView';
import ContactList from './components/ContactList';
import Dashboard from './components/Dashboard';
import StatsView from './components/StatsView';
import ContactForm from './components/ContactForm';
import ContactDetails from './components/ContactDetails';
import CalendarView from './components/CalendarView';

const App: React.FC = () => {
  const [contacts, setContacts] = useState<Contact[]>(() => {
    const saved = localStorage.getItem('contacts');
    return saved ? JSON.parse(saved) : INITIAL_CONTACTS;
  });
  const [addresses, setAddresses] = useState<Address[]>(() => {
    const saved = localStorage.getItem('addresses');
    return saved ? JSON.parse(saved) : INITIAL_ADDRESSES;
  });
  const [types, setTypes] = useState<ContactType[]>(() => {
    const saved = localStorage.getItem('types');
    return saved ? JSON.parse(saved) : DEFAULT_TYPES;
  });
  const [relations, setRelations] = useState<Relation[]>(() => {
    const saved = localStorage.getItem('relations');
    return saved ? JSON.parse(saved) : [];
  });

  const [viewMode, setViewMode] = useState<ViewMode>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [initialCoords, setInitialCoords] = useState<[number, number] | null>(null);

  // Persistence
  useEffect(() => localStorage.setItem('contacts', JSON.stringify(contacts)), [contacts]);
  useEffect(() => localStorage.setItem('addresses', JSON.stringify(addresses)), [addresses]);
  useEffect(() => localStorage.setItem('types', JSON.stringify(types)), [types]);
  useEffect(() => localStorage.setItem('relations', JSON.stringify(relations)), [relations]);

  const filteredContacts = useMemo(() => {
    const q = searchQuery.toLowerCase();
    return contacts.filter(c => {
      const addr = addresses.find(a => a.id === c.addressId);
      return (
        c.firstName.toLowerCase().includes(q) ||
        c.lastName.toLowerCase().includes(q) ||
        (addr?.city || '').toLowerCase().includes(q) ||
        (addr?.street || '').toLowerCase().includes(q)
      );
    });
  }, [contacts, addresses, searchQuery]);

  const handleAddContact = (coords?: [number, number]) => {
    setInitialCoords(coords || null);
    setEditContact(null);
    setIsFormOpen(true);
  };

  const handleEditContact = (contact: Contact) => {
    setEditContact(contact);
    setIsFormOpen(true);
  };

  const handleDeleteContact = (id: string) => {
    if (confirm('Weet je zeker dat je dit contact wilt verwijderen?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
      setSelectedContactId(null);
    }
  };

  const saveContact = (contact: Contact, address: Address) => {
    setAddresses(prev => {
      const exists = prev.find(a => a.id === address.id);
      return exists ? prev.map(a => a.id === address.id ? address : a) : [...prev, address];
    });
    setContacts(prev => {
      const exists = prev.find(c => c.id === contact.id);
      return exists ? prev.map(c => c.id === contact.id ? contact : c) : [...prev, contact];
    });
    setIsFormOpen(false);
  };

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      {/* Sidebar */}
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label="Kaart" 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label="Contacten" 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label="Dashboard" 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label="Verjaardagen" 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label="Statistieken" 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        <div className="p-4 border-t border-gray-100">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center justify-center p-2 rounded-lg hover:bg-gray-100 text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative min-w-0">
        {/* Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 z-40 shrink-0">
          <div className="flex-1 max-w-xl">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Zoek contacten, adressen..." 
                className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-full focus:ring-2 focus:ring-blue-500 text-sm transition-all"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4 ml-4">
            <button 
              onClick={() => handleAddContact()}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-full font-medium text-sm transition-all shadow-md active:scale-95"
            >
              <Plus size={18} />
              <span className="hidden sm:inline">Nieuw Contact</span>
            </button>
            <div className="h-8 w-px bg-gray-200" />
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Bell size={20} /></button>
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Settings size={20} /></button>
            <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold text-xs ring-2 ring-white">JD</div>
          </div>
        </header>

        {/* Dynamic Content */}
        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'map' && (
            <MapView 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
              onMapClick={handleAddContact}
            />
          )}
          {viewMode === 'list' && (
            <ContactList 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
            />
          )}
          {viewMode === 'dashboard' && (
            <Dashboard 
              contacts={contacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
            />
          )}
          {viewMode === 'calendar' && (
            <CalendarView 
              contacts={contacts}
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
            />
          )}
          {viewMode === 'stats' && (
            <StatsView 
              contacts={contacts} 
              types={types} 
            />
          )}

          {/* Contact Details Slider */}
          {selectedContactId && (
            <ContactDetails 
              contact={contacts.find(c => c.id === selectedContactId)!}
              address={addresses.find(a => a.id === contacts.find(c => c.id === selectedContactId)?.addressId)!}
              type={types.find(t => t.id === contacts.find(c => c.id === selectedContactId)?.typeId)!}
              otherResidents={contacts.filter(c => c.addressId === contacts.find(curr => curr.id === selectedContactId)?.addressId && c.id !== selectedContactId)}
              onClose={() => setSelectedContactId(null)}
              onEdit={handleEditContact}
              onDelete={handleDeleteContact}
            />
          )}
        </div>
      </main>

      {/* Forms and Modals */}
      {isFormOpen && (
        <ContactForm 
          contact={editContact}
          types={types}
          addresses={addresses}
          initialCoords={initialCoords}
          onClose={() => setIsFormOpen(false)}
          onSave={saveContact}
        />
      )}
    </div>
  );
};

