import React, { useMemo } from 'react';
import { Gift, MapPin, Users, Heart, ArrowRight, UserPlus, Calendar } from 'lucide-react';
import { Contact, Address, ContactType } from '../types';

interface DashboardProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  onAddContact: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ contacts, addresses, types, onContactClick, onAddContact }) => {
  const upcomingBirthdays = useMemo(() => {
    const today = new Date();
    return contacts
      .filter(c => c.birthDate)
      .map(c => {
        const bday = new Date(c.birthDate!);
        const currentYearBday = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
        const nextBday = currentYearBday < today 
          ? new Date(today.getFullYear() + 1, bday.getMonth(), bday.getDate())
          : currentYearBday;

        const diff = Math.ceil((nextBday.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        const age = nextBday.getFullYear() - bday.getFullYear();

        return { ...c, daysUntil: diff, nextAge: age };
      })
      .sort((a, b) => a.daysUntil - b.daysUntil)
      .slice(0, 5);
  }, [contacts]);

  const stats = [
    { label: 'Totaal Contacten', value: contacts.length, icon: <Users size={24} />, color: 'bg-blue-500' },
    { label: 'Unieke Adressen', value: addresses.length, icon: <MapPin size={24} />, color: 'bg-emerald-500' },
    { label: 'Favorieten', value: contacts.filter(c => c.isFavorite).length, icon: <Heart size={24} />, color: 'bg-red-500' },
    { label: 'Jarigen deze maand', value: contacts.filter(c => c.birthDate && new Date(c.birthDate).getMonth() === new Date().getMonth()).length, icon: <Gift size={24} />, color: 'bg-amber-500' },
  ];

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div>
        <h2 className="text-3xl font-bold text-gray-900 mb-1">Welkom terug!</h2>
        <p className="text-gray-500">Hier is een overzicht van je netwerk op dit moment.</p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 group hover:shadow-md transition-shadow">
            <div className={`p-3 rounded-2xl ${stat.color} text-white shadow-inner group-hover:scale-110 transition-transform`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
              <p className="text-2xl font-black text-gray-900">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              <Gift className="text-amber-500" /> Komende Verjaardagen
            </h3>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {upcomingBirthdays.length > 0 ? upcomingBirthdays.map(c => {
              const typeColor = types.find(t => t.id === c.typeId)?.color || '#3b82f6';
              return (
                <div 
                  key={c.id} 
                  onClick={() => onContactClick(c.id)}
                  className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4 cursor-pointer hover:bg-gray-50 hover:border-blue-200 transition-all group"
                >
                  <div className="relative">
                    <img 
