                      className={`w-full px-4 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all ${addrData.id ? 'opacity-70 cursor-not-allowed bg-blue-50/50' : ''}`}
