import React, { useState, useEffect, useMemo } from 'react';
import { 
  Map as MapIcon, 
  Users, 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Plus, 
  Search, 
  Filter,
  LogOut,
  Bell,
  Settings,
  ChevronRight,
  ChevronLeft
} from 'lucide-react';
import { Contact, Address, ContactType, ViewMode, Relation } from './types';
import { DEFAULT_TYPES, INITIAL_CONTACTS, INITIAL_ADDRESSES } from './constants';
import MapView from './components/MapView';
import ContactList from './components/ContactList';
import Dashboard from './components/Dashboard';
import StatsView from './components/StatsView';
import ContactForm from './components/ContactForm';
import ContactDetails from './components/ContactDetails';
import CalendarView from './components/CalendarView';

const App: React.FC = () => {
  const [contacts, setContacts] = useState<Contact[]>(() => {
    const saved = localStorage.getItem('contacts');
    return saved ? JSON.parse(saved) : INITIAL_CONTACTS;
  });
  const [addresses, setAddresses] = useState<Address[]>(() => {
    const saved = localStorage.getItem('addresses');
    return saved ? JSON.parse(saved) : INITIAL_ADDRESSES;
  });
  const [types, setTypes] = useState<ContactType[]>(() => {
    const saved = localStorage.getItem('types');
    return saved ? JSON.parse(saved) : DEFAULT_TYPES;
  });
  const [relations, setRelations] = useState<Relation[]>(() => {
    const saved = localStorage.getItem('relations');
    return saved ? JSON.parse(saved) : [];
  });

  const [viewMode, setViewMode] = useState<ViewMode>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [initialCoords, setInitialCoords] = useState<[number, number] | null>(null);
  const [initialAddressId, setInitialAddressId] = useState<string | null>(null);

  // Persistence
  useEffect(() => localStorage.setItem('contacts', JSON.stringify(contacts)), [contacts]);
  useEffect(() => localStorage.setItem('addresses', JSON.stringify(addresses)), [addresses]);
  useEffect(() => localStorage.setItem('types', JSON.stringify(types)), [types]);
  useEffect(() => localStorage.setItem('relations', JSON.stringify(relations)), [relations]);

  const filteredContacts = useMemo(() => {
    const q = searchQuery.toLowerCase();
    return contacts.filter(c => {
      const addr = addresses.find(a => a.id === c.addressId);
      return (
        c.firstName.toLowerCase().includes(q) ||
        (c.lastName || '').toLowerCase().includes(q) ||
        (addr?.city || '').toLowerCase().includes(q) ||
        (addr?.street || '').toLowerCase().includes(q)
      );
    });
  }, [contacts, addresses, searchQuery]);

  const handleAddContact = (coords?: [number, number], addressId?: string) => {
    setInitialCoords(coords || null);
    setInitialAddressId(addressId || null);
    setEditContact(null);
    setIsFormOpen(true);
  };

  const handleEditContact = (contact: Contact) => {
    setEditContact(contact);
    setInitialAddressId(null);
    setInitialCoords(null);
    setIsFormOpen(true);
  };

  const handleDeleteContact = (id: string) => {
    if (confirm('Weet je zeker dat je dit contact wilt verwijderen?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
      setSelectedContactId(null);
    }
  };

  const handleSetMapAvatar = (addressId: string, contactId: string) => {
    setAddresses(prev => prev.map(a => 
      a.id === addressId ? { ...a, mapAvatarId: contactId } : a
    ));
  };

  const saveContact = (contact: Contact, address: Address) => {
    setAddresses(prev => {
      const exists = prev.find(a => a.id === address.id);
      return exists ? prev.map(a => a.id === address.id ? address : a) : [...prev, address];
    });
    setContacts(prev => {
      const exists = prev.find(c => c.id === contact.id);
      return exists ? prev.map(c => c.id === contact.id ? contact : c) : [...prev, contact];
    });
    setIsFormOpen(false);
  };

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      {/* Sidebar */}
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label="Kaart" 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label="Contacten" 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label="Dashboard" 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label="Verjaardagen" 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label="Statistieken" 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        <div className="p-4 border-t border-gray-100">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center justify-center p-2 rounded-lg hover:bg-gray-100 text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative min-w-0">
        {/* Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 z-40 shrink-0">
          <div className="flex-1 max-w-xl">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Zoek contacten, adressen..." 
                className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-full focus:ring-2 focus:ring-blue-500 text-sm transition-all"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4 ml-4">
            <button 
              onClick={() => handleAddContact()}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-full font-medium text-sm transition-all shadow-md active:scale-95"
            >
              <Plus size={18} />
              <span className="hidden sm:inline">Nieuw Contact</span>
            </button>
            <div className="h-8 w-px bg-gray-200" />
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Bell size={20} /></button>
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Settings size={20} /></button>
            <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold text-xs ring-2 ring-white">JD</div>
          </div>
        </header>

        {/* Dynamic Content */}
        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'map' && (
            <MapView 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
              onMapClick={handleAddContact}
              onAddResident={(addrId) => handleAddContact(undefined, addrId)}
            />
          )}
          {viewMode === 'list' && (
            <ContactList 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
            />
          )}
          {viewMode === 'dashboard' && (
            <Dashboard 
              contacts={contacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
              onAddContact={() => handleAddContact()}
            />
          )}
          {viewMode === 'calendar' && (
            <CalendarView 
              contacts={contacts}
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
            />
          )}
          {viewMode === 'stats' && (
            <StatsView 
              contacts={contacts} 
              types={types} 
              addresses={addresses}
            />
          )}

          {/* Contact Details Slider */}
          {selectedContactId && (
            <ContactDetails 
              contact={contacts.find(c => c.id === selectedContactId)!}
              address={addresses.find(a => a.id === contacts.find(c => c.id === selectedContactId)?.addressId)!}
              type={types.find(t => t.id === contacts.find(c => c.id === selectedContactId)?.typeId)!}
              otherResidents={contacts.filter(c => c.addressId === contacts.find(curr => curr.id === selectedContactId)?.addressId && c.id !== selectedContactId)}
              onClose={() => setSelectedContactId(null)}
              onEdit={handleEditContact}
              onDelete={handleDeleteContact}
              onAddResident={(addrId) => handleAddContact(undefined, addrId)}
              onSetMapAvatar={handleSetMapAvatar}
            />
          )}
        </div>
      </main>

      {/* Forms and Modals */}
      {isFormOpen && (
        <ContactForm 
          contact={editContact}
          types={types}
          addresses={addresses}
          contacts={contacts}
          initialCoords={initialCoords}
          initialAddressId={initialAddressId}
          onClose={() => setIsFormOpen(false)}
          onSave={saveContact}
        />
      )}
    </div>
  );
};

interface NavItemProps {
  icon: React.ReactNode;
  label: string;
  active?: boolean;
  expanded?: boolean;
  onClick: () => void;
}

const NavItem: React.FC<NavItemProps> = ({ icon, label, active, expanded, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 p-3 rounded-lg transition-all ${
      active 
        ? 'bg-blue-50 text-blue-600 shadow-sm' 
        : 'text-gray-500 hover:bg-gray-100 hover:text-gray-900'
    }`}
  >
    <span className={`${active ? 'text-blue-600' : 'text-gray-400'}`}>{icon}</span>
    {expanded && <span className="font-medium text-sm">{label}</span>}
    {active && expanded && <div className="ml-auto w-1.5 h-1.5 bg-blue-600 rounded-full" />}
  </button>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  X, Save, Camera, Plus, Trash, RefreshCw, 
  Image as ImageIcon, Upload, Loader2, Heart, 
  MapPin, Users, Search, Phone, Mail, Calendar, 
  Dog, Info 
} from 'lucide-react';
import { Contact, Address, ContactType, Pet } from '../types';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  contacts: Contact[];
  initialCoords: [number, number] | null;
  initialAddressId: string | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, contacts, initialCoords, initialAddressId, onClose, onSave 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingAddress, setIsLoadingAddress] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');
  const [addressSearch, setAddressSearch] = useState('');
  const [isChoosingExisting, setIsChoosingExisting] = useState(false);

  const [formData, setFormData] = useState<Partial<Contact>>(() => {
    const base = contact || {
      firstName: '',
      lastName: '',
      phones: [''],
      emails: [''],
      typeId: types[0].id,
      notes: '',
      isFavorite: false,
      pets: [],
      hobbies: [],
      photoUrl: ''
    };

    if (!contact && initialAddressId) {
      const existingResident = contacts.find(c => c.addressId === initialAddressId);
      if (existingResident) {
        return { ...base, lastName: existingResident.lastName || '' };
      }
    }
    return base;
  });

  const [addrData, setAddrData] = useState<Partial<Address>>(() => {
    if (contact?.addressId) return addresses.find(a => a.id === contact.addressId) || {};
    if (initialAddressId) return addresses.find(a => a.id === initialAddressId) || {};
    return {
      street: '',
      houseNumber: '',
      postalCode: '',
      city: '',
      lat: initialCoords ? initialCoords[0] : 52.37,
      lng: initialCoords ? initialCoords[1] : 4.89,
      country: 'Nederland'
    };
  });

  const filteredAddresses = useMemo(() => {
    if (!addressSearch) return addresses;
    const q = addressSearch.toLowerCase();
    return addresses.filter(a => 
      a.street.toLowerCase().includes(q) || 
      a.city.toLowerCase().includes(q) || 
      a.postalCode.toLowerCase().includes(q)
    );
  }, [addresses, addressSearch]);

  const currentResidents = useMemo(() => {
    if (!addrData.id) return [];
    return contacts.filter(c => c.addressId === addrData.id && c.id !== contact?.id);
  }, [addrData.id, contacts, contact?.id]);

  useEffect(() => {
    if (initialCoords && !initialAddressId && !isChoosingExisting) {
      const [lat, lng] = initialCoords;
      setIsLoadingAddress(true);
      fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&addressdetails=1`)
        .then(res => res.json())
        .then(data => {
          const addr = data.address;
          setAddrData(prev => ({
            ...prev,
            street: addr.road || addr.pedestrian || addr.suburb || addr.neighbourhood || '',
            houseNumber: addr.house_number || '',
            postalCode: addr.postcode || '',
            city: addr.city || addr.town || addr.village || addr.municipality || '',
            lat,
            lng
          }));
        })
        .catch(() => setAddrData(prev => ({ ...prev, lat, lng })))
        .finally(() => setIsLoadingAddress(false));
    }
  }, [initialCoords, initialAddressId, isChoosingExisting]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    let finalAddr = { ...addrData };

    if (!addrData.id && !initialCoords) {
      try {
        const query = `${addrData.street} ${addrData.houseNumber}, ${addrData.postalCode}, ${addrData.city}, ${addrData.country}`;
        const response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`);
        const data = await response.json();
        if (data && data.length > 0) {
          finalAddr.lat = parseFloat(data[0].lat);
          finalAddr.lng = parseFloat(data[0].lon);
        }
      } catch (error) {
        console.error("Geocoding failed, falling back to defaults", error);
      }
    }

    const addressId = addrData.id || `addr-${Date.now()}`;
    const finalAddress: Address = { ...finalAddr as Address, id: addressId };
    const finalContact: Contact = {
      ...formData as Contact,
      id: contact?.id || `c-${Date.now()}`,
      addressId,
      updatedAt: new Date().toISOString(),
      createdAt: contact?.createdAt || new Date().toISOString(),
      interactions: contact?.interactions || []
    };

    onSave(finalContact, finalAddress);
    setIsSaving(false);
  };

  const selectedType = types.find(t => t.id === formData.typeId) || types[0];
  const initials = `${formData.firstName?.[0] || '?'}${formData.lastName?.[0] || ''}`.toUpperCase();

  return (
    <div className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[150] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden bg-gray-100">
          <img 
            src={`https://picsum.photos/seed/${addrData.id || 'new'}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          onClick={onClose}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white flex items-center justify-center"
              style={{ borderColor: selectedType.color }}
            >
              {formData.photoUrl ? (
                <img src={formData.photoUrl} alt="Preview" className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl">
                  {initials}
                </div>
              )}
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white rounded-full">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1">WIJZIG</span>
              </div>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
          </div>
          <div className="pb-2">
            <button 
              type="button"
              onClick={() => setFormData({...formData, isFavorite: !formData.isFavorite})}
              className={`p-2 rounded-full shadow-sm border transition-all ${formData.isFavorite ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-gray-300 border-gray-200'}`}
            >
              <Heart size={20} className={formData.isFavorite ? 'fill-current' : ''} />
            </button>
          </div>
        </div>

        <div className="px-6 mt-4">
          <h2 className="text-2xl font-bold text-gray-900 leading-tight">
            {formData.firstName || formData.lastName ? `${formData.firstName} ${formData.lastName || ''}`.trim() : 'Nieuw Contact'}
          </h2>
          <div className="mt-2 flex items-center gap-2">
            <select 
              value={formData.typeId}
              onChange={e => setFormData({ ...formData, typeId: e.target.value })}
              className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white cursor-pointer hover:brightness-110 transition-all outline-none border-none shadow-sm"
              style={{ backgroundColor: selectedType.color }}
            >
              {types.map(t => <option key={t.id} value={t.id} className="text-gray-900 bg-white">{t.name}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-32">
        <div className="space-y-4">
          <FormInput icon={<Users size={18} />} label="Voornaam" value={formData.firstName} onChange={v => setFormData({...formData, firstName: v})} placeholder="Bijv. Jan" />
          <FormInput icon={<Users size={18} />} label="Achternaam (optioneel)" value={formData.lastName} onChange={v => setFormData({...formData, lastName: v})} placeholder="Bijv. Jansen" />
          <FormInput icon={<Calendar size={18} />} label="Geboortedatum" type="date" value={formData.birthDate} onChange={v => setFormData({...formData, birthDate: v})} />
        </div>

        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">Contactgegevens</h3>
          <FormInput icon={<Phone size={18} />} label="Telefoon" value={formData.phones?.[0]} onChange={v => setFormData({...formData, phones: [v]})} placeholder="06..." />
          <FormInput icon={<Mail size={18} />} label="E-mail" value={formData.emails?.[0]} onChange={v => setFormData({...formData, emails: [v]})} placeholder="voorbeeld@mail.com" />
        </div>

        <div className="space-y-4 pt-4 border-t border-gray-100">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">Locatie & Adres</h3>
            <button 
              type="button" 
              onClick={() => setIsChoosingExisting(!isChoosingExisting)}
              className="text-[10px] font-bold text-blue-600 hover:text-blue-700 transition-colors uppercase tracking-tight"
            >
              {isChoosingExisting ? 'Handmatig invoeren' : 'Bestaand adres zoeken'}
            </button>
          </div>

          {isChoosingExisting ? (
            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 space-y-3">
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input 
                  className="w-full pl-9 pr-4 py-2 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none" 
                  placeholder="Zoek adres..." 
                  value={addressSearch}
                  onChange={e => setAddressSearch(e.target.value)}
                />
              </div>
              <div className="max-h-40 overflow-y-auto space-y-2 pr-1">
                {filteredAddresses.map(addr => (
                  <button 
                    key={addr.id} 
                    type="button"
                    onClick={() => { setAddrData(addr); setIsChoosingExisting(false); }}
                    className="w-full text-left p-2 hover:bg-blue-50 bg-white border border-gray-100 rounded-lg text-xs font-semibold flex items-center gap-2 transition-colors"
                  >
                    <MapPin size={12} className="text-blue-500" />
                    {addr.street} {addr.houseNumber}, {addr.city}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className={`space-y-3 ${addrData.id ? 'bg-blue-50/30 p-4 rounded-2xl border border-blue-100' : ''}`}>
              <div className="grid grid-cols-4 gap-2">
                <div className="col-span-3">
                  <FormInput label="Straat" value={addrData.street} onChange={v => setAddrData({...addrData, street: v})} disabled={!!addrData.id} />
                </div>
                <div>
                  <FormInput label="Nr" value={addrData.houseNumber} onChange={v => setAddrData({...addrData, houseNumber: v})} disabled={!!addrData.id} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <FormInput label="Postcode" value={addrData.postalCode} onChange={v => setAddrData({...addrData, postalCode: v})} disabled={!!addrData.id} />
                <FormInput label="Stad" value={addrData.city} onChange={v => setAddrData({...addrData, city: v})} disabled={!!addrData.id} />
              </div>
              {addrData.id && !initialAddressId && (
                <button type="button" onClick={() => setAddrData({...addrData, id: undefined})} className="text-[9px] font-black text-blue-600 uppercase hover:underline">
