        <div className="grid grid-cols-1 gap-4">
          <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 space-y-4">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Dog size={14} /> Huisdieren</div>
            </h4>
            <div className="flex gap-2">
              <input 
                className="flex-1 bg-white border border-blue-200 rounded-lg px-3 py-1 text-xs outline-none" 
                placeholder="Naam (Soort)" 
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    const [name, type] = e.currentTarget.value.split(' ');
                    if (name) setFormData({...formData, pets: [...(formData.pets || []), {name, type: type || '?'}]});
                    e.currentTarget.value = '';
                  }
                }}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.pets?.map((p, i) => (
                <span key={i} className="text-[10px] font-bold bg-white text-blue-700 px-2 py-1 rounded-lg border border-blue-200 flex items-center gap-1">
                  {p.name} <button type="button" onClick={() => setFormData({...formData, pets: formData.pets?.filter((_, idx) => idx !== i)})}><X size={10}/></button>
                </span>
              ))}
            </div>
          </div>

          <div className="bg-purple-50/50 p-4 rounded-2xl border border-purple-100 space-y-4">
            <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Heart size={14} /> Hobby's</div>
            </h4>
