        </div>

        <div className="px-6 mt-4">
          <h2 className="text-2xl font-bold text-gray-900 leading-tight">{`${contact.firstName} ${contact.lastName || ''}`.trim()}</h2>
          <span 
            className="inline-block mt-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white"
            style={{ backgroundColor: type.color }}
          >
            {type.name}
          </span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-20 mt-4">
        <div className="space-y-4">
          <DetailItem icon={<Phone size={18} />} label="Telefoon" value={contact.phones[0] || 'Geen nummer'} />
          <DetailItem icon={<Mail size={18} />} label="E-mail" value={contact.emails[0] || 'Geen e-mail'} />
          <DetailItem 
