        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2">
            <Info size={16} /> Bijzonderheden
          </h3>
          <div className="bg-yellow-50 p-4 rounded-2xl border border-yellow-100 text-sm text-gray-700 leading-relaxed italic">
            "{contact.notes || 'Geen notities'}"
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center justify-between">
            <div className="flex items-center gap-2"><Clock size={16} /> Historie</div>
            <button className="text-blue-600 hover:text-blue-700 lowercase">+ log</button>
          </h3>
          <div className="space-y-4 relative before:absolute before:left-[11px] before:top-2 before:bottom-0 before:w-0.5 before:bg-gray-100">
            {contact.interactions.length > 0 ? (
              contact.interactions.map(log => (
                <div key={log.id} className="relative pl-8">
                  <div className="absolute left-0 top-1 w-6 h-6 bg-white border-2 border-blue-500 rounded-full flex items-center justify-center z-10">
                    <MessageSquare size={10} className="text-blue-500" />
