import React, { useState } from 'react';
import { ChevronLeft, ChevronRight, Gift } from 'lucide-react';
import { Contact, ContactType } from '../types';

interface CalendarViewProps {
  contacts: Contact[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ contacts, types, onContactClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const monthNames = [
    'Januari', 'Februari', 'Maart', 'April', 'Mei', 'Juni',
    'Juli', 'Augustus', 'September', 'Oktober', 'November', 'December'
  ];

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const days = [];
  const totalDays = daysInMonth(year, month);
  const startOffset = (firstDayOfMonth(year, month) + 6) % 7; 

  for (let i = 0; i < startOffset; i++) {
    days.push(null);
  }

  for (let d = 1; d <= totalDays; d++) {
    days.push(d);
  }

  const handlePrevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  return (
    <div className="p-8 max-w-5xl mx-auto space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-3xl font-bold text-gray-900">{monthNames[month]} {year}</h2>
          <p className="text-gray-500">Plan je sociale uitjes en verjaardagskaarten.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={handlePrevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors border border-gray-200"><ChevronLeft size={20}/></button>
          <button onClick={() => setCurrentDate(new Date())} className="px-4 py-2 hover:bg-gray-100 rounded-xl transition-colors border border-gray-200 font-bold text-sm">Vandaag</button>
          <button onClick={handleNextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors border border-gray-200"><ChevronRight size={20}/></button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden flex flex-col">
        <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-100">
          {['Ma', 'Di', 'Wo', 'Do', 'Vr', 'Za', 'Zo'].map(day => (
            <div key={day} className="py-4 text-center text-xs font-black text-gray-400 uppercase tracking-widest">{day}</div>
          ))}
        </div>

        <div className="flex-1 grid grid-cols-7 grid-rows-5 overflow-auto">
          {days.map((day, idx) => {
            const birthdayContacts = day ? contacts.filter(c => {
              if (!c.birthDate) return false;
              const bday = new Date(c.birthDate);
              return bday.getDate() === day && bday.getMonth() === month;
            }) : [];

            return (
              <div 
                key={idx} 
                className={`min-h-[120px] p-2 border-r border-b border-gray-50 flex flex-col gap-1 transition-colors ${day ? 'hover:bg-blue-50/20' : 'bg-gray-50/30'}`}
              >
                {day && (
                  <>
                    <span className={`text-sm font-bold ${day === new Date().getDate() && month === new Date().getMonth() ? 'bg-blue-600 text-white w-7 h-7 flex items-center justify-center rounded-full' : 'text-gray-400'}`}>
                      {day}
                    </span>
                    <div className="space-y-1">
                      {birthdayContacts.map(c => {
                        const typeColor = types.find(t => t.id === c.typeId)?.color || '#fef3c7';
                        return (
                          <div 
                            key={c.id} 
                            onClick={() => onContactClick(c.id)}
                            className="flex items-center gap-1.5 p-1.5 bg-amber-50 rounded-lg cursor-pointer hover:bg-amber-100 transition-colors border border-amber-100"
                          >
                            <img 
                              src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} 
                              className="w-5 h-5 rounded-full border" 
                              style={{ borderColor: typeColor }}
                            />
                            <span className="text-[10px] font-bold text-amber-800 truncate">{c.firstName}</span>
                          </div>
                        );
                      })}
                    </div>
                  </>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

