          {isChoosingExisting ? (
            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 space-y-3">
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input 
                  className="w-full pl-9 pr-4 py-2 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none" 
                  placeholder="Zoek adres..." 
                  value={addressSearch}
                  onChange={e => setAddressSearch(e.target.value)}
                />
              </div>
              <div className="max-h-40 overflow-y-auto space-y-2 pr-1">
                {filteredAddresses.map(addr => (
                  <button 
                    key={addr.id} 
                    type="button"
                    onClick={() => { setAddrData(addr); setIsChoosingExisting(false); }}
                    className="w-full text-left p-2 hover:bg-blue-50 bg-white border border-gray-100 rounded-lg text-xs font-semibold flex items-center gap-2 transition-colors"
                  >
                    <MapPin size={12} className="text-blue-500" />
                    {addr.street} {addr.houseNumber}, {addr.city}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className={`space-y-3 ${addrData.id ? 'bg-blue-50/30 p-4 rounded-2xl border border-blue-100' : ''}`}>
              <div className="grid grid-cols-4 gap-2">
                <div className="col-span-3">
                  <FormInput label="Straat" value={addrData.street} onChange={v => setAddrData({...addrData, street: v})} disabled={!!addrData.id} />
                </div>
                <div>
                  <FormInput label="Nr" value={addrData.houseNumber} onChange={v => setAddrData({...addrData, houseNumber: v})} disabled={!!addrData.id} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <FormInput label="Postcode" value={addrData.postalCode} onChange={v => setAddrData({...addrData, postalCode: v})} disabled={!!addrData.id} />
                <FormInput label="Stad" value={addrData.city} onChange={v => setAddrData({...addrData, city: v})} disabled={!!addrData.id} />
              </div>
              {addrData.id && !initialAddressId && (
                <button type="button" onClick={() => setAddrData({...addrData, id: undefined})} className="text-[9px] font-black text-blue-600 uppercase hover:underline">
                  Adres loskoppelen
                </button>
              )}
            </div>
          )}
        </div>

        {currentResidents.length > 0 && (
          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} /> Huidige Bewoners
            </h3>
            <div className="flex flex-wrap gap-2">
              {currentResidents.map(res => (
                <div key={res.id} className="flex items-center gap-2 bg-emerald-50 border border-emerald-100 px-2 py-1 rounded-lg">
                  <img src={res.photoUrl || `https://ui-avatars.com/api/?name=${res.firstName}+${res.lastName || ''}`} className="w-5 h-5 rounded-full" />
                  <span className="text-[10px] font-bold text-emerald-800">{res.firstName} {res.lastName || ''}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4">
          <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 space-y-4">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Dog size={14} /> Huisdieren</div>
            </h4>
            <div className="flex gap-2">
              <input 
                className="flex-1 bg-white border border-blue-200 rounded-lg px-3 py-1 text-xs outline-none" 
                placeholder="Naam (Soort)" 
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    const [name, type] = e.currentTarget.value.split(' ');
                    if (name) setFormData({...formData, pets: [...(formData.pets || []), {name, type: type || '?'}]});
                    e.currentTarget.value = '';
                  }
                }}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.pets?.map((p, i) => (
                <span key={i} className="text-[10px] font-bold bg-white text-blue-700 px-2 py-1 rounded-lg border border-blue-200 flex items-center gap-1">
                  {p.name} <button type="button" onClick={() => setFormData({...formData, pets: formData.pets?.filter((_, idx) => idx !== i)})}><X size={10}/></button>
                </span>
              ))}
            </div>
          </div>

          <div className="bg-purple-50/50 p-4 rounded-2xl border border-purple-100 space-y-4">
            <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Heart size={14} /> Hobby's</div>
            </h4>
            <div className="flex gap-2">
              <input 
                className="flex-1 bg-white border border-purple-200 rounded-lg px-3 py-1 text-xs outline-none" 
                placeholder="Nieuwe hobby..." 
                value={hobbyInput}
                onChange={e => setHobbyInput(e.target.value)}
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    if (hobbyInput.trim()) setFormData({...formData, hobbies: [...(formData.hobbies || []), hobbyInput.trim()]});
                    setHobbyInput('');
                  }
                }}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.hobbies?.map((h, i) => (
                <span key={i} className="text-[10px] font-bold bg-purple-100 text-purple-700 px-2 py-1 rounded-lg border border-purple-200 flex items-center gap-1">
                  {h} <button type="button" onClick={() => setFormData({...formData, hobbies: formData.hobbies?.filter((_, idx) => idx !== i)})}><X size={10}/></button>
                </span>
              ))}
            </div>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2">
            <div className="flex items-center gap-1"><Info size={16} /> Bijzonderheden</div>
          </h3>
          <textarea 
            className="w-full bg-yellow-50 p-4 rounded-2xl border border-yellow-100 text-sm text-gray-700 leading-relaxed italic outline-none focus:ring-2 focus:ring-yellow-200 resize-none min-h-[100px]"
            placeholder="Schrijf hier bijzonderheden op..."
            value={formData.notes}
            onChange={e => setFormData({...formData, notes: e.target.value})}
          />
        </div>
      </div>

      <div className="shrink-0 p-6 border-t border-gray-100 bg-white/80 backdrop-blur-md sticky bottom-0 z-[160] flex items-center justify-end gap-3 shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">
        <button 
          onClick={onClose}
          className="px-6 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-700 transition-colors"
          disabled={isSaving}
        >
          Annuleren
        </button>
        <button 
          onClick={handleSubmit}
          className="px-8 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-bold text-sm transition-all shadow-lg flex items-center gap-2 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed min-w-[120px] justify-center"
          disabled={isSaving || !formData.firstName || !addrData.street}
        >
          {isSaving ? (
            <>
              <Loader2 size={18} className="animate-spin" />
              Verwerken...
            </>
          ) : (
            <>
              <Save size={18} />
              Opslaan
            </>
          )}
        </button>
      </div>
    </div>
  );
};

interface FormInputProps {
  icon?: React.ReactNode;
  label: string;
  value?: string;
  onChange: (v: string) => void;
  placeholder?: string;
  type?: string;
  disabled?: boolean;
}

const FormInput: React.FC<FormInputProps> = ({ icon, label, value, onChange, placeholder, type = 'text', disabled }) => (
  <div className={`flex items-start gap-4 group ${disabled ? 'opacity-70' : ''}`}>
    {icon && (
      <div className="p-2.5 bg-gray-50 rounded-xl text-gray-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors mt-1">
        {icon}
      </div>
    )}
    <div className="flex-1 min-w-0">
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{label}</p>
      <input 
        type={type}
        value={value || ''}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className={`w-full text-sm font-semibold text-gray-800 bg-transparent border-b border-gray-100 focus:border-blue-500 outline-none pb-1 transition-all ${disabled ? 'cursor-not-allowed' : ''}`}
      />
    </div>
  </div>
);

export default ContactForm;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Map as MapIcon, 
  Users, 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Plus, 
  Search, 
  Filter,
  LogOut,
  Bell,
  Settings,
  ChevronRight,
  ChevronLeft,
  Download,
  Upload
} from 'lucide-react';
import { Contact, Address, ContactType, ViewMode, Relation } from './types';
import { DEFAULT_TYPES, INITIAL_CONTACTS, INITIAL_ADDRESSES } from './constants';
import MapView from './components/MapView';
import ContactList from './components/ContactList';
import Dashboard from './components/Dashboard';
import StatsView from './components/StatsView';
import ContactForm from './components/ContactForm';
import ContactDetails from './components/ContactDetails';
import CalendarView from './components/CalendarView';

const App: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [contacts, setContacts] = useState<Contact[]>(() => {
    const saved = localStorage.getItem('contacts');
    return saved ? JSON.parse(saved) : INITIAL_CONTACTS;
  });
  const [addresses, setAddresses] = useState<Address[]>(() => {
    const saved = localStorage.getItem('addresses');
    return saved ? JSON.parse(saved) : INITIAL_ADDRESSES;
  });
  const [types, setTypes] = useState<ContactType[]>(() => {
    const saved = localStorage.getItem('types');
    return saved ? JSON.parse(saved) : DEFAULT_TYPES;
  });
  const [relations, setRelations] = useState<Relation[]>(() => {
    const saved = localStorage.getItem('relations');
    return saved ? JSON.parse(saved) : [];
  });

  const [viewMode, setViewMode] = useState<ViewMode>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [initialCoords, setInitialCoords] = useState<[number, number] | null>(null);
  const [initialAddressId, setInitialAddressId] = useState<string | null>(null);

  // Persistence
  useEffect(() => localStorage.setItem('contacts', JSON.stringify(contacts)), [contacts]);
  useEffect(() => localStorage.setItem('addresses', JSON.stringify(addresses)), [addresses]);
  useEffect(() => localStorage.setItem('types', JSON.stringify(types)), [types]);
  useEffect(() => localStorage.setItem('relations', JSON.stringify(relations)), [relations]);

  const filteredContacts = useMemo(() => {
    const q = searchQuery.toLowerCase();
    return contacts.filter(c => {
      const addr = addresses.find(a => a.id === c.addressId);
      return (
        c.firstName.toLowerCase().includes(q) ||
        (c.lastName || '').toLowerCase().includes(q) ||
        (addr?.city || '').toLowerCase().includes(q) ||
        (addr?.street || '').toLowerCase().includes(q)
      );
    });
  }, [contacts, addresses, searchQuery]);

  const handleAddContact = (coords?: [number, number], addressId?: string) => {
    setInitialCoords(coords || null);
    setInitialAddressId(addressId || null);
    setEditContact(null);
    setIsFormOpen(true);
  };

  const handleEditContact = (contact: Contact) => {
    setEditContact(contact);
    setInitialAddressId(null);
    setInitialCoords(null);
    setIsFormOpen(true);
  };

  const handleDeleteContact = (id: string) => {
    if (confirm('Weet je zeker dat je dit contact wilt verwijderen?')) {
      setContacts(prev => prev.filter(c => c.id !== id));
      setSelectedContactId(null);
    }
  };

  const handleSetMapAvatar = (addressId: string, contactId: string) => {
    setAddresses(prev => prev.map(a => 
      a.id === addressId ? { ...a, mapAvatarId: contactId } : a
    ));
  };

  const saveContact = (contact: Contact, address: Address) => {
    setAddresses(prev => {
      const exists = prev.find(a => a.id === address.id);
      return exists ? prev.map(a => a.id === address.id ? address : a) : [...prev, address];
    });
    setContacts(prev => {
      const exists = prev.find(c => c.id === contact.id);
      return exists ? prev.map(c => c.id === contact.id ? contact : c) : [...prev, contact];
    });
    setIsFormOpen(false);
  };

  // Data Management Functions
  const handleExportData = () => {
    const data = {
      contacts,
      addresses,
      types,
      relations,
      version: '1.6',
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mapcrm_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (confirm('Waarschuwing: Alle huidige gegevens worden overschreven door dit bestand. Wil je doorgaan?')) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          // Basic validation
          if (data.contacts && Array.isArray(data.contacts) && data.addresses && Array.isArray(data.addresses)) {
            setContacts(data.contacts);
            setAddresses(data.addresses);
            if (data.types) setTypes(data.types);
            if (data.relations) setRelations(data.relations);
            alert('Import succesvol voltooid!');
          } else {
            alert('Fout: Ongeldige bestandsstructuur.');
          }
        } catch (err) {
          alert('Fout: Kan bestand niet lezen als JSON.');
        }
      };
      reader.readAsText(file);
    }
    // Clear input so same file can be imported twice if needed
    e.target.value = '';
  };

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      {/* Sidebar */}
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1 overflow-y-auto">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label="Kaart" 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label="Contacten" 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label="Dashboard" 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label="Verjaardagen" 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label="Statistieken" 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        {/* Data Actions */}
        <div className="px-2 pt-4 border-t border-gray-100 flex flex-col gap-1">
          <NavItem 
            icon={<Download size={20} />} 
            label="Exporteer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleExportData} 
          />
          <NavItem 
            icon={<Upload size={20} />} 
            label="Importeer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={() => fileInputRef.current?.click()} 
          />
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportData} 
            accept=".json" 
            className="hidden" 
          />
        </div>

        <div className="p-4">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center justify-center p-2 rounded-lg hover:bg-gray-100 text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative min-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 z-40 shrink-0">
          <div className="flex-1 max-w-xl">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Zoek contacten, adressen..." 
                className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-full focus:ring-2 focus:ring-blue-500 text-sm transition-all"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4 ml-4">
            <button 
