    const file = e.target.files?.[0];
    if (!file) return;

    if (confirm('Waarschuwing: Alle huidige gegevens worden overschreven door dit bestand. Wil je doorgaan?')) {
      const reader = new FileReader();
      reader.onload = (event) => {
        try {
          const data = JSON.parse(event.target?.result as string);
          // Basic validation
          if (data.contacts && Array.isArray(data.contacts) && data.addresses && Array.isArray(data.addresses)) {
            setContacts(data.contacts);
            setAddresses(data.addresses);
            if (data.types) setTypes(data.types);
            if (data.relations) setRelations(data.relations);
            alert('Import succesvol voltooid!');
          } else {
            alert('Fout: Ongeldige bestandsstructuur.');
          }
        } catch (err) {
          alert('Fout: Kan bestand niet lezen als JSON.');
        }
      };
      reader.readAsText(file);
    }
    // Clear input so same file can be imported twice if needed
    e.target.value = '';
  };

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      {/* Sidebar */}
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1 overflow-y-auto">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label="Kaart" 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label="Contacten" 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label="Dashboard" 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label="Verjaardagen" 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label="Statistieken" 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        {/* Data Actions */}
        <div className="px-2 pt-4 border-t border-gray-100 flex flex-col gap-1">
          <NavItem 
            icon={<Download size={20} />} 
            label="Exporteer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleExportData} 
          />
          <NavItem 
            icon={<Upload size={20} />} 
            label="Importeer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={() => fileInputRef.current?.click()} 
          />
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportData} 
            accept=".json" 
            className="hidden" 
          />
        </div>

        <div className="p-4">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center justify-center p-2 rounded-lg hover:bg-gray-100 text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative min-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 z-40 shrink-0">
          <div className="flex-1 max-w-xl">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Zoek contacten, adressen..." 
                className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-full focus:ring-2 focus:ring-blue-500 text-sm transition-all"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4 ml-4">
            <button 
              onClick={() => handleAddContact()}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-full font-medium text-sm transition-all shadow-md active:scale-95"
            >
              <Plus size={18} />
              <span className="hidden sm:inline">Nieuw Contact</span>
            </button>
            <div className="h-8 w-px bg-gray-200" />
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Bell size={20} /></button>
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Settings size={20} /></button>
            <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold text-xs ring-2 ring-white">JD</div>
          </div>
        </header>

        {/* Dynamic Content */}
        <div className="flex-1 relative overflow-hidden">
          {viewMode === 'map' && (
            <MapView 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
              onMapClick={handleAddContact}
              onAddResident={(addrId) => handleAddContact(undefined, addrId)}
            />
          )}
          {viewMode === 'list' && (
            <ContactList 
              contacts={filteredContacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => setSelectedContactId(id)}
            />
          )}
          {viewMode === 'dashboard' && (
            <Dashboard 
              contacts={contacts} 
              addresses={addresses} 
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
              onAddContact={() => handleAddContact()}
            />
          )}
          {viewMode === 'calendar' && (
            <CalendarView 
              contacts={contacts}
              types={types}
              onContactClick={(id) => {
                setSelectedContactId(id);
                setViewMode('map');
              }}
            />
          )}
          {viewMode === 'stats' && (
            <StatsView 
              contacts={contacts} 
              types={types} 
              addresses={addresses}
            />
          )}

          {/* Contact Details Slider - Rendered only if all data is valid */}
          {selectedContact && selectedAddress && selectedType && (
            <ContactDetails 
              contact={selectedContact}
              address={selectedAddress}
              type={selectedType}
              otherResidents={otherResidents}
              onClose={() => setSelectedContactId(null)}
              onEdit={handleEditContact}
              onDelete={handleDeleteContact}
              onAddResident={(addrId) => handleAddContact(undefined, addrId)}
              onSetMapAvatar={handleSetMapAvatar}
            />
          )}
        </div>
      </main>

      {/* Forms and Modals */}
      {isFormOpen && (
        <ContactForm 
          contact={editContact}
          types={types}
          addresses={addresses}
          contacts={contacts}
          initialCoords={initialCoords}
          initialAddressId={initialAddressId}
          onClose={() => setIsFormOpen(false)}
          onSave={saveContact}
        />
      )}
    </div>
  );
};

