const MapEvents = ({ onMapClick }: { onMapClick: (coords: [number, number]) => void }) => {
  useMapEvents({
    click(e) {
      onMapClick([e.latlng.lat, e.latlng.lng]);
    },
  });
  return null;
};

/**
 * Fixes a common Leaflet issue where the map doesn't calculate its container size 
 * correctly if it's rendered inside a hidden element or during a layout transition.
 */
const MapResizeHandler = () => {
  const map = useMap();

  useEffect(() => {
    // Initial invalidation
    map.invalidateSize();

    // Delayed invalidation to ensure the flex layout has finalized
    const timer = setTimeout(() => {
      map.invalidateSize();
    }, 250);

    return () => clearTimeout(timer);
  }, [map]);

  return null;
};

