import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Contact, ContactType, Address } from '../types';

interface StatsViewProps {
  contacts: Contact[];
  types: ContactType[];
  addresses: Address[];
}

const StatsView: React.FC<StatsViewProps> = ({ contacts, types, addresses }) => {
  // Sort type data so the largest group is always at the top/first for the summary text
  const typeData = types.map(t => ({
    name: t.name,
    value: contacts.filter(c => c.typeId === t.id).length,
    color: t.color
  }))
  .filter(d => d.value > 0)
  .sort((a, b) => b.value - a.value);

  // Real city distribution logic
  const cityCounts = contacts.reduce((acc: Record<string, number>, contact) => {
    const addr = addresses.find(a => a.id === contact.addressId);
    const city = addr?.city || 'Onbekend';
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const cityData = Object.entries(cityCounts)
    .map(([city, count]) => ({ city, count: count as number }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5); // Show top 5 cities

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-10 pb-24">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Type Distribution */}
          <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Type Verdeling</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={typeData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={100}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {typeData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  />
                  <Legend verticalAlign="bottom" height={36}/>
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* City Distribution */}
          <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Top Locaties</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={cityData}>
                  <XAxis dataKey="city" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}} 
                    contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  />
                  <Bar dataKey="count" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        <div className="bg-blue-600 rounded-3xl p-10 text-white flex flex-col items-center text-center shadow-2xl shadow-blue-200 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
            <div className="absolute -top-20 -left-20 w-64 h-64 bg-white rounded-full blur-3xl" />
            <div className="absolute -bottom-20 -right-20 w-64 h-64 bg-white rounded-full blur-3xl" />
          </div>
          <h2 className="text-3xl font-bold mb-4 relative z-10">Inzicht in je netwerk</h2>
          <p className="max-w-2xl text-blue-100 text-lg leading-relaxed relative z-10">
            Je hebt momenteel <strong>{contacts.length}</strong> actieve contacten verspreid over <strong>{Object.keys(cityCounts).length}</strong> verschillende steden. 
            De grootste groep contacten zijn <strong>{typeData[0]?.name || 'n.v.t.'}</strong> ({typeData[0]?.value || 0}). 
            Zorg dat je je favorieten ({contacts.filter(c => c.isFavorite).length}) regelmatig een berichtje stuurt!
          </p>
        </div>
      </div>
    </div>
  );
};

