  </div>
);

export default ContactDetails;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  X, Save, Camera, Plus, Trash, RefreshCw, 
  ImageIcon, Upload, Loader2, Heart, 
  MapPin, Users, Search, Phone, Mail, Calendar, 
  Dog, Info, GitPullRequest, Trash2, Baby,
  Facebook, Instagram, Linkedin, Clock
} from 'lucide-react';
import { Contact, Address, ContactType, Pet, Relation, RelationType, ContactChild, SocialLinks } from '../types';
import { compressImageBase64 } from '../utils';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  contacts: Contact[];
  relations: Relation[];
  initialCoords: [number, number] | null;
  initialAddressId: string | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address, relations: Relation[]) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, contacts, relations, initialCoords, initialAddressId, onClose, onSave 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingAddress, setIsLoadingAddress] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');
  const [addressSearch, setAddressSearch] = useState('');
  const [relationSearch, setRelationSearch] = useState('');
  const [isChoosingExisting, setIsChoosingExisting] = useState(false);

  const [formData, setFormData] = useState<Partial<Contact>>(() => {
    const base = contact || {
      firstName: '',
      lastName: '',
      phones: [''],
      emails: [''],
      typeId: types[0].id,
      notes: '',
      isFavorite: false,
      pets: [],
      children: [],
      socialLinks: {},
      hobbies: [],
      photoUrl: '',
      lastInteractionDate: ''
    };

    if (!contact && initialAddressId) {
      const existingResident = contacts.find(c => c.addressId === initialAddressId);
      if (existingResident) {
        return { ...base, lastName: existingResident.lastName || '' };
      }
    }
    return base;
  });

  const [addrData, setAddrData] = useState<Partial<Address>>(() => {
    if (contact?.addressId) return addresses.find(a => a.id === contact.addressId) || {};
    if (initialAddressId) return addresses.find(a => a.id === initialAddressId) || {};
    return {
      street: '',
      houseNumber: '',
      postalCode: '',
      city: '',
      lat: initialCoords ? initialCoords[0] : 52.37,
      lng: initialCoords ? initialCoords[1] : 4.89,
      country: 'Nederland'
    };
  });

  const [localRelations, setLocalRelations] = useState<Relation[]>(() => {
    if (!contact) return [];
    return relations.filter(r => r.contactAId === contact.id || r.contactBId === contact.id);
  });

  const filteredAddresses = useMemo(() => {
    if (!addressSearch) return addresses;
    const q = addressSearch.toLowerCase();
    return addresses.filter(a => 
      a.street.toLowerCase().includes(q) || 
      a.city.toLowerCase().includes(q) || 
      a.postalCode.toLowerCase().includes(q)
    );
  }, [addresses, addressSearch]);

  const filteredContactsForRelation = useMemo(() => {
    if (!relationSearch) return [];
    const q = relationSearch.toLowerCase();
    const currentContactId = contact?.id || 'new';
    return contacts
      .filter(c => c.id !== currentContactId)
      .filter(c => !localRelations.some(r => r.contactAId === c.id || r.contactBId === c.id))
      .filter(c => 
        c.firstName.toLowerCase().includes(q) || 
        (c.lastName || '').toLowerCase().includes(q)
      )
      .slice(0, 5);
  }, [contacts, relationSearch, localRelations, contact?.id]);

  const currentResidents = useMemo(() => {
    if (!addrData.id) return [];
    return contacts.filter(c => c.addressId === addrData.id && c.id !== contact?.id);
  }, [addrData.id, contacts, contact?.id]);

  useEffect(() => {
    if (initialCoords && !initialAddressId && !isChoosingExisting) {
      const [lat, lng] = initialCoords;
      setIsLoadingAddress(true);
      fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&addressdetails=1`)
        .then(res => res.json())
        .then(data => {
          const addr = data.address;
          setAddrData(prev => ({
            ...prev,
            street: addr.road || addr.pedestrian || addr.suburb || addr.neighbourhood || '',
            houseNumber: addr.house_number || '',
            postalCode: addr.postcode || '',
            city: addr.city || addr.town || addr.village || addr.municipality || '',
            lat,
            lng
          }));
        })
        .catch(() => setAddrData(prev => ({ ...prev, lat, lng })))
        .finally(() => setIsLoadingAddress(false));
    }
  }, [initialCoords, initialAddressId, isChoosingExisting]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        // Compress image before storing in state
        const compressed = await compressImageBase64(base64);
        setFormData({ ...formData, photoUrl: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddRelation = (otherContact: Contact, type: RelationType) => {
    const currentId = contact?.id || 'new-temp-id';
    const newRel: Relation = {
      id: `rel-${Date.now()}-${Math.random()}`,
      contactAId: currentId,
      contactBId: otherContact.id,
      type,
      createdAt: new Date().toISOString()
    };
    setLocalRelations([...localRelations, newRel]);
    setRelationSearch('');
  };

  const handleRemoveRelation = (relId: string) => {
    setLocalRelations(localRelations.filter(r => r.id !== relId));
  };

  const handleAddChild = () => {
    const newChild: ContactChild = { name: '', birthDate: '' };
    setFormData({ ...formData, children: [...(formData.children || []), newChild] });
  };

  const handleUpdateChild = (idx: number, field: keyof ContactChild, value: string) => {
    const updatedChildren = [...(formData.children || [])];
    updatedChildren[idx] = { ...updatedChildren[idx], [field]: value };
    setFormData({ ...formData, children: updatedChildren });
  };

  const handleRemoveChild = (idx: number) => {
    setFormData({ ...formData, children: (formData.children || []).filter((_, i) => i !== idx) });
  };

  const handleUpdateSocial = (field: keyof SocialLinks, value: string) => {
    setFormData({
      ...formData,
      socialLinks: {
        ...(formData.socialLinks || {}),
        [field]: value
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    let finalAddr = { ...addrData };
    if (!addrData.id && !initialCoords) {
      try {
        const queryParts = [addrData.street, addrData.houseNumber, addrData.postalCode, addrData.city, addrData.country]
          .filter(p => !!p && p.trim() !== '');
        let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(queryParts.join(', '))}&limit=1`);
        let data = await response.json();
        if (data && data.length > 0) {
          finalAddr.lat = parseFloat(data[0].lat);
          finalAddr.lng = parseFloat(data[0].lon);
        }
      } catch (error) {
        console.error("Geocoding failed", error);
      }
    }

    const addressId = addrData.id || `addr-${Date.now()}`;
    const finalAddress: Address = { ...finalAddr as Address, id: addressId };

    const contactId = contact?.id || `c-${Date.now()}`;
    const finalContact: Contact = {
      ...formData as Contact,
      id: contactId,
      addressId,
      updatedAt: new Date().toISOString(),
      createdAt: contact?.createdAt || new Date().toISOString(),
      interactions: contact?.interactions || []
    };

    // Update local relations with the actual contact ID if it was new
    const finalRelations = localRelations.map(r => ({
      ...r,
      contactAId: r.contactAId === 'new-temp-id' ? contactId : r.contactAId,
      contactBId: r.contactBId === 'new-temp-id' ? contactId : r.contactBId
    }));

    onSave(finalContact, finalAddress, finalRelations);
    setIsSaving(false);
  };

  const selectedType = types.find(t => t.id === formData.typeId) || types[0];
  const initials = `${formData.firstName?.[0] || '?'}${formData.lastName?.[0] || ''}`.toUpperCase();

  return (
    <div className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[150] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden bg-gray-100">
          <img 
            src={`https://picsum.photos/seed/${addrData.id || 'new'}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          onClick={onClose}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white flex items-center justify-center"
              style={{ borderColor: selectedType.color }}
            >
              {formData.photoUrl ? (
                <img src={formData.photoUrl} alt="Preview" className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl">
                  {initials}
                </div>
              )}
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white rounded-full">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1">WIJZIG</span>
              </div>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
          </div>
          <div className="pb-2">
            <button 
              type="button"
              onClick={() => setFormData({...formData, isFavorite: !formData.isFavorite})}
              className={`p-2 rounded-full shadow-sm border transition-all ${formData.isFavorite ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-gray-300 border-gray-200'}`}
            >
              <Heart size={20} className={formData.isFavorite ? 'fill-current' : ''} />
            </button>
          </div>
        </div>

        <div className="px-6 mt-4">
          <h2 className="text-2xl font-bold text-gray-900 leading-tight">
            {formData.firstName || formData.lastName ? `${formData.firstName} ${formData.lastName || ''}`.trim() : 'Nieuw Contact'}
          </h2>
          <div className="mt-2 flex items-center gap-2">
            <select 
              value={formData.typeId}
              onChange={e => setFormData({ ...formData, typeId: e.target.value })}
              className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white cursor-pointer hover:brightness-110 transition-all outline-none border-none shadow-sm"
              style={{ backgroundColor: selectedType.color }}
            >
              {types.map(t => <option key={t.id} value={t.id} className="text-gray-900 bg-white">{t.name}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-32">
        <div className="space-y-4">
          <FormInput icon={<Users size={18} />} label="Voornaam" value={formData.firstName} onChange={v => setFormData({...formData, firstName: v})} placeholder="Bijv. Jan" />
          <FormInput icon={<Users size={18} />} label="Achternaam (optioneel)" value={formData.lastName} onChange={v => setFormData({...formData, lastName: v})} placeholder="Bijv. Jansen" />
          <FormInput icon={<Calendar size={18} />} label="Geboortedatum" type="date" value={formData.birthDate} onChange={v => setFormData({...formData, birthDate: v})} />
          <FormInput icon={<Clock size={18} />} label="Laatste Interactie" type="date" value={formData.lastInteractionDate?.split('T')[0]} onChange={v => setFormData({...formData, lastInteractionDate: v ? new Date(v).toISOString() : ''})} />
        </div>

        {/* Social Media Sectie */}
        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            Social Media
          </h3>
          <div className="space-y-3 bg-gray-50/50 p-4 rounded-2xl border border-gray-100">
            <FormInput icon={<Facebook size={18} />} label="Facebook URL" value={formData.socialLinks?.facebook} onChange={v => handleUpdateSocial('facebook', v)} placeholder="https://facebook.com/..." />
            <FormInput icon={<Instagram size={18} />} label="Instagram URL" value={formData.socialLinks?.instagram} onChange={v => handleUpdateSocial('instagram', v)} placeholder="https://instagram.com/..." />
            <FormInput icon={<Linkedin size={18} />} label="LinkedIn URL" value={formData.socialLinks?.linkedin} onChange={v => handleUpdateSocial('linkedin', v)} placeholder="https://linkedin.com/in/..." />
          </div>
        </div>

        {/* Relaties Sectie */}
        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <GitPullRequest size={14} /> Relaties & Familie
          </h3>

          <div className="space-y-3 bg-gray-50 p-4 rounded-2xl border border-gray-100">
            <div className="relative">
              <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input 
                className="w-full pl-9 pr-4 py-2 bg-white border border-gray-200 rounded-xl text-[11px] focus:ring-2 focus:ring-blue-500 outline-none" 
                placeholder="Zoek contact om te koppelen..." 
                value={relationSearch}
                onChange={e => setRelationSearch(e.target.value)}
              />
            </div>

            {filteredContactsForRelation.length > 0 && (
              <div className="space-y-2">
                {filteredContactsForRelation.map(c => (
                  <div key={c.id} className="p-2 bg-white border border-gray-100 rounded-lg flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <img src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} className="w-6 h-6 rounded-full" />
                      <span className="text-xs font-bold text-gray-700">{c.firstName} {c.lastName}</span>
                    </div>
                    <select 
                      className="text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded border-none cursor-pointer outline-none"
                      onChange={(e) => handleAddRelation(c, e.target.value as RelationType)}
                      defaultValue=""
                    >
                      <option value="" disabled>Voeg toe als...</option>
                      {Object.values(RelationType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-2 mt-4">
              {localRelations.map(rel => {
                const otherId = rel.contactAId === (contact?.id || 'new-temp-id') ? rel.contactBId : rel.contactAId;
                const other = contacts.find(c => c.id === otherId);
                if (!other) return null;
                return (
                  <div key={rel.id} className="flex items-center justify-between bg-white px-3 py-2 rounded-xl border border-gray-200 shadow-sm">
                    <div className="flex items-center gap-2">
                      <img src={other.photoUrl || `https://ui-avatars.com/api/?name=${other.firstName}+${other.lastName || ''}`} className="w-6 h-6 rounded-full" />
                      <div>
                        <p className="text-[10px] font-bold text-gray-900 leading-none">{other.firstName} {other.lastName}</p>
                        <p className="text-[8px] font-bold text-blue-500 uppercase tracking-tighter">{rel.type}</p>
                      </div>
                    </div>
                    <button type="button" onClick={() => handleRemoveRelation(rel.id)} className="text-gray-300 hover:text-red-500 transition-colors">
                      <Trash2 size={14} />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Kinderen Sectie */}
        <div className="space-y-4 pt-4 border-t border-gray-100">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Baby size={14} /> Kinderen
            </h3>
            <button 
              type="button" 
              onClick={handleAddChild}
              className="text-[10px] font-bold text-blue-600 hover:text-blue-700 transition-colors uppercase tracking-tight flex items-center gap-1"
            >
              <Plus size={12} /> toevoegen
            </button>
          </div>

          <div className="space-y-3">
            {formData.children?.map((child, idx) => (
              <div key={idx} className="bg-pink-50/30 p-4 rounded-2xl border border-pink-100 space-y-3 relative group/child">
                <button 
                  type="button" 
                  onClick={() => handleRemoveChild(idx)}
                  className="absolute top-2 right-2 p-1 text-gray-300 hover:text-red-500 transition-colors"
                >
                  <X size={14} />
                </button>
                <div className="space-y-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-[9px] font-black text-pink-400 uppercase tracking-widest mb-1">Naam Kind</p>
                    <input 
                      className="w-full text-xs font-semibold text-gray-800 bg-transparent border-b border-pink-100 focus:border-pink-300 outline-none pb-1"
                      placeholder="Naam..."
                      value={child.name}
                      onChange={e => handleUpdateChild(idx, 'name', e.target.value)}
                    />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-[9px] font-black text-pink-400 uppercase tracking-widest mb-1">Geboortedatum (optioneel)</p>
                    <input 
                      type="date"
                      className="w-full text-xs font-semibold text-gray-800 bg-transparent border-b border-pink-100 focus:border-pink-300 outline-none pb-1"
                      value={child.birthDate || ''}
                      onChange={e => handleUpdateChild(idx, 'birthDate', e.target.value)}
                    />
                  </div>
                </div>
              </div>
            ))}
            {(!formData.children || formData.children.length === 0) && (
              <p className="text-[10px] text-gray-400 italic text-center py-2">Geen kinderen toegevoegd</p>
            )}
          </div>
        </div>

        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">Contactgegevens</h3>
          <FormInput icon={<Phone size={18} />} label="Telefoon" value={formData.phones?.[0]} onChange={v => setFormData({...formData, phones: [v]})} placeholder="06..." />
          <FormInput icon={<Mail size={18} />} label="E-mail" value={formData.emails?.[0]} onChange={v => setFormData({...formData, emails: [v]})} placeholder="voorbeeld@mail.com" />
        </div>

        <div className="space-y-4 pt-4 border-t border-gray-100">
          <div className="flex items-center justify-between">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">Locatie & Adres</h3>
            <button 
              type="button" 
              onClick={() => setIsChoosingExisting(!isChoosingExisting)}
              className="text-[10px] font-bold text-blue-600 hover:text-blue-700 transition-colors uppercase tracking-tight"
            >
              {isChoosingExisting ? 'Handmatig invoeren' : 'Bestaand adres zoeken'}
            </button>
          </div>

          {isChoosingExisting ? (
            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 space-y-3">
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                <input 
                  className="w-full pl-9 pr-4 py-2 bg-white border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none" 
                  placeholder="Zoek adres..." 
                  value={addressSearch}
                  onChange={e => setAddressSearch(e.target.value)}
                />
              </div>
              <div className="max-h-40 overflow-y-auto space-y-2 pr-1">
                {filteredAddresses.map(addr => (
                  <button 
                    key={addr.id} 
                    type="button"
                    onClick={() => { setAddrData(addr); setIsChoosingExisting(false); }}
                    className="w-full text-left p-2 hover:bg-blue-50 bg-white border border-gray-100 rounded-lg text-xs font-semibold flex items-center gap-2 transition-colors"
                  >
                    <MapPin size={12} className="text-blue-500" />
                    {addr.street} {addr.houseNumber}, {addr.city}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className={`space-y-3 ${addrData.id ? 'bg-blue-50/30 p-4 rounded-2xl border border-blue-100' : ''}`}>
              <div className="grid grid-cols-4 gap-2">
                <div className="col-span-3">
                  <FormInput label="Straat" value={addrData.street} onChange={v => setAddrData({...addrData, street: v})} disabled={!!addrData.id} />
                </div>
                <div>
                  <FormInput label="Nr" value={addrData.houseNumber} onChange={v => setAddrData({...addrData, houseNumber: v})} disabled={!!addrData.id} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <FormInput label="Postcode" value={addrData.postalCode} onChange={v => setAddrData({...addrData, postalCode: v})} disabled={!!addrData.id} />
                <FormInput label="Stad" value={addrData.city} onChange={v => setAddrData({...addrData, city: v})} disabled={!!addrData.id} />
              </div>
              {addrData.id && !initialAddressId && (
                <button type="button" onClick={() => setAddrData({...addrData, id: undefined})} className="text-[9px] font-black text-blue-600 uppercase hover:underline">
                  Adres loskoppelen
                </button>
              )}
            </div>
          )}
        </div>

        {currentResidents.length > 0 && (
          <div className="space-y-3">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={14} /> Huidige Bewoners op dit adres
            </h3>
            <div className="flex flex-wrap gap-2">
              {currentResidents.map(res => (
                <div key={res.id} className="flex items-center gap-2 bg-emerald-50 border border-emerald-100 px-2 py-1 rounded-lg">
                  <img src={res.photoUrl || `https://ui-avatars.com/api/?name=${res.firstName}+${res.lastName || ''}`} className="w-5 h-5 rounded-full" />
                  <span className="text-[10px] font-bold text-emerald-800">{res.firstName} {res.lastName || ''}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4">
          <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 space-y-4">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Dog size={14} /> Huisdieren</div>
            </h4>
            <div className="flex gap-2">
              <input 
                className="flex-1 bg-white border border-blue-200 rounded-lg px-3 py-1 text-xs outline-none" 
                placeholder="Naam (Soort)" 
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    const [name, type] = e.currentTarget.value.split(' ');
                    if (name) setFormData({...formData, pets: [...(formData.pets || []), {name, type: type || '?'}]});
                    e.currentTarget.value = '';
                  }
                }}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.pets?.map((p, i) => (
                <span key={i} className="text-[10px] font-bold bg-white text-blue-700 px-2 py-1 rounded-lg border border-blue-200 flex items-center gap-1">
                  {p.name} <button type="button" onClick={() => setFormData({...formData, pets: formData.pets?.filter((_, idx) => idx !== i)})}><X size={10}/></button>
                </span>
              ))}
            </div>
          </div>

          <div className="bg-purple-50/50 p-4 rounded-2xl border border-purple-100 space-y-4">
            <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center justify-between">
              <div className="flex items-center gap-1"><Heart size={14} /> Hobby's</div>
            </h4>
            <div className="flex gap-2">
              <input 
                className="flex-1 bg-white border border-purple-200 rounded-lg px-3 py-1 text-xs outline-none" 
                placeholder="Nieuwe hobby..." 
                value={hobbyInput}
                onChange={e => setHobbyInput(e.target.value)}
                onKeyDown={e => {
                  if (e.key === 'Enter') {
                    if (hobbyInput.trim()) setFormData({...formData, hobbies: [...(formData.hobbies || []), hobbyInput.trim()]});
                    setHobbyInput('');
                  }
                }}
              />
            </div>
            <div className="flex flex-wrap gap-2">
              {formData.hobbies?.map((h, i) => (
                <span key={i} className="text-[10px] font-bold bg-purple-100 text-purple-700 px-2 py-1 rounded-lg border border-purple-200 flex items-center gap-1">
                  {h} <button type="button" onClick={() => setFormData({...formData, hobbies: formData.hobbies?.filter((_, idx) => idx !== i)})}><X size={10}/></button>
                </span>
              ))}
            </div>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2">
            <div className="flex items-center gap-1"><Info size={16} /> Bijzonderheden</div>
          </h3>
          <textarea 
            className="w-full bg-yellow-50 p-4 rounded-2xl border border-yellow-100 text-sm text-gray-700 leading-relaxed italic outline-none focus:ring-2 focus:ring-yellow-200 resize-none min-h-[100px]"
            placeholder="Schrijf hier bijzonderheden op..."
            value={formData.notes}
            onChange={e => setFormData({...formData, notes: e.target.value})}
          />
        </div>
      </div>

      <div className="shrink-0 p-6 border-t border-gray-100 bg-white/80 backdrop-blur-md sticky bottom-0 z-[160] flex items-center justify-end gap-3 shadow-[0_-10px_20px_-10px_rgba(0,0,0,0.05)]">
        <button 
          onClick={onClose}
          className="px-6 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-700 transition-colors"
          disabled={isSaving}
        >
          Annuleren
        </button>
        <button 
          onClick={handleSubmit}
          className="px-8 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-bold text-sm transition-all shadow-lg flex items-center gap-2 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed min-w-[120px] justify-center"
          disabled={isSaving || !formData.firstName || !addrData.street}
        >
          {isSaving ? (
            <>
              <Loader2 size={18} className="animate-spin" />
              Verwerken...
            </>
          ) : (
            <>
              <Save size={18} />
              Opslaan
            </>
          )}
        </button>
      </div>
    </div>
  );
};

interface FormInputProps {
  icon?: React.ReactNode;
  label: string;
  value?: string;
  onChange: (v: string) => void;
  placeholder?: string;
  type?: string;
  disabled?: boolean;
}

const FormInput: React.FC<FormInputProps> = ({ icon, label, value, onChange, placeholder, type = 'text', disabled }) => (
  <div className={`flex items-start gap-4 group ${disabled ? 'opacity-70' : ''}`}>
    {icon && (
      <div className="p-2.5 bg-gray-50 rounded-xl text-gray-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors mt-1">
        {icon}
      </div>
    )}
    <div className="flex-1 min-w-0">
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{label}</p>
      <input 
        type={type}
        value={value || ''}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className={`w-full text-sm font-semibold text-gray-800 bg-transparent border-b border-gray-100 focus:border-blue-500 outline-none pb-1 transition-all ${disabled ? 'cursor-not-allowed' : ''}`}
      />
    </div>
  </div>
);

export default ContactForm;

import React, { useState, useMemo } from 'react';
import { 
  Filter, MoreHorizontal, Mail, Phone, 
  MapPin, Star, Heart, Grid, List as ListIcon,
  ChevronDown, Clock
} from 'lucide-react';
import { Contact, Address, ContactType } from '../types';

interface ContactListProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const ContactList: React.FC<ContactListProps> = ({ contacts, addresses, types, onContactClick }) => {
  const [viewStyle, setViewStyle] = useState<'grid' | 'table'>('grid');
  const [selectedTypeId, setSelectedTypeId] = useState<string>('all');

  // Process contacts: Filter by type and sort by last name (fall back to first name)
  const processedContacts = useMemo(() => {
    let result = [...contacts];

    // Filter
    if (selectedTypeId !== 'all') {
      result = result.filter(c => c.typeId === selectedTypeId);
    }

    // Sort by last name (case-insensitive), fallback to first name if last name is missing
    return result.sort((a, b) => {
      const nameA = (a.lastName || a.firstName).toLowerCase();
      const nameB = (b.lastName || b.firstName).toLowerCase();
      return nameA.localeCompare(nameB);
    });
  }, [contacts, selectedTypeId]);

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString) return 'Nooit';
    const last = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - last.getTime());
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Vandaag';
    if (diffDays === 1) return 'Gisteren';
    if (diffDays < 7) return `${diffDays}d geleden`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)}w geleden`;
    return last.toLocaleDateString();
  };

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-6 pb-24">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Contacten Overzicht</h2>
            <p className="text-sm text-gray-500">{processedContacts.length} mensen getoond</p>
          </div>

          <div className="flex items-center gap-3">
            {/* Type Filter */}
            <div className="relative group">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-500 transition-colors">
                <Filter size={14} />
              </div>
              <select 
                value={selectedTypeId}
                onChange={(e) => setSelectedTypeId(e.target.value)}
                className="pl-9 pr-8 py-2 bg-white border border-gray-200 rounded-xl text-xs font-bold text-gray-700 outline-none appearance-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm transition-all cursor-pointer"
              >
                <option value="all">Alle Typen</option>
                {types.map(t => (
                  <option key={t.id} value={t.id}>{t.name}</option>
                ))}
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                <ChevronDown size={14} />
              </div>
            </div>

            <div className="h-8 w-px bg-gray-200" />

            {/* View Toggle */}
            <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-xl">
              <button 
                onClick={() => setViewStyle('grid')}
                className={`p-2 rounded-lg transition-all ${viewStyle === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400 hover:text-gray-600'}`}
                title="Grid weergave"
              >
                <Grid size={18} />
              </button>
              <button 
                onClick={() => setViewStyle('table')}
                className={`p-2 rounded-lg transition-all ${viewStyle === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400 hover:text-gray-600'}`}
                title="Lijst weergave"
              >
                <ListIcon size={18} />
              </button>
            </div>
          </div>
        </div>

        {viewStyle === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {processedContacts.map(contact => {
              const addr = addresses.find(a => a.id === contact.addressId);
              const type = types.find(t => t.id === contact.typeId);
              const displayAddress = addr ? `${addr.street} ${addr.houseNumber}, ${addr.city}` : 'Onbekend';
              return (
                <div 
                  key={contact.id}
                  onClick={() => onContactClick(contact.id)}
                  className="bg-white rounded-3xl p-5 border border-gray-100 shadow-sm hover:shadow-xl hover:border-blue-200 cursor-pointer transition-all group relative"
                >
                  {contact.isFavorite && (
                    <div className="absolute top-4 right-4 text-red-500 fill-current">
                      <Heart size={16} className="fill-current" />
                    </div>
                  )}

                  <div className="flex flex-col items-center text-center">
                    <div className="relative mb-4">
                      <img 
                        src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} 
                        className="w-24 h-24 rounded-3xl object-cover border-4 transition-all shadow-md" 
                        style={{ borderColor: type?.color || '#F3F4F6' }}
                      />
                      <div 
                        className="absolute -bottom-2 right-0 w-6 h-6 rounded-full border-2 border-white shadow-sm"
                        style={{ backgroundColor: type?.color }}
                      />
                    </div>

                    <h3 className="text-lg font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
                      {`${contact.firstName} ${contact.lastName || ''}`.trim()}
                    </h3>
                    <div className="flex items-center gap-1.5 justify-center mb-4">
                      <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{type?.name}</p>
                      <span className="text-gray-300">•</span>
                      <div className="flex items-center gap-1 text-[10px] text-blue-500 font-bold bg-blue-50 px-2 py-0.5 rounded-full">
                         <Clock size={10} /> {getTimeSinceLastContact(contact.lastInteractionDate)}
                      </div>
                    </div>

                    <div className="w-full space-y-2 text-sm">
                      <div className="flex items-center gap-2 text-gray-500 bg-gray-50 p-2 rounded-xl">
                        <MapPin size={14} className="shrink-0" />
                        <span className="truncate">{displayAddress}</span>
                      </div>
                      <div className="flex items-center gap-2 text-gray-500 bg-gray-50 p-2 rounded-xl">
                        <Phone size={14} className="shrink-0" />
                        <span className="truncate">{contact.phones[0] || 'Geen nr'}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[900px]">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest min-w-[250px]">Contact</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Type</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Adres</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Telefoon</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Laatst gezien</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest w-16">Actie</th>
                  </tr>
                </thead>
                <tbody>
                  {processedContacts.map(contact => {
                    const addr = addresses.find(a => a.id === contact.addressId);
                    const type = types.find(t => t.id === contact.typeId);
                    const fullAddress = addr ? `${addr.street} ${addr.houseNumber}, ${addr.city}` : 'Onbekend';
                    return (
                      <tr 
                        key={contact.id} 
                        className="hover:bg-blue-50/30 cursor-pointer transition-colors border-b border-gray-50"
                        onClick={() => onContactClick(contact.id)}
                      >
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            <div className="relative">
                              <img 
                                src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} 
                                className="w-10 h-10 rounded-xl object-cover border-2" 
                                style={{ borderColor: type?.color || '#F3F4F6' }}
                              />
                              {contact.isFavorite && (
                                <div className="absolute -top-1 -right-1 bg-white rounded-full p-0.5 shadow-sm text-red-500">
                                  <Heart size={10} className="fill-current" />
                                </div>
                              )}
                            </div>
                            <span className="font-bold text-gray-900 whitespace-nowrap">
                              {`${contact.firstName} ${contact.lastName || ''}`.trim()}
                            </span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <span 
                            className="px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider text-white whitespace-nowrap"
                            style={{ backgroundColor: type?.color }}
                          >
                            {type?.name}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600">
                          <div className="flex items-center gap-1.5 max-w-[300px]">
                            <span className="truncate">{fullAddress}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600 font-medium whitespace-nowrap">
                          {contact.phones[0] || 'Geen nr'}
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-1.5 text-xs text-blue-600 font-bold">
                            <Clock size={12} /> {getTimeSinceLastContact(contact.lastInteractionDate)}
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          <button className="p-2 hover:bg-gray-100 rounded-lg text-gray-400 transition-colors">
                            <MoreHorizontal size={18} />
                          </button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {processedContacts.length === 0 && (
          <div className="text-center py-20 bg-gray-50 rounded-[2.5rem] border border-dashed border-gray-200">
            <Filter size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-gray-400 font-bold">Geen contacten gevonden voor dit filter.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactList;

export enum ContactCategory {
  FAMILY = 'Familie',
  FRIEND = 'Vriend',
  ACQUAINTANCE = 'Kennis',
  UNKNOWN = 'Onbekend'
}

export interface ContactType {
  id: string;
  name: string;
  color: string;
}

export interface Address {
  id: string;
  street: string;
  houseNumber: string;
  postalCode: string;
  city: string;
  lat: number;
  lng: number;
  country: string;
  mapAvatarId?: string;
}

export interface Pet {
  type: string;
  name: string;
}

export interface ContactChild {
  name: string;
  birthDate?: string;
}

export interface SocialLinks {
  facebook?: string;
  instagram?: string;
  linkedin?: string;
}

export type InteractionMode = 'physical' | 'app' | 'phone' | 'other' | 'interaction';

export interface Interaction {
  id: string;
  type: InteractionMode;
  date: string;
  notes: string;
}

export interface Contact {
  id: string;
  firstName: string;
  lastName?: string;
  photoUrl?: string;
  birthDate?: string;
  addressId: string;
  typeId: string;
  phones: string[];
  emails: string[];
  pets: Pet[];
  children: ContactChild[];
  socialLinks: SocialLinks;
  hobbies: string[];
  notes: string;
  isFavorite: boolean;
  createdAt: string;
  updatedAt: string;
  interactions: Interaction[];
  lastInteractionDate?: string;
}

export enum RelationType {
  PARENT = 'Ouder',
  CHILD = 'Kind',
  PARTNER = 'Partner',
  EX_PARTNER = 'Ex-partner',
  SIBLING = 'Broer/Zus',
  UNCLE_AUNT = 'Oom/Tante',
  NEPHEW_NIECE = 'Neef/Nicht',
  GRANDPARENT = 'Opa/Oma',
  GRANDCHILD = 'Kleinzoon/Kleindochter',
  FRIEND = 'Vriend',
  BEST_FRIEND = 'Beste vriend',
  COLLEAGUE = 'Collega',
  ROOMMATE = 'Huisgenoot'
}

export interface Relation {
  id: string;
  contactAId: string;
  contactBId: string;
  type: RelationType;
  createdAt: string;
}

export type ViewMode = 'map' | 'list' | 'dashboard' | 'calendar' | 'stats';

import React, { useState, useMemo } from 'react';
import { 
  X, Phone, Mail, MapPin, Calendar, Heart, 
  Dog, Info, Edit2, Trash2, Check,
  MessageSquare, ExternalLink, Clock, Users, Plus,
  GitPullRequest, Baby, Facebook, Instagram, Linkedin,
  CheckCircle2, Smartphone, UserCheck
} from 'lucide-react';
import { Contact, Address, ContactType, Relation, Interaction, InteractionMode } from '../types';

interface ContactDetailsProps {
  contact: Contact;
  address: Address;
  type: ContactType;
  contacts: Contact[];
  relations: Relation[];
  otherResidents: Contact[];
  onClose: () => void;
  onEdit: (contact: Contact) => void;
  onDelete: (id: string) => void;
  onAddResident: (addressId: string) => void;
  onSetMapAvatar: (addressId: string, contactId: string) => void;
  onContactClick: (id: string) => void;
}

const ContactDetails: React.FC<ContactDetailsProps> = ({ 
  contact, address, type, contacts, relations, otherResidents, onClose, onEdit, onDelete, onAddResident, onSetMapAvatar, onContactClick
}) => {
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [showInteractionModal, setShowInteractionModal] = useState(false);
  const [newInteractionType, setNewInteractionType] = useState<InteractionMode>('physical');
  const [newInteractionNotes, setNewInteractionNotes] = useState('');

  const initials = `${contact.firstName?.[0] || ''}${contact.lastName?.[0] || ''}`.toUpperCase();
  const allResidents = [...otherResidents, contact].sort((a, b) => a.createdAt.localeCompare(b.createdAt));

  const contactRelations = useMemo(() => {
    return relations
      .filter(r => r.contactAId === contact.id || r.contactBId === contact.id)
      .map(r => {
        const otherId = r.contactAId === contact.id ? r.contactBId : r.contactAId;
        const otherContact = contacts.find(c => c.id === otherId);
        return {
          relation: r,
          contact: otherContact,
          displayType: r.type
        };
      })
      .filter(item => item.contact);
  }, [contact.id, relations, contacts]);

  const isMapAvatar = (contactId: string) => {
    if (address.mapAvatarId) {
      return address.mapAvatarId === contactId;
    }
    return allResidents[0]?.id === contactId;
  };

  const calculateAge = (birthDate: string) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age >= 0 ? age : 0;
  };

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString) return 'Nooit';
    const last = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - last.getTime());
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Vandaag';
    if (diffDays === 1) return 'Gisteren';
    if (diffDays < 7) return `${diffDays} dagen geleden`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weken geleden`;
    return last.toLocaleDateString();
  };

  const handleSaveInteraction = () => {
    const now = new Date().toISOString();
    const newInteraction: Interaction = {
      id: `int-${Date.now()}`,
      type: newInteractionType,
      date: now,
      notes: newInteractionNotes || 'Interactie vastgelegd.'
    };

    const updatedContact: Contact = {
      ...contact,
      lastInteractionDate: now,
      interactions: [newInteraction, ...contact.interactions],
      updatedAt: now
    };

    onEdit(updatedContact);
    setShowInteractionModal(false);
    setNewInteractionNotes('');
    setNewInteractionType('physical');
  };

  const getInteractionIcon = (type: InteractionMode) => {
    switch(type) {
      case 'physical': return <Users size={14} />;
      case 'app': return <Smartphone size={14} />;
      case 'phone': return <Phone size={14} />;
      default: return <MessageSquare size={14} />;
    }
  };

  return (
    <div 
      className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[100] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300"
      onClick={(e) => {
        e.stopPropagation();
        if (isConfirmingDelete) setIsConfirmingDelete(false);
      }}
    >
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden">
          <img 
            src={`https://picsum.photos/seed/${contact.addressId}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onClose();
          }}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="absolute top-4 right-4 flex gap-2 z-20">
          {!isConfirmingDelete ? (
            <>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit(contact);
                }} 
                className="p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all"
                title="Bewerken"
              >
                <Edit2 size={18} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(true);
                }} 
                className="p-2 bg-red-500/80 hover:bg-red-500 backdrop-blur-md text-white rounded-full transition-all shadow-lg"
                title="Verwijderen"
              >
                <Trash2 size={18} />
              </button>
            </>
          ) : (
            <div 
              className="flex items-center bg-red-600 rounded-full p-1 pr-3 gap-2 animate-in zoom-in-75 duration-200 shadow-xl border border-red-400"
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(contact.id);
                }} 
                className="bg-white text-red-600 p-1.5 rounded-full hover:bg-gray-100 transition-colors shadow-sm"
              >
                <Check size={16} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(false);
                }} 
                className="text-white hover:text-red-100 transition-colors"
              >
                <X size={16} />
              </button>
              <span className="text-[10px] text-white font-black uppercase tracking-tight">Wissen?</span>
            </div>
          )}
        </div>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative">
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white"
              style={{ borderColor: type.color }}
            >
              {contact.photoUrl ? (
                <img src={contact.photoUrl} alt={contact.firstName} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl">
                  {initials}
                </div>
              )}
            </div>
            <div 
              className="absolute bottom-1 right-1 w-6 h-6 rounded-full border-2 border-white shadow-sm"
              style={{ backgroundColor: type.color }}
            />
          </div>
          <div className="pb-2 flex flex-col items-center gap-2">
            {contact.isFavorite && (
              <div className="p-2 bg-red-50 rounded-full text-red-500 shadow-sm border border-red-100">
                <Heart size={20} className="fill-current" />
              </div>
            )}
          </div>
        </div>

        <div className="px-6 mt-4 flex items-start justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900 leading-tight">{`${contact.firstName} ${contact.lastName || ''}`.trim()}</h2>
            <span 
              className="inline-block mt-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white"
              style={{ backgroundColor: type.color }}
            >
              {type.name}
            </span>
          </div>
          <div className="flex gap-2 mt-1">
            {contact.socialLinks?.facebook && (
              <a href={contact.socialLinks.facebook} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors">
                <Facebook size={16} />
              </a>
            )}
            {contact.socialLinks?.instagram && (
              <a href={contact.socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-pink-50 text-pink-600 rounded-lg hover:bg-pink-100 transition-colors">
                <Instagram size={16} />
              </a>
            )}
            {contact.socialLinks?.linkedin && (
              <a href={contact.socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-blue-50 text-blue-800 rounded-lg hover:bg-blue-100 transition-colors">
                <Linkedin size={16} />
              </a>
            )}
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-20 mt-4">
        {/* Last Interaction Section */}
        <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 flex items-center justify-between">
          <div>
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Laatst gesproken</p>
            <p className="text-sm font-bold text-blue-900">{getTimeSinceLastContact(contact.lastInteractionDate)}</p>
          </div>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              setShowInteractionModal(true);
            }}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl font-bold text-xs transition-all shadow-md active:scale-95"
          >
            <CheckCircle2 size={14} /> Nu vastleggen
          </button>
        </div>

        <div className="space-y-4">
          <DetailItem icon={<Phone size={18} />} label="Telefoon" value={contact.phones[0] || 'Geen nummer'} />
          <DetailItem icon={<Mail size={18} />} label="E-mail" value={contact.emails[0] || 'Geen e-mail'} />
          <DetailItem 
            icon={<MapPin size={18} />} 
            label="Adres" 
            value={`${address.street} ${address.houseNumber}, ${address.city}`} 
            link={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${address.street} ${address.houseNumber}, ${address.city}`)}`}
          />
          <DetailItem icon={<Calendar size={18} />} label="Jarig op" value={contact.birthDate || 'Niet ingesteld'} />
        </div>

        {/* Interaction Modal (overlay inside details) */}
        {showInteractionModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/20 backdrop-blur-[2px]">
            <div className="bg-white rounded-3xl w-full max-w-[320px] shadow-2xl p-6 border border-gray-100 animate-in zoom-in-95 duration-200">
              <h4 className="text-lg font-bold text-gray-900 mb-4">Interactie vastleggen</h4>

              <div className="space-y-4">
                <div>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Type</p>
                  <div className="grid grid-cols-3 gap-2">
                    <button 
                      onClick={() => setNewInteractionType('physical')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[10px] font-bold transition-all ${newInteractionType === 'physical' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                    >
                      <UserCheck size={16} /> Fysiek
                    </button>
                    <button 
                      onClick={() => setNewInteractionType('app')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[10px] font-bold transition-all ${newInteractionType === 'app' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                    >
                      <Smartphone size={16} /> App
                    </button>
                    <button 
                      onClick={() => setNewInteractionType('phone')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[10px] font-bold transition-all ${newInteractionType === 'phone' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                    >
                      <Phone size={16} /> Bel
                    </button>
                  </div>
                </div>

                <div>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Toelichting</p>
                  <textarea 
                    className="w-full bg-gray-50 border border-gray-100 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-blue-500 min-h-[80px] resize-none"
                    placeholder="Bijv: Op verjaardag in Varik..."
                    value={newInteractionNotes}
                    onChange={(e) => setNewInteractionNotes(e.target.value)}
                  />
                </div>

                <div className="flex gap-2">
                  <button 
                    onClick={() => setShowInteractionModal(false)}
                    className="flex-1 py-2 text-sm font-bold text-gray-400 hover:text-gray-600 transition-colors"
                  >
                    Annuleer
                  </button>
                  <button 
                    onClick={handleSaveInteraction}
                    className="flex-1 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-blue-200 active:scale-95 transition-all"
                  >
                    Opslaan
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Kinderen Section */}
        {contact.children && contact.children.length > 0 && (
          <div>
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Baby size={16} /> Kinderen
            </h3>
            <div className="grid grid-cols-1 gap-2">
              {contact.children.map((child, idx) => {
                const age = calculateAge(child.birthDate || '');
                return (
                  <div key={idx} className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 bg-pink-50/20">
                    <div className="w-8 h-8 rounded-full bg-pink-100 flex items-center justify-center text-pink-500">
                      <Baby size={16} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-bold text-gray-900 truncate">
                        {child.name}
                      </p>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                        {child.birthDate ? `${age} jaar • ${new Date(child.birthDate).toLocaleDateString()}` : 'Geen geboortedatum'}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Relations Section */}
        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
            <GitPullRequest size={16} /> Relaties & Familie
          </h3>
          <div className="space-y-2">
            {contactRelations.length > 0 ? contactRelations.map(item => (
              <div 
                key={item.relation.id} 
                onClick={() => item.contact && onContactClick(item.contact.id)}
                className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 bg-gray-50/30 hover:bg-blue-50/50 hover:border-blue-100 cursor-pointer transition-all group"
              >
                <img src={item.contact?.photoUrl || `https://ui-avatars.com/api/?name=${item.contact?.firstName}+${item.contact?.lastName || ''}`} className="w-10 h-10 rounded-full border border-white shadow-sm" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900 truncate group-hover:text-blue-600 transition-colors">
                    {item.contact?.firstName} {item.contact?.lastName}
                  </p>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{item.displayType}</p>
                </div>
              </div>
            )) : (
              <p className="text-xs text-gray-400 italic bg-gray-50 p-3 rounded-xl border border-dashed border-gray-200 text-center">Nog geen relaties gekoppeld</p>
            )}
          </div>
        </div>

        <div>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={16} /> Bewoners op dit adres
            </h3>
            <button 
              type="button"
              onClick={() => onAddResident(address.id)}
              className="text-blue-600 hover:text-blue-700 text-xs font-bold flex items-center gap-1 transition-colors"
            >
              <Plus size={14} /> bewoner toevoegen
            </button>
          </div>

          <div className="space-y-2">
            {allResidents.map(res => {
              const active = isMapAvatar(res.id);
              return (
                <div key={res.id} className={`flex items-center gap-3 p-2 rounded-xl border transition-all ${res.id === contact.id ? 'bg-blue-50/30 border-blue-100' : 'bg-gray-50/50 border-gray-100'}`}>
                  <img src={res.photoUrl || `https://ui-avatars.com/api/?name=${res.firstName}+${res.lastName || ''}`} className="w-8 h-8 rounded-full border border-gray-200" />
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-bold truncate ${res.id === contact.id ? 'text-blue-700' : 'text-gray-700'}`}>
                      {`${res.firstName} ${res.lastName || ''}`.trim()} {res.id === contact.id && <span className="text-[10px] font-medium opacity-60">(dit contact)</span>}
                    </p>
                  </div>
                  <button 
                    type="button"
                    onClick={() => onSetMapAvatar(address.id, res.id)}
                    className={`p-1.5 rounded-lg transition-all flex items-center gap-1.5 ${active ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400 hover:bg-gray-100'}`}
                    title={active ? 'Dit profiel wordt getoond op de kaart' : 'Toon dit profiel op de kaart'}
                  >
                    <MapPin size={14} />
                    {active && <span className="text-[10px] font-bold uppercase tracking-tight pr-0.5">Kaart</span>}
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2 flex items-center gap-1">
              <Dog size={14} /> Huisdieren
            </h4>
            {contact.pets.length > 0 ? (
              <ul className="text-sm space-y-1">
                {contact.pets.map((p, i) => <li key={i} className="font-medium text-gray-700">{p.name} ({p.type})</li>)}
              </ul>
            ) : (
              <p className="text-sm text-gray-400 italic">Geen</p>
            )}
          </div>
          <div className="bg-purple-50/50 p-4 rounded-2xl border border-purple-100">
            <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider mb-2 flex items-center gap-1">
              <Heart size={14} /> Hobby's
            </h4>
            <div className="flex flex-wrap gap-1">
              {contact.hobbies.map((h, i) => (
                <span key={i} className="text-[10px] bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full font-bold">
                  {h}
                </span>
              ))}
              {contact.hobbies.length === 0 && <span className="text-sm text-gray-400 italic">Geen</span>}
            </div>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2">
            <div className="flex items-center gap-1"><Info size={16} /> Bijzonderheden</div>
          </h3>
          <div className="bg-yellow-50 p-4 rounded-2xl border border-yellow-100 text-sm text-gray-700 leading-relaxed italic">
            "{contact.notes || 'Geen notities'}"
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center justify-between">
            <div className="flex items-center gap-2"><Clock size={16} /> Historie</div>
          </h3>
          <div className="space-y-4 relative before:absolute before:left-[11px] before:top-2 before:bottom-0 before:w-0.5 before:bg-gray-100">
            {contact.interactions.length > 0 ? (
              contact.interactions.map(log => (
                <div key={log.id} className="relative pl-8">
                  <div className="absolute left-0 top-1 w-6 h-6 bg-white border-2 border-blue-500 rounded-full flex items-center justify-center z-10">
                    <span className="text-blue-500">
                      {getInteractionIcon(log.type)}
                    </span>
                  </div>
                  <div className="bg-white border border-gray-100 rounded-2xl p-3 shadow-sm">
                    <div className="flex items-center justify-between mb-1">
                      <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{new Date(log.date).toLocaleDateString()}</p>
                      <span className="text-[9px] bg-blue-50 text-blue-500 px-1.5 py-0.5 rounded font-black uppercase tracking-tighter">{log.type}</span>
                    </div>
                    <p className="text-sm text-gray-700 font-medium leading-snug">{log.notes}</p>
                  </div>
                </div>
              ))
            ) : (
              <p className="text-sm text-gray-400 italic pl-8">Nog geen interacties vastgelegd.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

interface DetailItemProps {
  icon: React.ReactNode;
  label: string;
  value: string;
  link?: string;
}

const DetailItem: React.FC<DetailItemProps> = ({ icon, label, value, link }) => (
  <div className="flex items-start gap-4 group">
    <div className="p-2.5 bg-gray-50 rounded-xl text-gray-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors mt-1">
      {icon}
    </div>
    <div className="flex-1 min-w-0">
      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{label}</p>
      {link ? (
        <a href={link} target="_blank" rel="noreferrer" className="text-sm font-semibold text-gray-800 hover:text-blue-600 flex items-center gap-1 group/link truncate">
          {value} <ExternalLink size={12} className="opacity-0 group-hover/link:opacity-100 transition-opacity" />
        </a>
      ) : (
        <p className="text-sm font-semibold text-gray-800 truncate">{value}</p>
      )}
    </div>
  </div>
);

export default ContactDetails;

import React, { useState, useMemo } from 'react';
import { 
  X, Phone, Mail, MapPin, Calendar, Heart, 
  Dog, Info, Edit2, Trash2, Check,
  MessageSquare, ExternalLink, Clock, Users, Plus,
  GitPullRequest, Baby, Facebook, Instagram, Linkedin,
  CheckCircle2, Smartphone, UserCheck
} from 'lucide-react';
import { Contact, Address, ContactType, Relation, Interaction, InteractionMode } from '../types';

interface ContactDetailsProps {
  contact: Contact;
  address: Address;
  type: ContactType;
  contacts: Contact[];
  relations: Relation[];
  otherResidents: Contact[];
  onClose: () => void;
  onEdit: (contact: Contact) => void;
  onDelete: (id: string) => void;
  onAddResident: (addressId: string) => void;
  onSetMapAvatar: (addressId: string, contactId: string) => void;
  onContactClick: (id: string) => void;
}

const ContactDetails: React.FC<ContactDetailsProps> = ({ 
  contact, address, type, contacts, relations, otherResidents, onClose, onEdit, onDelete, onAddResident, onSetMapAvatar, onContactClick
}) => {
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [showInteractionModal, setShowInteractionModal] = useState(false);
  const [newInteractionType, setNewInteractionType] = useState<InteractionMode>('physical');
  const [newInteractionNotes, setNewInteractionNotes] = useState('');

  const initials = `${contact.firstName?.[0] || ''}${contact.lastName?.[0] || ''}`.toUpperCase();
  const allResidents = [...otherResidents, contact].sort((a, b) => a.createdAt.localeCompare(b.createdAt));

  const contactRelations = useMemo(() => {
    return relations
      .filter(r => r.contactAId === contact.id || r.contactBId === contact.id)
      .map(r => {
        const otherId = r.contactAId === contact.id ? r.contactBId : r.contactAId;
        const otherContact = contacts.find(c => c.id === otherId);
        return {
          relation: r,
          contact: otherContact,
          displayType: r.type
        };
      })
      .filter(item => item.contact);
  }, [contact.id, relations, contacts]);

  const isMapAvatar = (contactId: string) => {
    if (address.mapAvatarId) {
      return address.mapAvatarId === contactId;
    }
    return allResidents[0]?.id === contactId;
  };

  const calculateAge = (birthDate: string) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age >= 0 ? age : 0;
  };

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString) return 'Nooit';
    const last = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - last.getTime());
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Vandaag';
    if (diffDays === 1) return 'Gisteren';
    if (diffDays < 7) return `${diffDays} dagen geleden`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weken geleden`;
    return last.toLocaleDateString();
  };

  const handleSaveInteraction = () => {
    const now = new Date().toISOString();
    const newInteraction: Interaction = {
      id: `int-${Date.now()}`,
      type: newInteractionType,
      date: now,
      notes: newInteractionNotes || 'Interactie vastgelegd.'
    };

    const updatedContact: Contact = {
      ...contact,
      lastInteractionDate: now,
      interactions: [newInteraction, ...contact.interactions],
      updatedAt: now
    };

    onEdit(updatedContact);
    setShowInteractionModal(false);
    setNewInteractionNotes('');
    setNewInteractionType('physical');
  };

  const getInteractionIcon = (type: InteractionMode) => {
    switch(type) {
      case 'physical': return <Users size={14} />;
      case 'app': return <Smartphone size={14} />;
      case 'phone': return <Phone size={14} />;
      default: return <MessageSquare size={14} />;
    }
  };

  return (
    <div 
      className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[100] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300"
      onClick={(e) => {
        e.stopPropagation();
        if (isConfirmingDelete) setIsConfirmingDelete(false);
      }}
    >
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden">
          <img 
            src={`https://picsum.photos/seed/${contact.addressId}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onClose();
          }}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="absolute top-4 right-4 flex gap-2 z-20">
          {!isConfirmingDelete ? (
            <>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit(contact);
                }} 
                className="p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all"
                title="Bewerken"
              >
                <Edit2 size={18} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(true);
                }} 
                className="p-2 bg-red-500/80 hover:bg-red-500 backdrop-blur-md text-white rounded-full transition-all shadow-lg"
                title="Verwijderen"
              >
                <Trash2 size={18} />
              </button>
            </>
          ) : (
            <div 
              className="flex items-center bg-red-600 rounded-full p-1 pr-3 gap-2 animate-in zoom-in-75 duration-200 shadow-xl border border-red-400"
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(contact.id);
                }} 
                className="bg-white text-red-600 p-1.5 rounded-full hover:bg-gray-100 transition-colors shadow-sm"
              >
                <Check size={16} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(false);
                }} 
                className="text-white hover:text-red-100 transition-colors"
              >
                <X size={16} />
              </button>
              <span className="text-[10px] text-white font-black uppercase tracking-tight">Wissen?</span>
            </div>
          )}
        </div>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative">
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white"
              style={{ borderColor: type.color }}
            >
              {contact.photoUrl ? (
                <img src={contact.photoUrl} alt={contact.firstName} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl">
                  {initials}
                </div>
              )}
            </div>
            <div 
              className="absolute bottom-1 right-1 w-6 h-6 rounded-full border-2 border-white shadow-sm"
              style={{ backgroundColor: type.color }}
            />
          </div>
          <div className="pb-2 flex flex-col items-center gap-2">
            {contact.isFavorite && (
              <div className="p-2 bg-red-50 rounded-full text-red-500 shadow-sm border border-red-100">
                <Heart size={20} className="fill-current" />
              </div>
            )}
          </div>
        </div>

        <div className="px-6 mt-4 flex items-start justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900 leading-tight">{`${contact.firstName} ${contact.lastName || ''}`.trim()}</h2>
            <span 
              className="inline-block mt-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white"
              style={{ backgroundColor: type.color }}
            >
              {type.name}
            </span>
          </div>
          <div className="flex gap-2 mt-1">
            {contact.socialLinks?.facebook && (
              <a href={contact.socialLinks.facebook} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors">
                <Facebook size={16} />
              </a>
            )}
            {contact.socialLinks?.instagram && (
              <a href={contact.socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-pink-50 text-pink-600 rounded-lg hover:bg-pink-100 transition-colors">
                <Instagram size={16} />
              </a>
            )}
            {contact.socialLinks?.linkedin && (
              <a href={contact.socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="p-1.5 bg-blue-50 text-blue-800 rounded-lg hover:bg-blue-100 transition-colors">
                <Linkedin size={16} />
              </a>
            )}
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-20 mt-4">
        {/* Last Interaction Section */}
        <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 flex items-center justify-between">
          <div>
            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">Laatst gesproken</p>
            <p className="text-sm font-bold text-blue-900">{getTimeSinceLastContact(contact.lastInteractionDate)}</p>
          </div>
          <button 
            onClick={(e) => {
              e.stopPropagation();
              setShowInteractionModal(true);
            }}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl font-bold text-xs transition-all shadow-md active:scale-95"
          >
            <CheckCircle2 size={14} /> Nu vastleggen
          </button>
        </div>

        <div className="space-y-4">
          <DetailItem icon={<Phone size={18} />} label="Telefoon" value={contact.phones[0] || 'Geen nummer'} />
          <DetailItem icon={<Mail size={18} />} label="E-mail" value={contact.emails[0] || 'Geen e-mail'} />
          <DetailItem 
            icon={<MapPin size={18} />} 
            label="Adres" 
            value={`${address.street} ${address.houseNumber}, ${address.city}`} 
            link={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${address.street} ${address.houseNumber}, ${address.city}`)}`}
          />
          <DetailItem icon={<Calendar size={18} />} label="Jarig op" value={contact.birthDate || 'Niet ingesteld'} />
        </div>

        {/* Kinderen Section */}
        {contact.children && contact.children.length > 0 && (
          <div>
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Baby size={16} /> Kinderen
            </h3>
            <div className="grid grid-cols-1 gap-2">
              {contact.children.map((child, idx) => {
                const age = calculateAge(child.birthDate || '');
                return (
                  <div key={idx} className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 bg-pink-50/20">
                    <div className="w-8 h-8 rounded-full bg-pink-100 flex items-center justify-center text-pink-500">
                      <Baby size={16} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-bold text-gray-900 truncate">
                        {child.name}
                      </p>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
                        {child.birthDate ? `${age} jaar • ${new Date(child.birthDate).toLocaleDateString()}` : 'Geen geboortedatum'}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Relations Section */}
        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
            <GitPullRequest size={16} /> Relaties & Familie
          </h3>
          <div className="space-y-2">
            {contactRelations.length > 0 ? contactRelations.map(item => (
              <div 
                key={item.relation.id} 
                onClick={() => item.contact && onContactClick(item.contact.id)}
                className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 bg-gray-50/30 hover:bg-blue-50/50 hover:border-blue-100 cursor-pointer transition-all group"
              >
                <img src={item.contact?.photoUrl || `https://ui-avatars.com/api/?name=${item.contact?.firstName}+${item.contact?.lastName || ''}`} className="w-10 h-10 rounded-full border border-white shadow-sm" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900 truncate group-hover:text-blue-600 transition-colors">
                    {item.contact?.firstName} {item.contact?.lastName}
                  </p>
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{item.displayType}</p>
                </div>
              </div>
            )) : (
              <p className="text-xs text-gray-400 italic bg-gray-50 p-3 rounded-xl border border-dashed border-gray-200 text-center">Nog geen relaties gekoppeld</p>
            )}
          </div>
        </div>

        <div>
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
              <Users size={16} /> Bewoners op dit adres
            </h3>
            <button 
              type="button"
              onClick={() => onAddResident(address.id)}
              className="text-blue-600 hover:text-blue-700 text-xs font-bold flex items-center gap-1 transition-colors"
            >
              <Plus size={14} /> bewoner toevoegen
            </button>
          </div>

          <div className="space-y-2">
            {allResidents.map(res => {
              const active = isMapAvatar(res.id);
              return (
                <div key={res.id} className={`flex items-center gap-3 p-2 rounded-xl border transition-all ${res.id === contact.id ? 'bg-blue-50/30 border-blue-100' : 'bg-gray-50/50 border-gray-100'}`}>
                  <img src={res.photoUrl || `https://ui-avatars.com/api/?name=${res.firstName}+${res.lastName || ''}`} className="w-8 h-8 rounded-full border border-gray-200" />
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-bold truncate ${res.id === contact.id ? 'text-blue-700' : 'text-gray-700'}`}>
                      {`${res.firstName} ${res.lastName || ''}`.trim()} {res.id === contact.id && <span className="text-[10px] font-medium opacity-60">(dit contact)</span>}
                    </p>
                  </div>
                  <button 
                    type="button"
                    onClick={() => onSetMapAvatar(address.id, res.id)}
                    className={`p-1.5 rounded-lg transition-all flex items-center gap-1.5 ${active ? 'bg-blue-600 text-white shadow-sm' : 'text-gray-400 hover:bg-gray-100'}`}
                    title={active ? 'Dit profiel wordt getoond op de kaart' : 'Toon dit profiel op de kaart'}
                  >
                    <MapPin size={14} />
                    {active && <span className="text-[10px] font-bold uppercase tracking-tight pr-0.5">Kaart</span>}
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-wider mb-2 flex items-center gap-1">
              <Dog size={14} /> Huisdieren
            </h4>
            {contact.pets.length > 0 ? (
              <ul className="text-sm space-y-1">
                {contact.pets.map((p, i) => <li key={i} className="font-medium text-gray-700">{p.name} ({p.type})</li>)}
              </ul>
            ) : (
              <p className="text-sm text-gray-400 italic">Geen</p>
            )}
          </div>
          <div className="bg-purple-50/50 p-4 rounded-2xl border border-purple-100">
            <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider mb-2 flex items-center gap-1">
              <Heart size={14} /> Hobby's
            </h4>
            <div className="flex flex-wrap gap-1">
              {contact.hobbies.map((h, i) => (
                <span key={i} className="text-[10px] bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full font-bold">
                  {h}
                </span>
              ))}
              {contact.hobbies.length === 0 && <span className="text-sm text-gray-400 italic">Geen</span>}
            </div>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-2">
            <div className="flex items-center gap-1"><Info size={16} /> Bijzonderheden</div>
          </h3>
          <div className="bg-yellow-50 p-4 rounded-2xl border border-yellow-100 text-sm text-gray-700 leading-relaxed italic">
            "{contact.notes || 'Geen notities'}"
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center justify-between">
            <div className="flex items-center gap-2"><Clock size={16} /> Historie</div>
          </h3>
          <div className="space-y-4 relative before:absolute before:left-[11px] before:top-2 before:bottom-0 before:w-0.5 before:bg-gray-100">
            {contact.interactions.length > 0 ? (
              contact.interactions.map(log => (
                <div key={log.id} className="relative pl-8">
                  <div className="absolute left-0 top-1 w-6 h-6 bg-white border-2 border-blue-500 rounded-full flex items-center justify-center z-10">
                    <span className="text-blue-500">
                      {getInteractionIcon(log.type)}
                    </span>
                  </div>
                  <div className="bg-white border border-gray-100 rounded-2xl p-3 shadow-sm">
                    <div className="flex items-center justify-between mb-1">
                      <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{new Date(log.date).toLocaleDateString()}</p>
                      <span className="text-[9px] bg-blue-50 text-blue-500 px-1.5 py-0.5 rounded font-black uppercase tracking-tighter">{log.type}</span>
                    </div>
                    <p className="text-sm text-gray-700 font-medium leading-snug">{log.notes}</p>
                  </div>
                </div>
              ))
            ) : (
              <p className="text-sm text-gray-400 italic pl-8">Nog geen interacties vastgelegd.</p>
            )}
          </div>
        </div>
      </div>

      {/* Interaction Modal - Moved outside of the scrolling content, absolute to the details container */}
      {showInteractionModal && (
        <div className="absolute inset-0 z-[250] flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-[2px] animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] w-full max-w-[320px] shadow-2xl p-8 border border-gray-100 animate-in zoom-in-95 duration-200">
            <h4 className="text-xl font-bold text-gray-900 mb-6">Interactie vastleggen</h4>

            <div className="space-y-6">
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Type contact</p>
                <div className="grid grid-cols-3 gap-3">
                  <button 
                    onClick={() => setNewInteractionType('physical')}
                    className={`flex flex-col items-center gap-2 p-3 rounded-2xl border text-[10px] font-bold transition-all ${newInteractionType === 'physical' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-200' : 'bg-gray-50 text-gray-400 border-gray-100 hover:bg-gray-100'}`}
                  >
                    <UserCheck size={18} /> Fysiek
                  </button>
                  <button 
                    onClick={() => setNewInteractionType('app')}
                    className={`flex flex-col items-center gap-2 p-3 rounded-2xl border text-[10px] font-bold transition-all ${newInteractionType === 'app' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-200' : 'bg-gray-50 text-gray-400 border-gray-100 hover:bg-gray-100'}`}
                  >
                    <Smartphone size={18} /> App
                  </button>
                  <button 
                    onClick={() => setNewInteractionType('phone')}
                    className={`flex flex-col items-center gap-2 p-3 rounded-2xl border text-[10px] font-bold transition-all ${newInteractionType === 'phone' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-200' : 'bg-gray-50 text-gray-400 border-gray-100 hover:bg-gray-100'}`}
                  >
                    <Phone size={18} /> Bel
                  </button>
                </div>
              </div>

              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3">Toelichting</p>
                <textarea 
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-blue-500 min-h-[100px] resize-none transition-all"
                  placeholder="Bijv: Op verjaardag in Varik..."
                  value={newInteractionNotes}
                  onChange={(e) => setNewInteractionNotes(e.target.value)}
                  autoFocus
                />
              </div>

              <div className="flex flex-col gap-2">
                <button 
                  onClick={handleSaveInteraction}
                  className="w-full py-4 bg-blue-600 text-white rounded-2xl text-sm font-bold shadow-xl shadow-blue-100 active:scale-95 transition-all"
                >
                  Opslaan
                </button>
                <button 
                  onClick={() => setShowInteractionModal(false)}
                  className="w-full py-4 text-sm font-bold text-gray-400 hover:text-gray-600 transition-colors"
                >
                  Annuleren
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

