import React, { useState, useMemo } from 'react';
import { 
  Filter, MoreHorizontal, Mail, Phone, 
  MapPin, Star, Heart, Grid, List as ListIcon,
  ChevronDown, Clock
} from 'lucide-react';
import { Contact, Address, ContactType } from '../types';

interface ContactListProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const ContactList: React.FC<ContactListProps> = ({ contacts, addresses, types, onContactClick }) => {
  const [viewStyle, setViewStyle] = useState<'grid' | 'table'>('grid');
  const [selectedTypeId, setSelectedTypeId] = useState<string>('all');

  // Process contacts: Filter by type and sort by last name (fall back to first name)
  const processedContacts = useMemo(() => {
    let result = [...contacts];

    // Filter
    if (selectedTypeId !== 'all') {
      result = result.filter(c => c.typeId === selectedTypeId);
    }

    // Sort by last name (case-insensitive), fallback to first name if last name is missing
    return result.sort((a, b) => {
      const nameA = (a.lastName || a.firstName).toLowerCase();
      const nameB = (b.lastName || b.firstName).toLowerCase();
      return nameA.localeCompare(nameB);
    });
  }, [contacts, selectedTypeId]);

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString) return 'Nooit';

    // Normalize dates to start of the day (00:00:00) to compare calendar days
    const lastDate = new Date(dateString);
    const lastDay = new Date(lastDate.getFullYear(), lastDate.getMonth(), lastDate.getDate());

    const todayDate = new Date();
    const todayDay = new Date(todayDate.getFullYear(), todayDate.getMonth(), todayDate.getDate());

    const diffTime = todayDay.getTime() - lastDay.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Vandaag';
    if (diffDays === 1) return 'Gisteren';
    if (diffDays < 7) return `${diffDays}d geleden`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)}w geleden`;
    return lastDate.toLocaleDateString();
  };

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-6 pb-24">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Contacten Overzicht</h2>
            <p className="text-sm text-gray-500">{processedContacts.length} mensen getoond</p>
          </div>

          <div className="flex items-center gap-3">
            {/* Type Filter */}
            <div className="relative group">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-blue-500 transition-colors">
                <Filter size={14} />
              </div>
              <select 
                value={selectedTypeId}
                onChange={(e) => setSelectedTypeId(e.target.value)}
                className="pl-9 pr-8 py-2 bg-white border border-gray-200 rounded-xl text-xs font-bold text-gray-700 outline-none appearance-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm transition-all cursor-pointer"
              >
                <option value="all">Alle Typen</option>
                {types.map(t => (
                  <option key={t.id} value={t.id}>{t.name}</option>
                ))}
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none">
                <ChevronDown size={14} />
              </div>
            </div>

            <div className="h-8 w-px bg-gray-200" />

            {/* View Toggle */}
            <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-xl">
              <button 
                onClick={() => setViewStyle('grid')}
                className={`p-2 rounded-lg transition-all ${viewStyle === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400 hover:text-gray-600'}`}
                title="Grid weergave"
              >
                <Grid size={18} />
              </button>
              <button 
                onClick={() => setViewStyle('table')}
                className={`p-2 rounded-lg transition-all ${viewStyle === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400 hover:text-gray-600'}`}
                title="Lijst weergave"
              >
                <ListIcon size={18} />
              </button>
            </div>
          </div>
        </div>

        {viewStyle === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {processedContacts.map(contact => {
              const addr = addresses.find(a => a.id === contact.addressId);
              const type = types.find(t => t.id === contact.typeId);
              const displayAddress = addr ? `${addr.street} ${addr.houseNumber}, ${addr.city}` : 'Onbekend';
              return (
                <div 
                  key={contact.id}
                  onClick={() => onContactClick(contact.id)}
                  className="bg-white rounded-3xl p-5 border border-gray-100 shadow-sm hover:shadow-xl hover:border-blue-200 cursor-pointer transition-all group relative"
                >
                  {contact.isFavorite && (
                    <div className="absolute top-4 right-4 text-red-500 fill-current">
                      <Heart size={16} className="fill-current" />
                    </div>
                  )}

                  <div className="flex flex-col items-center text-center">
                    <div className="relative mb-4">
                      <img 
                        src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} 
                        className="w-24 h-24 rounded-3xl object-cover border-4 transition-all shadow-md" 
                        style={{ borderColor: type?.color || '#F3F4F6' }}
                      />
                      <div 
                        className="absolute -bottom-2 right-0 w-6 h-6 rounded-full border-2 border-white shadow-sm"
                        style={{ backgroundColor: type?.color }}
                      />
                    </div>

                    <h3 className="text-lg font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
                      {`${contact.firstName} ${contact.lastName || ''}`.trim()}
                    </h3>
                    <div className="flex items-center gap-1.5 justify-center mb-4">
                      <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{type?.name}</p>
                      <span className="text-gray-300">•</span>
                      <div className="flex items-center gap-1 text-[10px] text-blue-500 font-bold bg-blue-50 px-2 py-0.5 rounded-full">
                         <Clock size={10} /> {getTimeSinceLastContact(contact.lastInteractionDate)}
                      </div>
                    </div>

                    <div className="w-full space-y-2 text-sm">
                      <div className="flex items-center gap-2 text-gray-500 bg-gray-50 p-2 rounded-xl">
                        <MapPin size={14} className="shrink-0" />
                        <span className="truncate">{displayAddress}</span>
                      </div>
                      <div className="flex items-center gap-2 text-gray-500 bg-gray-50 p-2 rounded-xl">
                        <Phone size={14} className="shrink-0" />
                        <span className="truncate">{contact.phones[0] || 'Geen nr'}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[900px]">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest min-w-[250px]">Contact</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Type</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Adres</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Telefoon</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Laatst gezien</th>
                    <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest w-16">Actie</th>
                  </tr>
                </thead>
                <tbody>
                  {processedContacts.map(contact => {
                    const addr = addresses.find(a => a.id === contact.addressId);
                    const type = types.find(t => t.id === contact.typeId);
                    const fullAddress = addr ? `${addr.street} ${addr.houseNumber}, ${addr.city}` : 'Onbekend';
                    return (
                      <tr 
                        key={contact.id} 
                        className="hover:bg-blue-50/30 cursor-pointer transition-colors border-b border-gray-50"
                        onClick={() => onContactClick(contact.id)}
                      >
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-3">
                            <div className="relative">
                              <img 
                                src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} 
                                className="w-10 h-10 rounded-xl object-cover border-2" 
                                style={{ borderColor: type?.color || '#F3F4F6' }}
                              />
                              {contact.isFavorite && (
                                <div className="absolute -top-1 -right-1 bg-white rounded-full p-0.5 shadow-sm text-red-500">
