import React, { useState, useMemo } from 'react';
import { 
  X, Phone, Mail, MapPin, Calendar, Heart, 
  Dog, Info, Edit2, Trash2, Check,
  MessageSquare, ExternalLink, Clock, Users, Plus,
  GitPullRequest, Baby, Facebook, Instagram, Linkedin,
  CheckCircle2, Smartphone, UserCheck
} from 'lucide-react';
import { Contact, Address, ContactType, Relation, Interaction, InteractionMode } from '../types';

interface ContactDetailsProps {
  contact: Contact;
  address: Address;
  type: ContactType;
  contacts: Contact[];
  relations: Relation[];
  otherResidents: Contact[];
  onClose: () => void;
  onEdit: (contact: Contact) => void;
  onDelete: (id: string) => void;
  onAddResident: (addressId: string) => void;
  onSetMapAvatar: (addressId: string, contactId: string) => void;
  onContactClick: (id: string) => void;
}

const ContactDetails: React.FC<ContactDetailsProps> = ({ 
  contact, address, type, contacts, relations, otherResidents, onClose, onEdit, onDelete, onAddResident, onSetMapAvatar, onContactClick
}) => {
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [showInteractionModal, setShowInteractionModal] = useState(false);
  const [newInteractionType, setNewInteractionType] = useState<InteractionMode>('physical');
  const [newInteractionNotes, setNewInteractionNotes] = useState('');
  const [newInteractionDate, setNewInteractionDate] = useState<string>(new Date().toISOString().split('T')[0]);

  const initials = `${contact.firstName?.[0] || ''}${contact.lastName?.[0] || ''}`.toUpperCase();
  const allResidents = [...otherResidents, contact].sort((a, b) => a.createdAt.localeCompare(b.createdAt));

  const contactRelations = useMemo(() => {
    return relations
      .filter(r => r.contactAId === contact.id || r.contactBId === contact.id)
      .map(r => {
        const otherId = r.contactAId === contact.id ? r.contactBId : r.contactAId;
        const otherContact = contacts.find(c => c.id === otherId);
        return {
          relation: r,
          contact: otherContact,
          displayType: r.type
        };
      })
      .filter(item => item.contact);
  }, [contact.id, relations, contacts]);

  const isMapAvatar = (contactId: string) => {
    if (address.mapAvatarId) {
      return address.mapAvatarId === contactId;
    }
    return allResidents[0]?.id === contactId;
  };

  const calculateAge = (birthDate: string) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age >= 0 ? age : 0;
  };

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString) return 'Nooit';

    const lastDate = new Date(dateString);
    const lastDay = new Date(lastDate.getFullYear(), lastDate.getMonth(), lastDate.getDate());

    const todayDate = new Date();
    const todayDay = new Date(todayDate.getFullYear(), todayDate.getMonth(), todayDate.getDate());

    const diffTime = todayDay.getTime() - lastDay.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return 'Vandaag';
    if (diffDays === 1) return 'Gisteren';
    if (diffDays < 7) return `${diffDays} dagen geleden`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weken geleden`;
    return lastDate.toLocaleDateString();
  };

  const handleSaveInteraction = () => {
    const selectedDateTime = new Date(newInteractionDate);
    // Add current time components if it's today, otherwise keep at midnight UTC
    const now = new Date();
    if (selectedDateTime.toDateString() === now.toDateString()) {
      selectedDateTime.setHours(now.getHours(), now.getMinutes(), now.getSeconds());
    }

    const isoDate = selectedDateTime.toISOString();

    const newInteraction: Interaction = {
      id: `int-${Date.now()}`,
      type: newInteractionType,
      date: isoDate,
      notes: newInteractionNotes || 'Interactie vastgelegd.'
    };

    const updatedContact: Contact = {
      ...contact,
      lastInteractionDate: isoDate,
      interactions: [newInteraction, ...contact.interactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()),
      updatedAt: new Date().toISOString()
    };

    onEdit(updatedContact);
    setShowInteractionModal(false);
    setNewInteractionNotes('');
    setNewInteractionType('physical');
    setNewInteractionDate(new Date().toISOString().split('T')[0]);
  };

  const getInteractionIcon = (type: InteractionMode) => {
    switch(type) {
      case 'physical': return <Users size={14} />;
      case 'app': return <Smartphone size={14} />;
      case 'phone': return <Phone size={14} />;
      default: return <MessageSquare size={14} />;
    }
  };

  return (
    <div 
      className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[100] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300"
      onClick={(e) => {
        e.stopPropagation();
        if (isConfirmingDelete) setIsConfirmingDelete(false);
      }}
    >
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden">
          <img 
            src={`https://picsum.photos/seed/${contact.addressId}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onClose();
          }}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="absolute top-4 right-4 flex gap-2 z-20">
          {!isConfirmingDelete ? (
            <>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit(contact);
                }} 
                className="p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all"
                title="Bewerken"
              >
                <Edit2 size={18} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(true);
                }} 
                className="p-2 bg-red-500/80 hover:bg-red-500 backdrop-blur-md text-white rounded-full transition-all shadow-lg"
                title="Verwijderen"
              >
                <Trash2 size={18} />
              </button>
            </>
          ) : (
            <div 
              className="flex items-center bg-red-600 rounded-full p-1 pr-3 gap-2 animate-in zoom-in-75 duration-200 shadow-xl border border-red-400"
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(contact.id);
                }} 
                className="bg-white text-red-600 p-1.5 rounded-full hover:bg-gray-100 transition-colors shadow-sm"
              >
                <Check size={16} />
              </button>
              <button 
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setIsConfirmingDelete(false);
                }} 
                className="text-white hover:text-red-100 transition-colors"
              >
                <X size={16} />
              </button>
              <span className="text-[10px] text-white font-black uppercase tracking-tight">Wissen?</span>
            </div>
          )}
        </div>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative">
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white"
              style={{ borderColor: type.color }}
            >
              {contact.photoUrl ? (
                <img src={contact.photoUrl} alt={contact.firstName} className="w-full h-full object-cover" />
              ) : (
