export default ContactDetails;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  X, Save, Camera, Plus, Trash, RefreshCw, 
  ImageIcon, Upload, Loader2, Heart, 
  MapPin, Users, Search, Phone, Mail, Calendar, 
  Dog, Info, GitPullRequest, Trash2, Baby,
  Facebook, Instagram, Linkedin, Clock, Smartphone, UserCheck, MessageSquare
} from 'lucide-react';
import { Contact, Address, ContactType, Pet, Relation, RelationType, ContactChild, SocialLinks, InteractionMode, Interaction } from '../types';
import { compressImageBase64 } from '../utils';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  contacts: Contact[];
  relations: Relation[];
  initialCoords: [number, number] | null;
  initialAddressId: string | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address, relations: Relation[]) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, contacts, relations, initialCoords, initialAddressId, onClose, onSave 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingAddress, setIsLoadingAddress] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');
  const [addressSearch, setAddressSearch] = useState('');
  const [relationSearch, setRelationSearch] = useState('');
  const [isChoosingExisting, setIsChoosingExisting] = useState(false);

  // New interaction state for the form
  const [lastInteractionType, setLastInteractionType] = useState<InteractionMode>('physical');
  const [lastInteractionNotes, setLastInteractionNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Contact>>(() => {
    const base = contact || {
      firstName: '',
      lastName: '',
      phones: [''],
      emails: [''],
      typeId: types[0].id,
      notes: '',
      isFavorite: false,
      pets: [],
      children: [],
      socialLinks: {},
      hobbies: [],
      photoUrl: '',
      lastInteractionDate: '',
      interactions: []
    };

    if (!contact && initialAddressId) {
      const existingResident = contacts.find(c => c.addressId === initialAddressId);
      if (existingResident) {
        return { ...base, lastName: existingResident.lastName || '' };
      }
    }
    return base;
  });

  const [addrData, setAddrData] = useState<Partial<Address>>(() => {
    if (contact?.addressId) return addresses.find(a => a.id === contact.addressId) || {};
    if (initialAddressId) return addresses.find(a => a.id === initialAddressId) || {};
    return {
      street: '',
      houseNumber: '',
      postalCode: '',
      city: '',
      lat: initialCoords ? initialCoords[0] : 52.37,
      lng: initialCoords ? initialCoords[1] : 4.89,
      country: 'Nederland'
    };
  });

  const [localRelations, setLocalRelations] = useState<Relation[]>(() => {
    if (!contact) return [];
    return relations.filter(r => r.contactAId === contact.id || r.contactBId === contact.id);
  });

  const filteredAddresses = useMemo(() => {
    if (!addressSearch) return addresses;
    const q = addressSearch.toLowerCase();
    return addresses.filter(a => 
      a.street.toLowerCase().includes(q) || 
      a.city.toLowerCase().includes(q) || 
      a.postalCode.toLowerCase().includes(q)
    );
  }, [addresses, addressSearch]);

  const filteredContactsForRelation = useMemo(() => {
    if (!relationSearch) return [];
    const q = relationSearch.toLowerCase();
    const currentContactId = contact?.id || 'new';
    return contacts
      .filter(c => c.id !== currentContactId)
      .filter(c => !localRelations.some(r => r.contactAId === c.id || r.contactBId === c.id))
      .filter(c => 
        c.firstName.toLowerCase().includes(q) || 
        (c.lastName || '').toLowerCase().includes(q)
      )
      .slice(0, 5);
  }, [contacts, relationSearch, localRelations, contact?.id]);

  const currentResidents = useMemo(() => {
    if (!addrData.id) return [];
    return contacts.filter(c => c.addressId === addrData.id && c.id !== contact?.id);
  }, [addrData.id, contacts, contact?.id]);

  useEffect(() => {
    if (initialCoords && !initialAddressId && !isChoosingExisting) {
      const [lat, lng] = initialCoords;
      setIsLoadingAddress(true);
      fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&addressdetails=1`)
        .then(res => res.json())
        .then(data => {
          const addr = data.address;
          setAddrData(prev => ({
            ...prev,
            street: addr.road || addr.pedestrian || addr.suburb || addr.neighbourhood || '',
            houseNumber: addr.house_number || '',
            postalCode: addr.postcode || '',
            city: addr.city || addr.town || addr.village || addr.municipality || '',
            lat,
            lng
          }));
        })
        .catch(() => setAddrData(prev => ({ ...prev, lat, lng })))
        .finally(() => setIsLoadingAddress(false));
    }
  }, [initialCoords, initialAddressId, isChoosingExisting]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        // Compress image before storing in state
        const compressed = await compressImageBase64(base64);
        setFormData({ ...formData, photoUrl: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddRelation = (otherContact: Contact, type: RelationType) => {
    const currentId = contact?.id || 'new-temp-id';
    const newRel: Relation = {
      id: `rel-${Date.now()}-${Math.random()}`,
      contactAId: currentId,
      contactBId: otherContact.id,
      type,
      createdAt: new Date().toISOString()
    };
    setLocalRelations([...localRelations, newRel]);
    setRelationSearch('');
  };

  const handleRemoveRelation = (relId: string) => {
    setLocalRelations(localRelations.filter(r => r.id !== relId));
  };

  const handleAddChild = () => {
    const newChild: ContactChild = { name: '', birthDate: '' };
    setFormData({ ...formData, children: [...(formData.children || []), newChild] });
  };

  const handleUpdateChild = (idx: number, field: keyof ContactChild, value: string) => {
    const updatedChildren = [...(formData.children || [])];
    updatedChildren[idx] = { ...updatedChildren[idx], [field]: value };
    setFormData({ ...formData, children: updatedChildren });
  };

  const handleRemoveChild = (idx: number) => {
    setFormData({ ...formData, children: (formData.children || []).filter((_, i) => i !== idx) });
  };

  const handleUpdateSocial = (field: keyof SocialLinks, value: string) => {
    setFormData({
      ...formData,
      socialLinks: {
        ...(formData.socialLinks || {}),
        [field]: value
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    let finalAddr = { ...addrData };
    if (!addrData.id && !initialCoords) {
      try {
        const queryParts = [addrData.street, addrData.houseNumber, addrData.postalCode, addrData.city, addrData.country]
          .filter(p => !!p && p.trim() !== '');
        let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(queryParts.join(', '))}&limit=1`);
        let data = await response.json();
        if (data && data.length > 0) {
          finalAddr.lat = parseFloat(data[0].lat);
          finalAddr.lng = parseFloat(data[0].lon);
        }
      } catch (error) {
        console.error("Geocoding failed", error);
      }
    }

    const addressId = addrData.id || `addr-${Date.now()}`;
    const finalAddress: Address = { ...finalAddr as Address, id: addressId };

    const contactId = contact?.id || `c-${Date.now()}`;

    const finalContact: Contact = {
      ...formData as Contact,
      id: contactId,
      addressId,
      updatedAt: new Date().toISOString(),
      createdAt: contact?.createdAt || new Date().toISOString(),
      interactions: formData.interactions || []
    };

    // Update local relations with the actual contact ID if it was new
    const finalRelations = localRelations.map(r => ({
      ...r,
