interface FormInputProps {
  icon?: React.ReactNode;
  label: string;
  value?: string;
  onChange: (v: string) => void;
  placeholder?: string;
  type?: string;
  disabled?: boolean;
}

const FormInput: React.FC<FormInputProps> = ({ icon, label, value, onChange, placeholder, type = 'text', disabled }) => (
  <div className={`flex items-start gap-4 group ${disabled ? 'opacity-70' : ''}`}>
    {icon && (
      <div className="p-2.5 bg-gray-50 rounded-xl text-gray-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-colors mt-1">
        {icon}
      </div>
    )}
    <div className="flex-1 min-w-0">
      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{label}</p>
      <input 
        type={type}
        value={value || ''}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className={`w-full text-sm font-semibold text-gray-800 bg-transparent border-b border-gray-100 focus:border-blue-500 outline-none pb-1 transition-all ${disabled ? 'cursor-not-allowed' : ''}`}
      />
    </div>
  </div>
);

