                          >
                            {type?.name}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-sm text-gray-600">
                          <div className="flex items-center gap-1.5 max-w-[300px]">
                            <span className="truncate">{fullAddress}</span>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          {frequencyLabel ? (
                            <div className="flex items-center gap-1.5 text-xs text-emerald-600 font-bold bg-emerald-50 px-2 py-1 rounded-lg w-fit">
                              <Activity size={12} /> {frequencyLabel}
