export default ContactDetails;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  X, Save, Camera, Plus, Trash, RefreshCw, 
  ImageIcon, Upload, Loader2, Heart, 
  MapPin, Users, Search, Phone, Mail, Calendar, 
  Dog, Info, GitPullRequest, Trash2, Baby,
  Facebook, Instagram, Linkedin, Clock, Smartphone, UserCheck, MessageSquare, Activity
} from 'lucide-react';
import { Contact, Address, ContactType, Pet, Relation, RelationType, ContactChild, SocialLinks, InteractionMode, Interaction } from '../types.ts';
import { compressImageBase64 } from '../utils.ts';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  contacts: Contact[];
  relations: Relation[];
  initialCoords: [number, number] | null;
  initialAddressId: string | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address, relations: Relation[]) => void;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, contacts, relations, initialCoords, initialAddressId, onClose, onSave 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingAddress, setIsLoadingAddress] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');
  const [addressSearch, setAddressSearch] = useState('');
  const [relationSearch, setRelationSearch] = useState('');
  const [isChoosingExisting, setIsChoosingExisting] = useState(false);

  // New interaction state for the form
  const [lastInteractionType, setLastInteractionType] = useState<InteractionMode>('physical');
  const [lastInteractionNotes, setLastInteractionNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Contact>>(() => {
    const base = contact || {
      firstName: '',
      lastName: '',
      phones: [''],
      emails: [''],
      typeId: types[0].id,
      notes: '',
      isFavorite: false,
      pets: [],
      children: [],
      socialLinks: {},
      hobbies: [],
      photoUrl: '',
      lastInteractionDate: '',
      interactions: [],
      interactionIntervalDays: 0
    };

    if (!contact && initialAddressId) {
      const existingResident = contacts.find(c => c.addressId === initialAddressId);
      if (existingResident) {
        return { ...base, lastName: existingResident.lastName || '' };
      }
    }
    return base;
  });

  const [addrData, setAddrData] = useState<Partial<Address>>(() => {
    if (contact?.addressId) return addresses.find(a => a.id === contact.addressId) || {};
    if (initialAddressId) return addresses.find(a => a.id === initialAddressId) || {};
    return {
      street: '',
      houseNumber: '',
      postalCode: '',
      city: '',
      lat: initialCoords ? initialCoords[0] : 52.37,
      lng: initialCoords ? initialCoords[1] : 4.89,
      country: 'Nederland'
    };
  });

  const [localRelations, setLocalRelations] = useState<Relation[]>(() => {
    if (!contact) return [];
    return relations.filter(r => r.contactAId === contact.id || r.contactBId === contact.id);
  });

  const filteredAddresses = useMemo(() => {
    if (!addressSearch) return addresses;
    const q = addressSearch.toLowerCase();
    return addresses.filter(a => 
      a.street.toLowerCase().includes(q) || 
      a.city.toLowerCase().includes(q) || 
      a.postalCode.toLowerCase().includes(q)
    );
  }, [addresses, addressSearch]);

  const filteredContactsForRelation = useMemo(() => {
    if (!relationSearch) return [];
    const q = relationSearch.toLowerCase();
    const currentContactId = contact?.id || 'new';
    return contacts
      .filter(c => c.id !== currentContactId)
      .filter(c => !localRelations.some(r => r.contactAId === c.id || r.contactBId === c.id))
      .filter(c => 
        c.firstName.toLowerCase().includes(q) || 
        (c.lastName || '').toLowerCase().includes(q)
      )
      .slice(0, 5);
  }, [contacts, relationSearch, localRelations, contact?.id]);

  const currentResidents = useMemo(() => {
    if (!addrData.id) return [];
    return contacts.filter(c => c.addressId === addrData.id && c.id !== contact?.id);
  }, [addrData.id, contacts, contact?.id]);

  useEffect(() => {
    if (initialCoords && !initialAddressId && !isChoosingExisting) {
      const [lat, lng] = initialCoords;
      setIsLoadingAddress(true);
      fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&addressdetails=1`)
        .then(res => res.json())
        .then(data => {
          const addr = data.address;
          setAddrData(prev => ({
            ...prev,
            street: addr.road || addr.pedestrian || addr.suburb || addr.neighbourhood || '',
            houseNumber: addr.house_number || '',
            postalCode: addr.postcode || '',
            city: addr.city || addr.town || addr.village || addr.municipality || '',
            lat,
            lng
          }));
        })
        .catch(() => setAddrData(prev => ({ ...prev, lat, lng })))
        .finally(() => setIsLoadingAddress(false));
    }
  }, [initialCoords, initialAddressId, isChoosingExisting]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64 = reader.result as string;
        // Compress image before storing in state
        const compressed = await compressImageBase64(base64);
        setFormData({ ...formData, photoUrl: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddRelation = (otherContact: Contact, type: RelationType) => {
    const currentId = contact?.id || 'new-temp-id';
    const newRel: Relation = {
      id: `rel-${Date.now()}-${Math.random()}`,
      contactAId: currentId,
      contactBId: otherContact.id,
      type,
      createdAt: new Date().toISOString()
    };
    setLocalRelations([...localRelations, newRel]);
    setRelationSearch('');
  };

  const handleRemoveRelation = (relId: string) => {
    setLocalRelations(localRelations.filter(r => r.id !== relId));
  };

  const handleAddChild = () => {
    const newChild: ContactChild = { name: '', birthDate: '' };
    setFormData({ ...formData, children: [...(formData.children || []), newChild] });
  };

  const handleUpdateChild = (idx: number, field: keyof ContactChild, value: string) => {
    const updatedChildren = [...(formData.children || [])];
    updatedChildren[idx] = { ...updatedChildren[idx], [field]: value };
    setFormData({ ...formData, children: updatedChildren });
  };

  const handleUpdateFrequency = (days: number) => {
    setFormData({ ...formData, interactionIntervalDays: days });
  };

  const handleRemoveChild = (idx: number) => {
    setFormData({ ...formData, children: (formData.children || []).filter((_, i) => i !== idx) });
  };

  const handleUpdateSocial = (field: keyof SocialLinks, value: string) => {
    setFormData({
      ...formData,
      socialLinks: {
        ...(formData.socialLinks || {}),
        [field]: value
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    let finalAddr = { ...addrData };
    if (!addrData.id && !initialCoords) {
      try {
        const queryParts = [addrData.street, addrData.houseNumber, addrData.postalCode, addrData.city, addrData.country]
          .filter(p => !!p && p.trim() !== '');
        let response = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(queryParts.join(', '))}&limit=1`);
        let data = await response.json();
        if (data && data.length > 0) {
          finalAddr.lat = parseFloat(data[0].lat);
          finalAddr.lng = parseFloat(data[0].lon);
        }
      } catch (error) {
        console.error("Geocoding failed", error);
      }
    }

    const addressId = addrData.id || `addr-${Date.now()}`;
    const finalAddress: Address = { ...finalAddr as Address, id: addressId };

    const contactId = contact?.id || `c-${Date.now()}`;

    const finalContact: Contact = {
      ...formData as Contact,
      id: contactId,
      addressId,
      updatedAt: new Date().toISOString(),
      createdAt: contact?.createdAt || new Date().toISOString(),
      interactions: formData.interactions || []
    };

    // Update local relations with the actual contact ID if it was new
    const finalRelations = localRelations.map(r => ({
      ...r,
      contactAId: r.contactAId === 'new-temp-id' ? contactId : r.contactAId,
      contactBId: r.contactBId === 'new-temp-id' ? contactId : r.contactBId
    }));

    onSave(finalContact, finalAddress, finalRelations);
    setIsSaving(false);
  };

  const selectedType = types.find(t => t.id === formData.typeId) || types[0];
  const initials = `${formData.firstName?.[0] || '?'}${formData.lastName?.[0] || ''}`.toUpperCase();

  return (
    <div className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[150] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
      <div className="relative shrink-0">
        <div className="h-32 w-full relative overflow-hidden bg-gray-100">
          <img 
            src={`https://picsum.photos/seed/${addrData.id || 'new'}/600/300`} 
            className="w-full h-full object-cover brightness-75 blur-[1px]" 
            alt="Cover"
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/30 to-transparent" />
        </div>

        <button 
          onClick={onClose}
          className="absolute top-4 left-4 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-md text-white rounded-full transition-all z-20"
        >
          <X size={20} />
        </button>

        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <div 
              className="w-24 h-24 rounded-full border-4 shadow-xl overflow-hidden bg-white flex items-center justify-center"
              style={{ borderColor: selectedType.color }}
            >
              {formData.photoUrl ? (
                <img src={formData.photoUrl} alt="Preview" className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold text-2xl">
                  {initials}
                </div>
              )}
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center text-white rounded-full">
                <Camera size={24} />
                <span className="text-[10px] font-bold mt-1">WIJZIG</span>
              </div>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
          </div>
          <div className="pb-2">
            <button 
              type="button"
              onClick={() => setFormData({...formData, isFavorite: !formData.isFavorite})}
              className={`p-2 rounded-full shadow-sm border transition-all ${formData.isFavorite ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-gray-300 border-gray-200'}`}
            >
              <Heart size={20} className={formData.isFavorite ? 'fill-current' : ''} />
            </button>
          </div>
        </div>

        <div className="px-6 mt-4">
          <h2 className="text-2xl font-bold text-gray-900 leading-tight">
            {formData.firstName || formData.lastName ? `${formData.firstName} ${formData.lastName || ''}`.trim() : 'Nieuw Contact'}
          </h2>
          <div className="mt-2 flex items-center gap-2">
            <select 
              value={formData.typeId}
              onChange={e => setFormData({ ...formData, typeId: e.target.value })}
              className="text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white cursor-pointer hover:brightness-110 transition-all outline-none border-none shadow-sm"
              style={{ backgroundColor: selectedType.color }}
            >
              {types.map(t => <option key={t.id} value={t.id} className="text-gray-900 bg-white">{t.name}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 pb-32">
        <div className="space-y-4">
          <FormInput icon={<Users size={18} />} label="Voornaam" value={formData.firstName} onChange={v => setFormData({...formData, firstName: v})} placeholder="Bijv. Jan" />
          <FormInput icon={<Users size={18} />} label="Achternaam (optioneel)" value={formData.lastName} onChange={v => setFormData({...formData, lastName: v})} placeholder="Bijv. Jansen" />
          <FormInput icon={<Calendar size={18} />} label="Geboortedatum" type="date" value={formData.birthDate} onChange={v => setFormData({...formData, birthDate: v})} />

          <div className="space-y-4 pt-4 border-t border-gray-100">
             <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-2">
                <Clock size={14} /> Planning & Interactie
             </h3>
             <FormInput label="Laatste Datum" type="date" value={formData.lastInteractionDate?.split('T')[0]} onChange={v => setFormData({...formData, lastInteractionDate: v ? new Date(v).toISOString() : ''})} />

             <div className="space-y-2">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1">
                  <Activity size={10} /> Gewenste Frequentie
                </p>
                <select 
                  className="w-full bg-gray-50 border border-gray-100 rounded-xl p-3 text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-blue-500 transition-all cursor-pointer"
                  value={formData.interactionIntervalDays || 0}
                  onChange={(e) => handleUpdateFrequency(parseInt(e.target.value))}
                >
                  <option value={0}>Handmatig / Geen planning</option>
                  <option value={7}>Wekelijks</option>
                  <option value={14}>Elke 2 weken</option>
                  <option value={30}>Maandelijks</option>
                  <option value={60}>Elke 2 maanden</option>
                  <option value={91}>Kwartaal</option>
                  <option value={182}>Halfjaarlijks</option>
                  <option value={365}>Jaarlijks</option>
                </select>
             </div>

             <div className="space-y-2">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Type contact (Laatste)</p>
                <div className="grid grid-cols-3 gap-2">
                   <button 
                      type="button"
                      onClick={() => setLastInteractionType('physical')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[9px] font-bold transition-all ${lastInteractionType === 'physical' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                   >
                      <UserCheck size={14} /> Fysiek
                   </button>
                   <button 
                      type="button"
                      onClick={() => setLastInteractionType('app')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[9px] font-bold transition-all ${lastInteractionType === 'app' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                   >
                      <Smartphone size={14} /> App
                   </button>
                   <button 
                      type="button"
                      onClick={() => setLastInteractionType('phone')}
                      className={`flex flex-col items-center gap-1 p-2 rounded-xl border text-[9px] font-bold transition-all ${lastInteractionType === 'phone' ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-400 border-gray-100'}`}
                   >
                      <Phone size={14} /> Bel
                   </button>
                </div>
             </div>

             <div className="space-y-1">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Toelichting</p>
                <textarea 
                   className="w-full bg-gray-50 border border-gray-100 rounded-xl p-3 text-xs outline-none focus:ring-2 focus:ring-blue-500 min-h-[100px] resize-none"
                   placeholder="Bijv: Op verjaardag in Varik..."
                   value={lastInteractionNotes}
                   onChange={(e) => setLastInteractionNotes(e.target.value)}
                />
             </div>
          </div>
        </div>

        {/* Social Media Sectie */}
        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            Social Media
          </h3>
          <div className="space-y-3 bg-gray-50/50 p-4 rounded-2xl border border-gray-100">
            <FormInput icon={<Facebook size={18} />} label="Facebook URL" value={formData.socialLinks?.facebook} onChange={v => handleUpdateSocial('facebook', v)} placeholder="https://facebook.com/..." />
            <FormInput icon={<Instagram size={18} />} label="Instagram URL" value={formData.socialLinks?.instagram} onChange={v => handleUpdateSocial('instagram', v)} placeholder="https://instagram.com/..." />
            <FormInput icon={<Linkedin size={18} />} label="LinkedIn URL" value={formData.socialLinks?.linkedin} onChange={v => handleUpdateSocial('linkedin', v)} placeholder="https://linkedin.com/in/..." />
          </div>
        </div>

        {/* Relaties Sectie */}
        <div className="space-y-4 pt-4 border-t border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <GitPullRequest size={14} /> Relaties & Familie
          </h3>

          <div className="space-y-3 bg-gray-50 p-4 rounded-2xl border border-gray-100">
            <div className="relative">
