          <p className="text-gray-500">Hier is een overzicht van je netwerk op dit moment.</p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, i) => (
            <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 group hover:shadow-md transition-shadow">
              <div className={`p-3 rounded-2xl ${stat.color} text-white shadow-inner group-hover:scale-110 transition-transform`}>
                {stat.icon}
              </div>
              <div>
                <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
                <p className="text-2xl font-black text-gray-900">{stat.value}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-12">
          <div className="lg:col-span-2 space-y-6">
            <div className="flex items-center justify-between">
              <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                <Gift className="text-amber-500" /> Komende Verjaardagen
              </h3>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {upcomingBirthdays.length > 0 ? upcomingBirthdays.map(c => {
                const typeColor = types.find(t => t.id === c.typeId)?.color || '#3b82f6';
                return (
                  <div 
                    key={c.id} 
                    onClick={() => onContactClick(c.id)}
                    className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4 cursor-pointer hover:bg-gray-50 hover:border-blue-200 transition-all group"
                  >
                    <div className="relative">
                      <img 
                        src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} 
                        className="w-16 h-16 rounded-2xl object-cover border-4" 
                        style={{ borderColor: typeColor }}
                      />
                      <div className="absolute -bottom-1 -right-1 bg-amber-500 text-white p-1 rounded-lg">
                        <Gift size={12} />
                      </div>
                    </div>
                    <div className="flex-1">
                      <p className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">{`${c.firstName} ${c.lastName || ''}`.trim()}</p>
                      <p className="text-xs text-gray-500 font-medium">Wordt {c.nextAge} jaar</p>
                      <div className="mt-2 flex items-center gap-1">
                        <span className="text-[10px] bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full font-black uppercase">
                          Over {c.daysUntil} {c.daysUntil === 1 ? 'dag' : 'dagen'}
