import React, { useState } from 'react';
import { ChevronLeft, ChevronRight, Gift } from 'lucide-react';
import { Contact, ContactType } from '../types.ts';

interface CalendarViewProps {
  contacts: Contact[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ contacts, types, onContactClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const monthNames = [
    'Januari', 'Februari', 'Maart', 'April', 'Mei', 'Juni',
    'Juli', 'Augustus', 'September', 'Oktober', 'November', 'December'
  ];

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const days = [];
  const totalDays = daysInMonth(year, month);
  const startOffset = (firstDayOfMonth(year, month) + 6) % 7; 

  for (let i = 0; i < startOffset; i++) {
    days.push(null);
  }

  for (let d = 1; d <= totalDays; d++) {
    days.push(d);
  }

  const handlePrevMonth = () => setCurrentDate(new Date(year, month - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(year, month + 1, 1));

  return (
    <div className="p-8 max-w-5xl mx-auto space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-3xl font-bold text-gray-900">{monthNames[month]} {year}</h2>
          <p className="text-gray-500">Plan je sociale uitjes en verjaardagskaarten.</p>
        </div>
        <div className="flex gap-2">
          <button onClick={handlePrevMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors border border-gray-200"><ChevronLeft size={20}/></button>
          <button onClick={() => setCurrentDate(new Date())} className="px-4 py-2 hover:bg-gray-100 rounded-xl transition-colors border border-gray-200 font-bold text-sm">Vandaag</button>
          <button onClick={handleNextMonth} className="p-2 hover:bg-gray-100 rounded-full transition-colors border border-gray-200"><ChevronRight size={20}/></button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden flex flex-col">
        <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-100">
          {['Ma', 'Di', 'Wo', 'Do', 'Vr', 'Za', 'Zo'].map(day => (
            <div key={day} className="py-4 text-center text-xs font-black text-gray-400 uppercase tracking-widest">{day}</div>
          ))}
        </div>

        <div className="flex-1 grid grid-cols-7 grid-rows-5 overflow-auto">
          {days.map((day, idx) => {
            const birthdayContacts = day ? contacts.filter(c => {
              if (!c.birthDate) return false;
              const bday = new Date(c.birthDate);
              return bday.getDate() === day && bday.getMonth() === month;
            }) : [];

            return (
              <div 
                key={idx} 
                className={`min-h-[120px] p-2 border-r border-b border-gray-50 flex flex-col gap-1 transition-colors ${day ? 'hover:bg-blue-50/20' : 'bg-gray-50/30'}`}
              >
                {day && (
                  <>
                    <span className={`text-sm font-bold ${day === new Date().getDate() && month === new Date().getMonth() ? 'bg-blue-600 text-white w-7 h-7 flex items-center justify-center rounded-full' : 'text-gray-400'}`}>
                      {day}
                    </span>
                    <div className="space-y-1">
                      {birthdayContacts.map(c => {
                        const typeColor = types.find(t => t.id === c.typeId)?.color || '#fef3c7';
                        return (
                          <div 
                            key={c.id} 
                            onClick={() => onContactClick(c.id)}
                            className="flex items-center gap-1.5 p-1.5 bg-amber-50 rounded-lg cursor-pointer hover:bg-amber-100 transition-colors border border-amber-100"
                          >
                            <img 
                              src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} 
                              className="w-5 h-5 rounded-full border" 
                              style={{ borderColor: typeColor }}
                            />
                            <span className="text-[10px] font-bold text-amber-800 truncate">{c.firstName}</span>
                          </div>
                        );
                      })}
                    </div>
                  </>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useMemo } from 'react';
import { 
  Clock, AlertTriangle, CheckCircle2, Calendar, 
  ChevronRight, ArrowRight, UserCheck, Smartphone, Phone,
  Activity
} from 'lucide-react';
import { Contact, Address, ContactType } from '../types.ts';

interface PlanningViewProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const PlanningView: React.FC<PlanningViewProps> = ({ contacts, addresses, types, onContactClick }) => {
  const planningData = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const plannedContacts = contacts
      .filter(c => c.interactionIntervalDays && c.interactionIntervalDays > 0)
      .map(c => {
        const lastInteractionStr = c.lastInteractionDate;
        const lastDate = (lastInteractionStr && lastInteractionStr.trim() !== "") 
          ? new Date(lastInteractionStr) 
          : new Date(c.createdAt);

        lastDate.setHours(0, 0, 0, 0);

        const nextDate = new Date(lastDate);
        nextDate.setDate(lastDate.getDate() + (c.interactionIntervalDays || 0));

        const diffDays = Math.ceil((nextDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));

        let status: 'overdue' | 'soon' | 'ontrack' = 'ontrack';
        if (diffDays < 0) status = 'overdue';
        else if (diffDays <= 7) status = 'soon';

        return { ...c, nextDate, diffDays, status };
      });

    return {
      overdue: plannedContacts.filter(c => c.status === 'overdue').sort((a, b) => a.diffDays - b.diffDays),
      soon: plannedContacts.filter(c => c.status === 'soon').sort((a, b) => a.diffDays - b.diffDays),
      onTrack: plannedContacts.filter(c => c.status === 'ontrack').sort((a, b) => a.diffDays - b.diffDays),
    };
  }, [contacts]);

  return (
    <div className="h-full w-full overflow-y-auto bg-gray-50/50">
      <div className="p-8 max-w-6xl mx-auto space-y-10 pb-24">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 mb-1 flex items-center gap-3">
            <Activity className="text-blue-600" /> Planning
          </h2>
          <p className="text-gray-500">Houd je sociale relaties gezond en op schema.</p>
        </div>

        {/* Overdue Section */}
        <section className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-red-500 uppercase tracking-[0.2em] flex items-center gap-2">
              <AlertTriangle size={14} /> Overschreden ({planningData.overdue.length})
            </h3>
          </div>
          {planningData.overdue.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {planningData.overdue.map(c => (
                <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} />
              ))}
            </div>
          ) : (
            <div className="p-10 bg-white rounded-[2rem] border border-dashed border-gray-200 text-center">
              <p className="text-gray-400 text-sm font-medium">Lekker bezig! Geen verlopen contactmomenten.</p>
            </div>
          )}
        </section>

        {/* Soon Section */}
        <section className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-amber-500 uppercase tracking-[0.2em] flex items-center gap-2">
              <Clock size={14} /> Binnenkort ({planningData.soon.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {planningData.soon.map(c => (
              <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} />
            ))}
            {planningData.soon.length === 0 && (
               <p className="col-span-full text-xs text-gray-400 italic">Geen contacten in de komende 7 dagen.</p>
            )}
          </div>
        </section>

        {/* On Track Section */}
        <section className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-black text-emerald-500 uppercase tracking-[0.2em] flex items-center gap-2">
              <CheckCircle2 size={14} /> Op schema ({planningData.onTrack.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {planningData.onTrack.map(c => (
              <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} />
            ))}
            {planningData.onTrack.length === 0 && (
               <p className="col-span-full text-xs text-gray-400 italic">Geen geplande contacten gevonden. Geef bij een contact een interval aan!</p>
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

interface PlanningCardProps {
  contact: any;
  types: ContactType[];
  onContactClick: (id: string) => void;
}

const PlanningCard: React.FC<PlanningCardProps> = ({ contact, types, onContactClick }) => {
  const type = types.find(t => t.id === contact.typeId);
  const isOverdue = contact.status === 'overdue';
  const isSoon = contact.status === 'soon';

  const getStatusColor = () => {
    if (isOverdue) return 'bg-red-500';
    if (isSoon) return 'bg-amber-500';
    return 'bg-emerald-500';
  };

  const getStatusBg = () => {
    if (isOverdue) return 'bg-red-50 border-red-100';
    if (isSoon) return 'bg-amber-50 border-amber-100';
    return 'bg-emerald-50 border-emerald-100';
  };

  const getStatusText = () => {
    if (isOverdue) return `Overschreden: ${Math.abs(contact.diffDays)} ${Math.abs(contact.diffDays) === 1 ? 'dag' : 'dagen'}`;
    if (isSoon) return contact.diffDays === 0 ? 'Vandaag' : `Nog ${contact.diffDays} dagen`;
    return `Nog ${contact.diffDays} dagen`;
  };

  const getIntervalLabel = (days: number) => {
    if (days === 7) return 'Wekelijks';
    if (days === 14) return 'Elke 2 weken';
    if (days === 30) return 'Maandelijks';
    if (days === 60) return 'Elke 2 maanden';
    if (days === 91) return 'Kwartaal';
    if (days === 182) return 'Halfjaarlijks';
    if (days === 365) return 'Jaarlijks';
    return `${days} dagen`;
  };

  return (
    <div 
      onClick={() => onContactClick(contact.id)}
      className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all group cursor-pointer flex flex-col gap-4"
    >
      <div className="flex items-center gap-4">
        <div className="relative">
          <img 
            src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} 
            className="w-14 h-14 rounded-2xl object-cover border-2 shadow-sm" 
            style={{ borderColor: type?.color || '#F3F4F6' }}
          />
          <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white shadow-sm ${getStatusColor()}`} />
        </div>
        <div className="flex-1 min-w-0">
          <h4 className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors truncate">
            {contact.firstName} {contact.lastName}
          </h4>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest truncate">{type?.name}</p>
        </div>
      </div>

      <div className={`p-3 rounded-2xl border ${getStatusBg()} flex flex-col gap-1`}>
        <div className="flex items-center justify-between">
          <span className={`text-[10px] font-black uppercase tracking-widest ${isOverdue ? 'text-red-600' : isSoon ? 'text-amber-600' : 'text-emerald-600'}`}>
            {getStatusText()}
          </span>
          <div className="flex items-center gap-1 text-[9px] text-gray-400 font-bold bg-white/50 px-2 py-0.5 rounded-full">
            <Activity size={10} /> {getIntervalLabel(contact.interactionIntervalDays)}
          </div>
        </div>
        <div className="flex items-center gap-1.5 mt-1 text-[11px] font-bold text-gray-700">
           <Calendar size={12} className="opacity-40" /> {new Date(contact.nextDate).toLocaleDateString()}
        </div>
      </div>

      <button className="w-full py-2.5 bg-gray-50 hover:bg-blue-50 text-gray-400 hover:text-blue-600 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all">
        Open Profiel <ArrowRight size={14} />
      </button>
    </div>
  );
};

export default PlanningView;

import React, { useState } from 'react';
import { 
  auth,
  db,
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  doc,
  setDoc
} from "../firebase.ts";
import { Users, Mail, Lock, Loader2, AlertCircle } from 'lucide-react';

const AuthScreen: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      if (isLogin) {
        await signInWithEmailAndPassword(auth, email, password);
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const user = userCredential.user;

        // Add user to 'users' collection
        await setDoc(doc(db, 'users', user.uid), {
          email: user.email,
          createdAt: new Date().toISOString(),
          lastLogin: new Date().toISOString()
        });
      }
    } catch (err: any) {
      console.error(err);
      let message = "Er is iets misgegaan. Probeer het opnieuw.";
      if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
        message = "Ongeldig e-mailadres of wachtwoord.";
      } else if (err.code === 'auth/email-already-in-use') {
        message = "Dit e-mailadres is al in gebruik.";
      } else if (err.code === 'auth/weak-password') {
        message = "Wachtwoord moet minimaal 6 tekens bevatten.";
      }
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full bg-blue-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md overflow-hidden border border-white/50 animate-in zoom-in-95 duration-300">
        <div className="p-8 sm:p-12">
          <div className="flex flex-col items-center mb-10">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-200 mb-4 animate-bounce">
              <Users size={32} />
            </div>
            <h1 className="text-3xl font-black text-blue-900 tracking-tight">MapCRM</h1>
            <p className="text-gray-500 text-sm mt-2 font-medium">
              {isLogin ? 'Welkom terug! Log in op je account.' : 'Maak een nieuw account aan.'}
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-4">
              <div className="relative">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                  <Mail size={18} />
                </div>
                <input
                  type="email"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-semibold text-black placeholder:text-gray-400"
                  placeholder="E-mailadres"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>

              <div className="relative">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                  <Lock size={18} />
                </div>
                <input
                  type="password"
                  required
                  className="w-full pl-12 pr-4 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-semibold text-black placeholder:text-gray-400"
                  placeholder="Wachtwoord"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-xs font-bold flex items-center gap-3 animate-in fade-in slide-in-from-top-2 duration-200">
                <AlertCircle size={16} />
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-sm tracking-wide transition-all shadow-xl shadow-blue-100 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {loading ? (
                <Loader2 size={20} className="animate-spin" />
              ) : (
                isLogin ? 'INLOGGEN' : 'REGISTREREN'
              )}
            </button>
          </form>

          <div className="mt-8 text-center">
            <button
              onClick={() => {
                setIsLogin(!isLogin);
                setError(null);
              }}
              className="text-sm font-bold text-blue-600 hover:text-blue-800 transition-colors"
            >
              {isLogin ? 'Nog geen account? Registreer hier' : 'Heb je al een account? Log hier in'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthScreen;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Map as MapIcon, 
  Users, 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Plus, 
  Search, 
  Filter,
  LogOut,
  Bell,
  Settings,
  ChevronRight,
  ChevronLeft,
  Download,
  Upload,
  AlertTriangle,
  CheckCircle2,
  X,
  FileJson,
  Loader2,
  ShieldAlert,
  ExternalLink,
  Clock,
  Activity
} from 'lucide-react';
import { 
  auth, 
  db, 
  onAuthStateChanged, 
  signOut, 
  collection, 
  doc, 
  getDocs, 
  setDoc, 
  deleteDoc, 
  writeBatch 
} from "./firebase.ts";
import { Contact, Address, ContactType, ViewMode, Relation } from './types.ts';
import { DEFAULT_TYPES, INITIAL_CONTACTS, INITIAL_ADDRESSES } from './constants.tsx';
import MapView from './components/MapView.tsx';
import ContactList from './components/ContactList.tsx';
import Dashboard from './components/Dashboard.tsx';
import StatsView from './components/StatsView.tsx';
import ContactForm from './components/ContactForm.tsx';
import ContactDetails from './components/ContactDetails.tsx';
import CalendarView from './components/CalendarView.tsx';
import AuthScreen from './components/AuthScreen.tsx';
import PlanningView from './components/PlanningView.tsx';
import { compressImageBase64 } from './utils.ts';

const App: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isDataSyncing, setIsDataSyncing] = useState(false);
  const [hasPermissionError, setHasPermissionError] = useState(false);

  const [contacts, setContacts] = useState<Contact[]>([]);
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [types, setTypes] = useState<ContactType[]>(DEFAULT_TYPES);
  const [relations, setRelations] = useState<Relation[]>([]);

  const [viewMode, setViewMode] = useState<ViewMode>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [initialCoords, setInitialCoords] = useState<[number, number] | null>(null);
  const [initialAddressId, setInitialAddressId] = useState<string | null>(null);

  // Import states
  const [importPendingData, setImportPendingData] = useState<any>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importSuccess, setImportSuccess] = useState(false);
  const [importError, setImportError] = useState<string | null>(null);

  // Authentication observer
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user: any) => {
      setCurrentUser(user);
      setIsAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch data from Firestore when user logs in
  useEffect(() => {
    if (!currentUser) {
      setContacts([]);
      setAddresses([]);
      setRelations([]);
      setTypes(DEFAULT_TYPES);
      setHasPermissionError(false);
      return;
    }

    const fetchData = async () => {
      setIsDataSyncing(true);
      setHasPermissionError(false);
      try {
        const userRef = doc(db, 'users', currentUser.uid);

        // Fetch subcollections
        const contactsSnap = await getDocs(collection(userRef, 'contacts'));
        const addressesSnap = await getDocs(collection(userRef, 'addresses'));
        const relationsSnap = await getDocs(collection(userRef, 'relations'));
        const typesSnap = await getDocs(collection(userRef, 'types'));

        // Safety: Filter out nulls or invalid contacts that might have been saved accidentally
        const loadedContacts = contactsSnap.docs
          .map(d => d.data() as Contact)
          .filter(c => c && c.firstName);

        const loadedAddresses = addressesSnap.docs
          .map(d => d.data() as Address)
          .filter(a => a && a.street);

        const loadedRelations = relationsSnap.docs
          .map(d => d.data() as Relation)
          .filter(r => r && r.contactAId && r.contactBId);

        const loadedTypes = typesSnap.docs
          .map(d => d.data() as ContactType)
          .filter(t => t && t.name);

        setContacts(loadedContacts);
        setAddresses(loadedAddresses);
        setRelations(loadedRelations);

        // Always ensure DEFAULT_TYPES are present, merge with loaded ones
        const mergedTypes = [...DEFAULT_TYPES];
        loadedTypes.forEach(lt => {
          const idx = mergedTypes.findIndex(mt => mt.id === lt.id);
          if (idx > -1) {
            mergedTypes[idx] = lt;
          } else {
            mergedTypes.push(lt);
          }
        });
        setTypes(mergedTypes);

      } catch (err: any) {
        console.error("Error fetching Firestore data:", err);
        if (err.code === 'permission-denied') {
          setHasPermissionError(true);
        }
      } finally {
        setIsDataSyncing(false);
      }
    };

    fetchData();
  }, [currentUser]);

  const filteredContacts = useMemo(() => {
    const q = searchQuery.toLowerCase();
    return contacts.filter(c => {
      // Robust safety guard
      if (!c || typeof c.firstName !== 'string') return false;

      const addr = addresses.find(a => a.id === c.addressId);
      return (
        c.firstName.toLowerCase().includes(q) ||
        (c.lastName || '').toLowerCase().includes(q) ||
        (addr?.city || '').toLowerCase().includes(q) ||
        (addr?.street || '').toLowerCase().includes(q)
      );
    });
  }, [contacts, addresses, searchQuery]);

  const selectedContact = useMemo(() => 
    selectedContactId ? contacts.find(c => c.id === selectedContactId) : null
  , [selectedContactId, contacts]);

  const selectedAddress = useMemo(() => 
    selectedContact ? addresses.find(a => a.id === selectedContact.addressId) : null
  , [selectedContact, addresses]);

  const selectedType = useMemo(() => 
    selectedContact ? types.find(t => t.id === selectedContact.typeId) : null
  , [selectedContact, types]);

  const otherResidents = useMemo(() => 
    selectedContact ? contacts.filter(c => c.addressId === selectedContact.addressId && c.id !== selectedContact.id) : []
  , [selectedContact, contacts]);

  const handleAddContact = (coords?: [number, number], addressId?: string) => {
    setInitialCoords(coords || null);
    setInitialAddressId(addressId || null);
    setEditContact(null);
    setIsFormOpen(true);
  };

  const handleEditContact = (contact: Contact) => {
    setEditContact(contact);
    setInitialAddressId(null);
    setInitialCoords(null);
    setIsFormOpen(true);
  };

  const handleUpdateContact = async (updatedContact: Contact) => {
    if (!currentUser) return;

    // UI update (optimistic)
    setContacts(prev => prev.map(c => c.id === updatedContact.id ? updatedContact : c));

    // Firestore update
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      await setDoc(doc(userRef, 'contacts', updatedContact.id), updatedContact);
    } catch (err) {
      console.error("Firestore update failed", err);
    }
  };

  const handleDeleteContact = async (id: string) => {
    if (!currentUser) return;

    // UI Update
    setSelectedContactId(null);
    setContacts(prev => prev.filter(c => c.id !== id));

    // DB Update
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      await deleteDoc(doc(userRef, 'contacts', id));

      // Also cleanup relations in DB
      const relationsToDelete = relations.filter(r => r.contactAId === id || r.contactBId === id);
      for (const rel of relationsToDelete) {
        await deleteDoc(doc(userRef, 'relations', rel.id));
      }
    } catch (err) {
      console.error("Delete from Firestore failed", err);
    }
  };

  const handleSetMapAvatar = async (addressId: string, contactId: string) => {
    if (!currentUser) return;

    setAddresses(prev => prev.map(a => 
      a.id === addressId ? { ...a, mapAvatarId: contactId } : a
    ));

    try {
      const userRef = doc(db, 'users', currentUser.uid);
      const addr = addresses.find(a => a.id === addressId);
      if (addr) {
        await setDoc(doc(userRef, 'addresses', addressId), { ...addr, mapAvatarId: contactId });
      }
    } catch (err) {
      console.error("Avatar update failed", err);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Logout failed", error);
    }
  };

  const saveContact = async (contact: Contact, address: Address, contactRelations: Relation[]) => {
    if (!currentUser) return;

    // UI update (optimistic)
    setAddresses(prev => {
      const exists = prev.find(a => a.id === address.id);
      return exists ? prev.map(a => a.id === address.id ? address : a) : [...prev, address];
    });
    setContacts(prev => {
      const exists = prev.find(c => c.id === contact.id);
      return exists ? prev.map(c => c.id === contact.id ? contact : c) : [...prev, contact];
    });
    setRelations(prev => {
      const otherRelations = prev.filter(r => r.contactAId !== contact.id && r.contactBId !== contact.id);
      return [...otherRelations, ...contactRelations];
    });

    // Firestore update
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      const batch = writeBatch(db);

      batch.set(doc(userRef, 'addresses', address.id), address);
      batch.set(doc(userRef, 'contacts', contact.id), contact);

      for (const rel of contactRelations) {
        batch.set(doc(userRef, 'relations', rel.id), rel);
      }

      await batch.commit();
    } catch (err) {
      console.error("Firestore save failed", err);
    }

    setIsFormOpen(false);
  };

  const handleExportData = () => {
    const data = {
      contacts,
      addresses,
      types,
      relations,
      version: '2.2',
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mapcrm_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const data = JSON.parse(text);

        if (data && typeof data === 'object' && Array.isArray(data.contacts) && Array.isArray(data.addresses)) {
          setImportPendingData(data);
          setShowImportModal(true);
          setImportError(null);
        } else {
          setImportError('Ongeldige bestandsstructuur. Geen contacten of adressen gevonden.');
        }
      } catch (err) {
        setImportError('Kan bestand niet lezen als JSON. Controleer het bestand.');
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const executeImport = async () => {
    if (!importPendingData || !currentUser) return;

    setIsDataSyncing(true);
    try {
      const data = importPendingData;
      const userRef = doc(db, 'users', currentUser.uid);
      const batch = writeBatch(db);

      // Perform asynchronous compression for all imported photos
      const sanitizedContacts = await Promise.all(data.contacts
        .filter((c: any) => c && c.firstName)
        .map(async (c: any) => {
          let photoUrl = c.photoUrl;
          if (photoUrl && photoUrl.startsWith('data:image')) {
            // Compress imported Base64 images to prevent Firestore document size limit issues
            photoUrl = await compressImageBase64(photoUrl);
          }

          return {
            ...c,
            photoUrl,
            phones: Array.isArray(c.phones) ? c.phones : (c.phone ? [c.phone] : []),
            emails: Array.isArray(c.emails) ? c.emails : (c.email ? [c.email] : []),
            pets: Array.isArray(c.pets) ? c.pets : [],
            children: Array.isArray(c.children) ? c.children : [],
            socialLinks: c.socialLinks || {},
            hobbies: Array.isArray(c.hobbies) ? c.hobbies : [],
            interactions: Array.isArray(c.interactions) ? c.interactions : [],
            isFavorite: !!c.isFavorite,
            createdAt: c.createdAt || new Date().toISOString(),
            updatedAt: c.updatedAt || new Date().toISOString(),
          };
        })
      );

      for (const c of sanitizedContacts) batch.set(doc(userRef, 'contacts', c.id), c);
      for (const a of data.addresses) batch.set(doc(userRef, 'addresses', a.id), a);
      if (data.types) for (const t of data.types) batch.set(doc(userRef, 'types', t.id), t);
      if (data.relations) for (const r of data.relations) batch.set(doc(userRef, 'relations', r.id), r);

      await batch.commit();

      setContacts(sanitizedContacts);
      setAddresses(data.addresses);

      const mergedTypes = [...DEFAULT_TYPES];
      if (data.types) {
        data.types.forEach((lt: ContactType) => {
          const idx = mergedTypes.findIndex(mt => mt.id === lt.id);
          if (idx > -1) {
            mergedTypes[idx] = lt;
          } else {
            mergedTypes.push(lt);
          }
        });
      }
      setTypes(mergedTypes);

      if (data.relations) setRelations(data.relations);

      setSelectedContactId(null);
      setImportPendingData(null);
      setShowImportModal(false);
      setImportSuccess(true);
      setTimeout(() => setImportSuccess(false), 3000);
    } catch (err) {
      setImportError('Er is een fout opgetreden tijdens de synchronisatie.');
    } finally {
      setIsDataSyncing(false);
    }
  };

  if (isAuthLoading) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-blue-50">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-200 animate-pulse">
            <Users size={28} />
          </div>
          <p className="text-blue-900 font-bold tracking-tight">Authenticatie...</p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <AuthScreen />;
  }

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50 shadow-sm`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1 overflow-y-auto">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label="Kaart" 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label="Contacten" 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label="Dashboard" 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Activity size={20} />} 
            label="Planning" 
            active={viewMode === 'planning'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('planning')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label="Verjaardagen" 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label="Statistieken" 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        <div className="px-2 pt-4 border-t border-gray-100 flex flex-col gap-1">
          <NavItem 
            icon={<Download size={20} />} 
            label="Exporteer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleExportData} 
          />
          <NavItem 
            icon={<Upload size={20} />} 
            label="Importeer Data" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={() => fileInputRef.current?.click()} 
          />
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportData} 
            accept=".json" 
            className="hidden" 
          />
        </div>

        <div className="p-2 border-t border-gray-100 mt-2">
          <NavItem 
            icon={<LogOut size={20} />} 
            label="Uitloggen" 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleLogout} 
          />
        </div>

        <div className="p-4">
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className="w-full flex items-center justify-center p-2 rounded-lg hover:bg-gray-100 text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <ChevronLeft size={20} /> : <ChevronRight size={20} />}
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col relative min-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 z-40 shrink-0">
          <div className="flex-1 max-xl flex items-center gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Zoek contacten, adressen..." 
                className="w-full pl-10 pr-4 py-2 bg-gray-100 border-none rounded-full focus:ring-2 focus:ring-blue-500 text-sm transition-all text-black"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            {isDataSyncing && (
              <div className="flex items-center gap-2 text-[10px] font-black text-blue-500 uppercase tracking-widest animate-pulse">
                <Loader2 size={12} className="animate-spin" />
                Sync
              </div>
            )}
          </div>

          <div className="flex items-center gap-4 ml-4">
            <button 
              onClick={() => handleAddContact()}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-full font-bold text-sm transition-all shadow-md active:scale-95"
            >
              <Plus size={18} />
              <span className="hidden sm:inline">Nieuw Contact</span>
            </button>
            <div className="h-8 w-px bg-gray-200" />
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Bell size={20} /></button>
            <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full"><Settings size={20} /></button>
            <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold text-xs ring-2 ring-white uppercase">
              {currentUser?.email?.slice(0, 2) || 'US'}
            </div>
          </div>
        </header>

        <div className="flex-1 relative overflow-hidden">
          {hasPermissionError ? (
            <div className="absolute inset-0 z-50 flex items-center justify-center p-6 bg-gray-50">
              <div className="max-w-md w-full bg-white rounded-[2.5rem] shadow-2xl p-10 text-center border border-red-100 space-y-6 animate-in zoom-in-95 duration-300">
                <div className="mx-auto w-20 h-20 bg-red-50 rounded-3xl flex items-center justify-center text-red-500 shadow-inner">
                  <ShieldAlert size={40} />
                </div>
                <div className="space-y-2">
                  {/* Fixed typo: added missing opening bracket for h3 */}
                  <h3 className="text-2xl font-black text-gray-900">Configuratie Vereist</h3>
                  <p className="text-gray-500 text-sm leading-relaxed">
                    Firestore blokkeert de toegang. Je moet de <strong>Security Rules</strong> aanpassen in de Firebase Console om je eigen data te kunnen opslaan.
                  </p>
                </div>
                <div className="bg-red-50/50 p-4 rounded-2xl border border-red-100 text-left">
                  <p className="text-[10px] font-black text-red-400 uppercase tracking-widest mb-2">Benodigde regels:</p>
                  <code className="text-[10px] text-red-700 font-mono block overflow-x-auto whitespace-pre p-2 bg-white rounded-lg border border-red-100">
                    {`match /users/{userId}/{doc=**} {\n  allow read, write: if \n  request.auth.uid == userId;\n}`}
                  </code>
                </div>
                <a 
                  href="https://console.firebase.google.com/" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="w-full flex items-center justify-center gap-2 py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold transition-all shadow-xl shadow-blue-100 active:scale-95"
                >
                  Firebase Console Openen
                  <ExternalLink size={16} />
                </a>
              </div>
            </div>
          ) : (
            <>
              {viewMode === 'map' && (
                <MapView 
                  contacts={filteredContacts} 
                  addresses={addresses} 
                  types={types}
                  onContactClick={(id) => setSelectedContactId(id)}
                  onMapClick={handleAddContact}
                  onAddResident={(addrId) => handleAddContact(undefined, addrId)}
                />
              )}
              {viewMode === 'list' && (
                <ContactList 
                  contacts={filteredContacts} 
                  addresses={addresses} 
                  types={types}
                  onContactClick={(id) => setSelectedContactId(id)}
                />
              )}
              {viewMode === 'dashboard' && (
                <Dashboard 
                  contacts={contacts} 
                  addresses={addresses} 
                  types={types}
                  onContactClick={(id) => {
                    setSelectedContactId(id);
                    setViewMode('map');
                  }}
                  onAddContact={() => handleAddContact()}
                />
              )}
              {viewMode === 'planning' && (
                <PlanningView 
                  contacts={contacts} 
                  addresses={addresses} 
                  types={types}
                  onContactClick={(id) => setSelectedContactId(id)}
                />
              )}
              {viewMode === 'calendar' && (
                <CalendarView 
                  contacts={contacts}
                  types={types}
                  onContactClick={(id) => {
                    setSelectedContactId(id);
                    setViewMode('map');
                  }}
                />
              )}
              {viewMode === 'stats' && (
                <StatsView 
                  contacts={contacts} 
                  types={types} 
                  addresses={addresses}
                />
              )}

              {selectedContact && selectedAddress && selectedType && (
                <ContactDetails 
                  contact={selectedContact}
                  address={selectedAddress}
                  type={selectedType}
                  contacts={contacts}
                  relations={relations}
                  otherResidents={otherResidents}
                  onClose={() => setSelectedContactId(null)}
                  onEdit={handleEditContact}
                  onUpdate={handleUpdateContact}
                  onDelete={handleDeleteContact}
                  onAddResident={(addrId) => handleAddContact(undefined, addrId)}
                  onSetMapAvatar={handleSetMapAvatar}
                  onContactClick={(id) => setSelectedContactId(id)}
                />
              )}
            </>
          )}

          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-[200] flex flex-col gap-2 pointer-events-none">
            {importSuccess && (
              <div className="animate-in slide-in-from-top-4 duration-300 pointer-events-auto">
                <div className="bg-emerald-600 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border border-emerald-500">
                  <CheckCircle2 size={24} />
                  <div>
                    <p className="font-bold text-sm">Import succesvol!</p>
                    <p className="text-[10px] opacity-80 uppercase font-black tracking-widest">Je gegevens zijn gesynchroniseerd</p>
                  </div>
                </div>
              </div>
            )}
            {importError && (
              <div className="animate-in slide-in-from-top-4 duration-300 pointer-events-auto">
                <div className="bg-red-600 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 border border-red-500">
                  <AlertTriangle size={24} />
                  <div>
                    <p className="font-bold text-sm">Synchronisatie mislukt</p>
                    <p className="text-[10px] opacity-80 uppercase font-black tracking-widest">{importError}</p>
                  </div>
                  <button onClick={() => setImportError(null)} className="ml-2 hover:bg-white/20 p-1 rounded-full"><X size={16}/></button>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {isFormOpen && (
        <ContactForm 
          contact={editContact}
          types={types}
          addresses={addresses}
          contacts={contacts}
          relations={relations}
          initialCoords={initialCoords}
          initialAddressId={initialAddressId}
          onClose={() => setIsFormOpen(false)}
          onSave={saveContact}
        />
      )}

      {showImportModal && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-6 bg-blue-900/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200 border border-white/50">
            <div className="p-8 text-center space-y-6">
              <div className="mx-auto w-20 h-20 bg-amber-50 rounded-3xl flex items-center justify-center text-amber-500 shadow-inner">
                <FileJson size={40} />
              </div>
              <div>
                <h3 className="text-2xl font-black text-gray-900 mb-2">Back-up Terugzetten?</h3>
                <p className="text-gray-500 text-sm leading-relaxed">
                  Dit bestand zal naar de database worden geschreven en je <span className="font-bold text-blue-600">bestaande gegevens overschrijven</span>.
                </p>
              </div>
              <div className="bg-gray-50 rounded-2xl p-4 flex flex-col gap-2 border border-gray-100">
                <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-widest">
                  <span>Contacten</span>
                  <span className="text-blue-600">{importPendingData?.contacts?.length || 0}</span>
                </div>
                <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-widest">
                  <span>Locaties</span>
                  <span className="text-blue-600">{importPendingData?.addresses?.length || 0}</span>
                </div>
              </div>
              <div className="flex flex-col gap-3 pt-2">
                <button 
                  onClick={executeImport}
                  disabled={isDataSyncing}
                  className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-bold transition-all shadow-xl shadow-blue-200 active:scale-95 disabled:opacity-50"
                >
                  {isDataSyncing ? 'Synchroniseren...' : 'Ja, overschrijf alles'}
                </button>
                <button 
                  onClick={() => {
                    setImportPendingData(null);
                    setShowImportModal(false);
                  }}
                  className="w-full py-4 bg-white hover:bg-gray-50 text-gray-500 rounded-2xl font-bold transition-all border border-gray-100"
                >
                  Annuleren
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

