  );
};

export default MapView;

import React, { useState, useMemo } from 'react';
import { 
  Filter, MoreHorizontal, Mail, Phone, 
  MapPin, Star, Heart, Grid, List as ListIcon,
  ChevronDown, Clock, Activity
} from 'lucide-react';
import { Contact, Address, ContactType } from '../types.ts';

interface ContactListProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  t: (key: any) => string;
}

const ContactList: React.FC<ContactListProps> = ({ contacts, addresses, types, onContactClick, t }) => {
  const [viewStyle, setViewStyle] = useState<'grid' | 'table'>('grid');
  const [selectedTypeId, setSelectedTypeId] = useState<string>('all');

  const processedContacts = useMemo(() => {
    let result = [...contacts];
    if (selectedTypeId !== 'all') result = result.filter(c => c.typeId === selectedTypeId);
    return result.sort((a, b) => (a.lastName || a.firstName).toLowerCase().localeCompare((b.lastName || b.firstName).toLowerCase()));
  }, [contacts, selectedTypeId]);

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString || dateString.trim() === "") return t('never');
    const lastDate = new Date(dateString);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const lastDay = new Date(lastDate.getFullYear(), lastDate.getMonth(), lastDate.getDate());
    const diffDays = Math.floor((today.getTime() - lastDay.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays === 0) return t('today');
    if (diffDays === 1) return t('yesterday');
    if (diffDays < 7) return `${diffDays} ${t('days')} ${t('ago') || 'ago'}`;
    return lastDate.toLocaleDateString();
  };

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-6 pb-24">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">{t('overview')}</h2>
            <p className="text-sm text-gray-500">{processedContacts.length} {t('peopleShown')}</p>
          </div>
          <div className="flex items-center gap-3">
            <div className="relative group">
              <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
              <select value={selectedTypeId} onChange={e => setSelectedTypeId(e.target.value)} className="pl-9 pr-8 py-2 bg-white border border-gray-200 rounded-xl text-xs font-bold text-gray-700 outline-none appearance-none focus:ring-2 focus:ring-blue-500 shadow-sm cursor-pointer">
                <option value="all">{t('allTypes')}</option>
                {types.map(t_obj => <option key={t_obj.id} value={t_obj.id}>{t(t_obj.name)}</option>)}
              </select>
              <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
            </div>
            <div className="h-8 w-px bg-gray-200" />
            <div className="flex bg-gray-100 p-1 rounded-xl">
              <button onClick={() => setViewStyle('grid')} className={`p-2 rounded-lg transition-all ${viewStyle === 'grid' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`} title={t('gridView')}>
                <Grid size={18} />
              </button>
              <button onClick={() => setViewStyle('table')} className={`p-2 rounded-lg transition-all ${viewStyle === 'table' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`} title={t('listView')}>
                <ListIcon size={18} />
              </button>
            </div>
          </div>
        </div>

        {viewStyle === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {processedContacts.map(contact => {
              const addr = addresses.find(a => a.id === contact.addressId);
              const type = types.find(t_obj => t_obj.id === contact.typeId);
              return (
                <div key={contact.id} onClick={() => onContactClick(contact.id)} className="bg-white rounded-3xl p-5 border border-gray-100 shadow-sm hover:shadow-xl hover:border-blue-200 cursor-pointer transition-all group relative">
                  {contact.isFavorite && <Heart className="absolute top-4 right-4 text-red-500 fill-current" size={16} />}
                  <div className="flex flex-col items-center text-center">
                    <img src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} className="w-24 h-24 rounded-3xl object-cover border-4 mb-4" style={{ borderColor: type?.color }} />
                    <h3 className="text-lg font-bold text-gray-900 group-hover:text-blue-600">{contact.firstName} {contact.lastName}</h3>
                    <div className="flex flex-wrap items-center gap-1.5 justify-center mb-4">
                      <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t(type?.name)}</p>
                      <span className="text-gray-300">•</span>
                      <div className="flex items-center gap-1 text-[10px] text-blue-500 font-bold bg-blue-50 px-2 py-0.5 rounded-full">
                         <Clock size={10} /> {getTimeSinceLastContact(contact.lastInteractionDate)}
                      </div>
                    </div>
                    <div className="w-full space-y-2 text-sm">
                      <div className="flex items-center gap-2 text-gray-500 bg-gray-50 p-2 rounded-xl">
                        <MapPin size={14} className="shrink-0" />
                        <span className="truncate">{addr ? `${addr.city}` : t('never')}</span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[800px]">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100">
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">{t('contacts')}</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">{t('contactType')}</th>
                  <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">{t('lastSpoken')}</th>
                </tr>
              </thead>
              <tbody>
                {processedContacts.map(contact => {
                  const type = types.find(t_obj => t_obj.id === contact.typeId);
                  return (
                    <tr key={contact.id} className="hover:bg-blue-50/30 cursor-pointer border-b border-gray-50" onClick={() => onContactClick(contact.id)}>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3 font-bold text-gray-900">{contact.firstName} {contact.lastName}</div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-wider text-white" style={{ backgroundColor: type?.color }}>{t(type?.name)}</span>
                      </td>
                      <td className="px-6 py-4 text-xs text-blue-600 font-bold">{getTimeSinceLastContact(contact.lastInteractionDate)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
        {processedContacts.length === 0 && (
          <div className="text-center py-20 bg-gray-50 rounded-[2.5rem] border border-dashed border-gray-200">
            <p className="text-gray-400 font-bold">{t('noneFound')}</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactList;

import React, { useMemo } from 'react';
import { Gift, MapPin, Users, Heart, ArrowRight, UserPlus, Calendar } from 'lucide-react';
import { Contact, Address, ContactType } from '../types.ts';

interface DashboardProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  onAddContact: () => void;
  t: (key: any) => string;
}

const Dashboard: React.FC<DashboardProps> = ({ contacts, addresses, types, onContactClick, onAddContact, t }) => {
  const upcomingBirthdays = useMemo(() => {
    const today = new Date();
    return contacts
      .filter(c => c.birthDate)
      .map(c => {
        const bday = new Date(c.birthDate!);
        const currentYearBday = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
        const nextBday = currentYearBday < today 
          ? new Date(today.getFullYear() + 1, bday.getMonth(), bday.getDate())
          : currentYearBday;
        const diff = Math.ceil((nextBday.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        const age = nextBday.getFullYear() - bday.getFullYear();
        return { ...c, daysUntil: diff, nextAge: age };
      })
      .sort((a, b) => a.daysUntil - b.daysUntil)
      .slice(0, 5);
  }, [contacts]);

  const stats = [
    { label: t('totalContacts'), value: contacts.length, icon: <Users size={24} />, color: 'bg-blue-500' },
    { label: t('uniqueAddresses'), value: addresses.length, icon: <MapPin size={24} />, color: 'bg-emerald-500' },
    { label: t('favorites'), value: contacts.filter(c => c.isFavorite).length, icon: <Heart size={24} />, color: 'bg-red-500' },
    { label: t('birthdaysThisMonth'), value: contacts.filter(c => c.birthDate && new Date(c.birthDate).getMonth() === new Date().getMonth()).length, icon: <Gift size={24} />, color: 'bg-amber-500' },
  ];

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 mb-1">{t('welcomeBack')}</h2>
          <p className="text-gray-500">{t('welcomeSubtitle')}</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, i) => (
            <div key={i} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-center gap-4 group transition-shadow">
              <div className={`p-3 rounded-2xl ${stat.color} text-white shadow-inner transition-transform group-hover:scale-110`}>{stat.icon}</div>
              <div>
                <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
                <p className="text-2xl font-black text-gray-900">{stat.value}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-12">
          <div className="lg:col-span-2 space-y-6">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2"><Gift className="text-amber-500" /> {t('upcomingBirthdays')}</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {upcomingBirthdays.length > 0 ? upcomingBirthdays.map(c => {
                const typeColor = types.find(t_obj => t_obj.id === c.typeId)?.color;
                return (
                  <div key={c.id} onClick={() => onContactClick(c.id)} className="bg-white p-4 rounded-3xl border border-gray-100 shadow-sm flex items-center gap-4 cursor-pointer hover:border-blue-200 group transition-all">
                    <img src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} className="w-16 h-16 rounded-2xl object-cover border-4" style={{ borderColor: typeColor }} />
                    <div className="flex-1 min-w-0">
                      <p className="font-bold text-gray-900 truncate group-hover:text-blue-600">{c.firstName} {c.lastName}</p>
                      <p className="text-xs text-gray-500 font-medium">{t('turning')} {c.nextAge} {t('yearsOld')}</p>
                      <span className="text-[10px] bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full font-black uppercase inline-block mt-2">
                        {t('inDays')} {c.daysUntil} {c.daysUntil === 1 ? t('day') : t('days')}
                      </span>
                    </div>
                  </div>
                );
              }) : (
                <div className="col-span-2 p-10 bg-gray-50 rounded-3xl border border-dashed border-gray-200 flex flex-col items-center text-gray-400">
                  <Calendar size={48} className="mb-2 opacity-20" />
                  <p>{t('noBirthdays')}</p>
                </div>
              )}
            </div>
          </div>
          <div className="space-y-6">
            <h3 className="text-xl font-bold text-gray-900 flex items-center gap-2"><UserPlus className="text-blue-500" /> {t('sync')}</h3>
            <div className="bg-blue-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden group">
              <div className="relative z-10">
                <h4 className="text-lg font-bold mb-2">{t('expandNetwork')}</h4>
                <p className="text-blue-100 text-sm mb-6">{t('expandSubtitle')}</p>
                <button onClick={onAddContact} className="bg-white text-blue-600 px-6 py-2.5 rounded-2xl font-bold text-sm shadow-lg hover:bg-blue-50 transition-colors active:scale-95">{t('newContact')}</button>
              </div>
            </div>
            <div className="bg-white rounded-3xl p-6 border border-gray-100 shadow-sm space-y-4">
              <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{t('recentFavorites')}</h4>
              <div className="space-y-3">
                {contacts.filter(c => c.isFavorite).slice(0, 3).map(c => (
                  <div key={c.id} className="flex items-center gap-3 cursor-pointer p-2 rounded-xl hover:bg-gray-50" onClick={() => onContactClick(c.id)}>
                    <img src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} className="w-10 h-10 rounded-full object-cover" />
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-bold text-gray-900 truncate">{c.firstName} {c.lastName}</p>
                      <p className="text-[10px] text-gray-400 font-medium">{t('lastUpdated')}: {new Date(c.updatedAt).toLocaleDateString()}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { 
  Clock, AlertTriangle, CheckCircle2, Calendar, 
  ChevronRight, ArrowRight, UserCheck, Smartphone, Phone,
  Activity
} from 'lucide-react';
import { Contact, Address, ContactType } from '../types.ts';

interface PlanningViewProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  t: (key: any) => string;
}

const PlanningView: React.FC<PlanningViewProps> = ({ contacts, addresses, types, onContactClick, t }) => {
  const planningData = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const plannedContacts = contacts
      .filter(c => c.interactionIntervalDays && c.interactionIntervalDays > 0)
      .map(c => {
        const lastDate = (c.lastInteractionDate && c.lastInteractionDate.trim() !== "") 
          ? new Date(c.lastInteractionDate) 
          : new Date(c.createdAt);
        lastDate.setHours(0, 0, 0, 0);
        const nextDate = new Date(lastDate);
        nextDate.setDate(lastDate.getDate() + (c.interactionIntervalDays || 0));
        const diffDays = Math.ceil((nextDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        let status: 'overdue' | 'soon' | 'ontrack' = 'ontrack';
        if (diffDays < 0) status = 'overdue';
        else if (diffDays <= 7) status = 'soon';
        return { ...c, nextDate, diffDays, status };
      });
    return {
      overdue: plannedContacts.filter(c => c.status === 'overdue').sort((a, b) => a.diffDays - b.diffDays),
      soon: plannedContacts.filter(c => c.status === 'soon').sort((a, b) => a.diffDays - b.diffDays),
      onTrack: plannedContacts.filter(c => c.status === 'ontrack').sort((a, b) => a.diffDays - b.diffDays),
    };
  }, [contacts]);

  return (
    <div className="h-full w-full overflow-y-auto bg-gray-50/50">
      <div className="p-8 max-w-6xl mx-auto space-y-10 pb-24">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 mb-1 flex items-center gap-3"><Activity className="text-blue-600" /> {t('planning')}</h2>
          <p className="text-gray-500">{t('planningSubtitle')}</p>
        </div>
        <section className="space-y-4">
          <h3 className="text-xs font-black text-red-500 uppercase tracking-[0.2em] flex items-center gap-2"><AlertTriangle size={14} /> {t('overdue')} ({planningData.overdue.length})</h3>
          {planningData.overdue.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {planningData.overdue.map(c => <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} t={t} />)}
            </div>
          ) : (
            <div className="p-10 bg-white rounded-[2rem] border border-dashed border-gray-200 text-center text-gray-400 text-sm">{t('noOverdue')}</div>
          )}
        </section>
        <section className="space-y-4">
          <h3 className="text-xs font-black text-amber-500 uppercase tracking-[0.2em] flex items-center gap-2"><Clock size={14} /> {t('soon')} ({planningData.soon.length})</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {planningData.soon.map(c => <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} t={t} />)}
          </div>
        </section>
        <section className="space-y-4">
          <h3 className="text-xs font-black text-emerald-500 uppercase tracking-[0.2em] flex items-center gap-2"><CheckCircle2 size={14} /> {t('onTrack')} ({planningData.onTrack.length})</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {planningData.onTrack.map(c => <PlanningCard key={c.id} contact={c} types={types} onContactClick={onContactClick} t={t} />)}
            {planningData.onTrack.length === 0 && <p className="col-span-full text-xs text-gray-400 italic">{t('noPlanned')}</p>}
          </div>
        </section>
      </div>
    </div>
  );
};

const PlanningCard = ({ contact, types, onContactClick, t }: any) => {
  const type = types.find((t_obj: any) => t_obj.id === contact.typeId);
  const isOverdue = contact.status === 'overdue';
  const isSoon = contact.status === 'soon';
  const getStatusText = () => {
    if (isOverdue) return `${t('overdue')}: ${Math.abs(contact.diffDays)} ${t('days')}`;
    if (isSoon) return contact.diffDays === 0 ? t('today') : `${t('inDays')} ${contact.diffDays} ${t('days')}`;
    return `${t('inDays')} ${contact.diffDays} ${t('days')}`;
  };
  return (
    <div onClick={() => onContactClick(contact.id)} className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm hover:border-blue-200 transition-all group cursor-pointer flex flex-col gap-4">
      <div className="flex items-center gap-4">
        <img src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}+${contact.lastName || ''}`} className="w-14 h-14 rounded-2xl object-cover border-2 shadow-sm" style={{ borderColor: type?.color }} />
        <div className="flex-1 min-w-0">
          <h4 className="font-bold text-gray-900 group-hover:text-blue-600 truncate">{contact.firstName} {contact.lastName}</h4>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{t(type?.name)}</p>
        </div>
      </div>
      <div className={`p-3 rounded-2xl border ${isOverdue ? 'bg-red-50 border-red-100' : isSoon ? 'bg-amber-50 border-amber-100' : 'bg-emerald-50 border-emerald-100'}`}>
        <span className={`text-[10px] font-black uppercase tracking-widest ${isOverdue ? 'text-red-600' : isSoon ? 'text-amber-600' : 'text-emerald-600'}`}>{getStatusText()}</span>
      </div>
    </div>
  );
};

export default PlanningView;

import React, { useState, useMemo } from 'react';
import { 
  X, Phone, Mail, MapPin, Calendar, Heart, 
  Dog, Info, Edit2, Trash2, Check,
  MessageSquare, ExternalLink, Clock, Users, Plus,
  GitPullRequest, Baby, Facebook, Instagram, Linkedin,
  CheckCircle2, Smartphone, UserCheck
} from 'lucide-react';
import { Contact, Address, ContactType, Relation, Interaction, InteractionMode } from '../types.ts';

interface ContactDetailsProps {
  contact: Contact;
  address: Address;
  type: ContactType;
  contacts: Contact[];
  relations: Relation[];
  otherResidents: Contact[];
  onClose: () => void;
  onEdit: (contact: Contact) => void;
  onUpdate: (contact: Contact) => void;
  onDelete: (id: string) => void;
  onAddResident: (addressId: string) => void;
  onSetMapAvatar: (addressId: string, contactId: string) => void;
  onContactClick: (id: string) => void;
  t: (key: any) => string;
}

const ContactDetails: React.FC<ContactDetailsProps> = ({ 
  contact, address, type, contacts, relations, otherResidents, onClose, onEdit, onUpdate, onDelete, onAddResident, onSetMapAvatar, onContactClick, t
}) => {
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [showInteractionModal, setShowInteractionModal] = useState(false);
  const [editingInteractionId, setEditingInteractionId] = useState<string | null>(null);
  const [newInteractionType, setNewInteractionType] = useState<InteractionMode>('physical');
  const [newInteractionNotes, setNewInteractionNotes] = useState('');
  const [newInteractionDate, setNewInteractionDate] = useState<string>(new Date().toISOString().split('T')[0]);

  const allResidents = [...otherResidents, contact].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  const contactRelations = useMemo(() => {
    return relations
      .filter(r => r.contactAId === contact.id || r.contactBId === contact.id)
      .map(r => {
        const otherId = r.contactAId === contact.id ? r.contactBId : r.contactAId;
        const otherContact = contacts.find(c => c.id === otherId);
        return { relation: r, contact: otherContact, displayType: r.type };
      })
      .filter(item => item.contact);
  }, [contact.id, relations, contacts]);

  const displayInteractions = useMemo(() => {
    let list = [...(contact.interactions || [])];
    const lastInteractionStr = contact.lastInteractionDate;
    if (lastInteractionStr && lastInteractionStr.trim() !== "") {
      const lastDateStr = new Date(lastInteractionStr).toLocaleDateString();
      if (!list.some(i => new Date(i.date).toLocaleDateString() === lastDateStr)) {
        list.push({ id: 'virtual-last', type: 'interaction', date: lastInteractionStr, notes: t('nu_vastleggen') });
      }
    }
    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [contact.interactions, contact.lastInteractionDate, t]);

  const getTimeSinceLastContact = (dateString?: string) => {
    if (!dateString || dateString.trim() === "") return t('never');
    const lastDate = new Date(dateString);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const diffDays = Math.floor((today.getTime() - new Date(lastDate.getFullYear(), lastDate.getMonth(), lastDate.getDate()).getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays === 0) return t('today');
    if (diffDays === 1) return t('yesterday');
    if (diffDays < 7) return `${diffDays} ${t('daysAgo')}`;
    return lastDate.toLocaleDateString();
  };

  const handleSaveInteraction = () => {
    const selectedDateTime = new Date(newInteractionDate);
    const isoDate = selectedDateTime.toISOString();
    let updatedInteractions = [...(contact.interactions || [])];
    if (editingInteractionId) {
      updatedInteractions = updatedInteractions.map(i => i.id === editingInteractionId ? { ...i, type: newInteractionType, date: isoDate, notes: newInteractionNotes } : i);
    } else {
      updatedInteractions = [{ id: `int-${Date.now()}`, type: newInteractionType, date: isoDate, notes: newInteractionNotes || t('nu_vastleggen') }, ...updatedInteractions];
    }
    const latestInteractionDate = updatedInteractions.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0]?.date || '';
    onUpdate({ ...contact, lastInteractionDate: latestInteractionDate, interactions: updatedInteractions, updatedAt: new Date().toISOString() });
    setShowInteractionModal(false);
  };

  const getInteractionIcon = (type_in: InteractionMode) => {
    switch(type_in) {
      case 'physical': return <Users size={14} />;
      case 'app': return <Smartphone size={14} />;
      case 'phone': return <Phone size={14} />;
      default: return <Clock size={14} />;
    }
  };

  return (
    <div className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[100] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
      <div className="relative shrink-0">
        <div className="h-32 w-full relative bg-gray-100">
          <img src={`https://picsum.photos/seed/${contact.addressId}/600/300`} className="w-full h-full object-cover brightness-75" />
          <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/20 text-white rounded-full"><X size={20} /></button>
          <div className="absolute top-4 right-4 flex gap-2">
            {!isConfirmingDelete ? (
              <>
                <button onClick={() => onEdit(contact)} className="p-2 bg-white/20 text-white rounded-full"><Edit2 size={18} /></button>
                <button onClick={() => setIsConfirmingDelete(true)} className="p-2 bg-red-500/80 text-white rounded-full"><Trash2 size={18} /></button>
              </>
            ) : (
              <div className="flex items-center bg-red-600 rounded-full p-1 pr-3 gap-2">
                <button onClick={() => onDelete(contact.id)} className="bg-white text-red-600 p-1.5 rounded-full"><Check size={16} /></button>
                <button onClick={() => setIsConfirmingDelete(false)} className="text-white"><X size={16} /></button>
                <span className="text-[10px] text-white font-black uppercase">{t('wissen')}</span>
              </div>
            )}
          </div>
        </div>
        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <img src={contact.photoUrl || `https://ui-avatars.com/api/?name=${contact.firstName}`} className="w-24 h-24 rounded-full border-4 bg-white" style={{ borderColor: type.color }} />
          {contact.isFavorite && <Heart className="p-2 bg-red-50 text-red-500 rounded-full fill-current" size={40} />}
        </div>
        <div className="px-6 mt-4">
          <h2 className="text-2xl font-bold text-gray-900">{contact.firstName} {contact.lastName}</h2>
          <span className="inline-block mt-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full text-white" style={{ backgroundColor: type.color }}>{t(type.name)}</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8">
        <div className="bg-blue-50/50 p-4 rounded-2xl border border-blue-100 flex items-center justify-between">
          <div>
            <p className="text-[10px] font-black text-blue-400 uppercase mb-1">{t('lastSpoken')}</p>
            <p className="text-sm font-bold text-blue-900">{getTimeSinceLastContact(contact.lastInteractionDate)}</p>
          </div>
          <button onClick={() => setShowInteractionModal(true)} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-xs font-bold">{t('recordNow')}</button>
        </div>

        <div className="space-y-4">
          <DetailItem icon={<Phone size={18} />} label={t('phone')} value={contact.phones[0] || t('never')} />
          <DetailItem icon={<Mail size={18} />} label={t('email')} value={contact.emails[0] || t('never')} />
          <DetailItem icon={<MapPin size={18} />} label={t('address')} value={`${address.street} ${address.houseNumber}`} />
          <DetailItem icon={<Calendar size={18} />} label={t('birthday')} value={contact.birthDate || t('notSet')} />
        </div>

        {contact.children.length > 0 && (
          <div>
            <h3 className="text-sm font-bold text-gray-400 uppercase mb-4">{t('children')}</h3>
            {contact.children.map((c, i) => <div key={i} className="text-sm font-bold p-2 bg-pink-50 rounded-xl mb-1">{c.name}</div>)}
          </div>
        )}

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase mb-4">{t('relations')}</h3>
          {contactRelations.map(item => (
            <div key={item.relation.id} onClick={() => onContactClick(item.contact!.id)} className="flex items-center gap-3 p-2 bg-gray-50 rounded-xl mb-1 cursor-pointer">
              <img src={item.contact?.photoUrl || `https://ui-avatars.com/api/?name=${item.contact?.firstName}`} className="w-8 h-8 rounded-full" />
              <div className="min-w-0 flex-1"><p className="text-xs font-bold">{item.contact?.firstName}</p><p className="text-[9px] text-gray-400 uppercase">{t(item.displayType)}</p></div>
            </div>
          ))}
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase mb-4">{t('residentsAtAddress')}</h3>
          {allResidents.map(res => (
            <div key={res.id} className="flex items-center justify-between p-2 bg-gray-50 rounded-xl mb-1 text-xs">
              <span className="font-bold">{res.firstName} {res.id === contact.id && t('ditContact')}</span>
              <button onClick={() => onSetMapAvatar(address.id, res.id)} className={`p-1 rounded ${address.mapAvatarId === res.id ? 'bg-blue-600 text-white' : 'text-gray-400'}`}><MapPin size={14}/></button>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="bg-blue-50 p-4 rounded-xl">
            <h4 className="text-xs font-bold text-blue-400 uppercase mb-2">{t('pets')}</h4>
            <div className="text-xs">{contact.pets.length > 0 ? contact.pets.map(p => p.name).join(', ') : t('never')}</div>
          </div>
          <div className="bg-purple-50 p-4 rounded-xl">
            <h4 className="text-xs font-bold text-purple-400 uppercase mb-2">{t('hobbies')}</h4>
            <div className="text-xs">{contact.hobbies.length > 0 ? contact.hobbies.join(', ') : t('never')}</div>
          </div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase mb-2">{t('notes')}</h3>
          <div className="bg-yellow-50 p-4 rounded-xl italic text-sm">{contact.notes || t('noInteractions')}</div>
        </div>

        <div>
          <h3 className="text-sm font-bold text-gray-400 uppercase mb-4">{t('history')}</h3>
          {displayInteractions.map(log => (
            <div key={log.id} className="pl-6 border-l mb-4 relative">
              <div className="absolute -left-2 top-1 bg-white border rounded-full p-0.5">{getInteractionIcon(log.type)}</div>
              <p className="text-[10px] text-gray-400 font-bold uppercase">{new Date(log.date).toLocaleDateString()}</p>
              <p className="text-sm">{log.notes}</p>
            </div>
          ))}
        </div>
      </div>

      {showInteractionModal && (
        <div className="absolute inset-0 bg-gray-900/40 z-[250] flex items-center justify-center p-4">
          <div className="bg-white p-6 rounded-3xl w-full max-w-xs shadow-2xl space-y-4">
            <h4 className="text-lg font-bold">{t('interactionTitle')}</h4>
            <input type="date" value={newInteractionDate} onChange={e => setNewInteractionDate(e.target.value)} className="w-full p-2 bg-gray-50 border rounded-xl" />
            <div className="grid grid-cols-3 gap-2">
              <button onClick={() => setNewInteractionType('physical')} className={`p-2 rounded-xl border text-[10px] font-bold ${newInteractionType === 'physical' ? 'bg-blue-600 text-white' : 'bg-gray-50'}`}>{t('physical')}</button>
              <button onClick={() => setNewInteractionType('app')} className={`p-2 rounded-xl border text-[10px] font-bold ${newInteractionType === 'app' ? 'bg-blue-600 text-white' : 'bg-gray-50'}`}>{t('app')}</button>
              <button onClick={() => setNewInteractionType('phone')} className={`p-2 rounded-xl border text-[10px] font-bold ${newInteractionType === 'phone' ? 'bg-blue-600 text-white' : 'bg-gray-50'}`}>{t('call')}</button>
            </div>
            <textarea value={newInteractionNotes} onChange={e => setNewInteractionNotes(e.target.value)} className="w-full p-2 bg-gray-50 border rounded-xl text-sm" placeholder={t('recordNow')} />
            <div className="flex flex-col gap-2">
              <button onClick={handleSaveInteraction} className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold">{t('save')}</button>
              <button onClick={() => setShowInteractionModal(false)} className="w-full text-gray-400 font-bold text-sm">{t('cancel')}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const DetailItem = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-3">
    <div className="p-2 bg-gray-50 rounded-xl text-gray-400">{icon}</div>
    <div><p className="text-[10px] font-bold text-gray-400 uppercase">{label}</p><p className="text-sm font-semibold text-gray-800">{value}</p></div>
  </div>
);

