import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  X, Save, Camera, Plus, Trash, RefreshCw, 
  ImageIcon, Upload, Loader2, Heart, 
  MapPin, Users, Search, Phone, Mail, Calendar, 
  Dog, Info, GitPullRequest, Trash2, Baby,
  Facebook, Instagram, Linkedin, Clock, Smartphone, UserCheck, MessageSquare, Activity
} from 'lucide-react';
import { Contact, Address, ContactType, Pet, Relation, RelationType, ContactChild, SocialLinks, InteractionMode, Interaction } from '../types.ts';
import { compressImageBase64 } from '../utils.ts';

interface ContactFormProps {
  contact: Contact | null;
  types: ContactType[];
  addresses: Address[];
  contacts: Contact[];
  relations: Relation[];
  initialCoords: [number, number] | null;
  initialAddressId: string | null;
  onClose: () => void;
  onSave: (contact: Contact, address: Address, relations: Relation[]) => void;
  t: (key: any) => string;
}

const ContactForm: React.FC<ContactFormProps> = ({ 
  contact, types, addresses, contacts, relations, initialCoords, initialAddressId, onClose, onSave, t 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [hobbyInput, setHobbyInput] = useState('');
  const [addressSearch, setAddressSearch] = useState('');
  const [relationSearch, setRelationSearch] = useState('');
  const [isChoosingExisting, setIsChoosingExisting] = useState(false);
  const [lastInteractionType, setLastInteractionType] = useState<InteractionMode>('physical');
  const [lastInteractionNotes, setLastInteractionNotes] = useState('');

  const [formData, setFormData] = useState<Partial<Contact>>(() => {
    return contact || {
      firstName: '', lastName: '', phones: [''], emails: [''], typeId: types[0].id,
      notes: '', isFavorite: false, pets: [], children: [], socialLinks: {},
      hobbies: [], photoUrl: '', lastInteractionDate: '', interactions: [], interactionIntervalDays: 0
    };
  });

  const [addrData, setAddrData] = useState<Partial<Address>>(() => {
    if (contact?.addressId) return addresses.find(a => a.id === contact.addressId) || {};
    if (initialAddressId) return addresses.find(a => a.id === initialAddressId) || {};
    return { street: '', houseNumber: '', postalCode: '', city: '', lat: initialCoords?.[0] || 52.37, lng: initialCoords?.[1] || 4.89, country: 'NL' };
  });

  const [localRelations, setLocalRelations] = useState<Relation[]>(() => {
    if (!contact) return [];
    return relations.filter(r => r.contactAId === contact.id || r.contactBId === contact.id);
  });

  const filteredAddresses = useMemo(() => {
    if (!addressSearch) return addresses;
    return addresses.filter(a => a.street.toLowerCase().includes(addressSearch.toLowerCase()) || a.city.toLowerCase().includes(addressSearch.toLowerCase()));
  }, [addresses, addressSearch]);

  const filteredContactsForRelation = useMemo(() => {
    if (!relationSearch) return [];
    const q = relationSearch.toLowerCase();
    return contacts.filter(c => c.id !== contact?.id && !localRelations.some(r => r.contactAId === c.id || r.contactBId === c.id) && (c.firstName.toLowerCase().includes(q) || (c.lastName || '').toLowerCase().includes(q))).slice(0, 5);
  }, [contacts, relationSearch, localRelations, contact?.id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const addressId = addrData.id || `addr-${Date.now()}`;
    const contactId = contact?.id || `c-${Date.now()}`;

    let updatedInteractions = [...(formData.interactions || [])];
    if (lastInteractionNotes.trim() !== "") {
      updatedInteractions.push({ id: `int-form-${Date.now()}`, type: lastInteractionType, date: formData.lastInteractionDate || new Date().toISOString(), notes: lastInteractionNotes });
    }

    onSave({ ...formData as Contact, id: contactId, addressId, updatedAt: new Date().toISOString(), interactions: updatedInteractions }, { ...addrData as Address, id: addressId }, localRelations);
    setIsSaving(false);
  };

  const selectedType = types.find(t_obj => t_obj.id === formData.typeId) || types[0];

  return (
    <div className="absolute top-0 right-0 w-full sm:w-96 h-full bg-white shadow-2xl z-[150] border-l border-gray-200 flex flex-col animate-in slide-in-from-right duration-300">
      <div className="relative shrink-0">
        <div className="h-32 w-full bg-gray-100">
           <img src={`https://picsum.photos/seed/${addrData.id || 'new'}/600/300`} className="w-full h-full object-cover" />
           <button onClick={onClose} className="absolute top-4 left-4 p-2 bg-white/20 text-white rounded-full"><X size={20}/></button>
        </div>
        <div className="px-6 -mt-10 relative z-10 flex items-end justify-between">
          <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
            <img src={formData.photoUrl || `https://ui-avatars.com/api/?name=${formData.firstName || '?'}`} className="w-24 h-24 rounded-full border-4 bg-white" style={{ borderColor: selectedType.color }} />
            <input type="file" ref={fileInputRef} onChange={async e => { const file = e.target.files?.[0]; if (file) { const reader = new FileReader(); reader.onloadend = async () => setFormData({...formData, photoUrl: await compressImageBase64(reader.result as string)}); reader.readAsDataURL(file); } }} className="hidden" />
          </div>
          <button onClick={() => setFormData({...formData, isFavorite: !formData.isFavorite})} className={`p-2 rounded-full border shadow-sm ${formData.isFavorite ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-gray-300'}`}><Heart className={formData.isFavorite ? 'fill-current' : ''} /></button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        <FormInput label={t('firstName')} value={formData.firstName} onChange={v => setFormData({...formData, firstName: v})} placeholder="Jan" />
        <FormInput label={t('lastName')} value={formData.lastName} onChange={v => setFormData({...formData, lastName: v})} placeholder="Jansen" />
        <FormInput label={t('birthDate')} type="date" value={formData.birthDate} onChange={v => setFormData({...formData, birthDate: v})} />

        <div className="pt-4 border-t space-y-4">
          <h3 className="text-[10px] font-black uppercase text-blue-500">{t('planningInteraction')}</h3>
          <FormInput label={t('lastDate')} type="date" value={formData.lastInteractionDate?.split('T')[0]} onChange={v => setFormData({...formData, lastInteractionDate: v ? new Date(v).toISOString() : ''})} />
          <textarea className="w-full p-3 bg-gray-50 border rounded-xl text-xs outline-none" placeholder={t('recordNow')} value={lastInteractionNotes} onChange={e => setLastInteractionNotes(e.target.value)} />
        </div>

        <div className="pt-4 border-t space-y-4">
          <div className="flex justify-between items-center"><h3 className="text-[10px] font-black uppercase text-gray-400">{t('location')}</h3><button onClick={() => setIsChoosingExisting(!isChoosingExisting)} className="text-[10px] font-bold text-blue-600">{isChoosingExisting ? t('manualEntry') : t('searchExisting')}</button></div>
          {isChoosingExisting ? (
             <div className="space-y-2"><input className="w-full p-2 bg-gray-50 border rounded-xl text-xs" placeholder={t('search')} value={addressSearch} onChange={e => setAddressSearch(e.target.value)} />{filteredAddresses.map(a => <button key={a.id} onClick={() => { setAddrData(a); setIsChoosingExisting(false); }} className="w-full text-left p-2 bg-white border rounded-lg text-[10px] font-bold">{a.street} {a.houseNumber}, {a.city}</button>)}</div>
          ) : (
             <div className="grid grid-cols-3 gap-2"><div className="col-span-2"><FormInput label="Straat" value={addrData.street} onChange={v => setAddrData({...addrData, street: v})} /></div><div><FormInput label="Nr" value={addrData.houseNumber} onChange={v => setAddrData({...addrData, houseNumber: v})} /></div></div>
          )}
        </div>

        <div className="pt-4 border-t space-y-2">
           <div className="flex justify-between items-center text-[10px] font-black uppercase text-gray-400"><span>{t('hobbies')}</span></div>
           <input className="w-full p-2 bg-gray-50 border rounded-xl text-xs" placeholder={t('newHobby')} onKeyDown={e => { if (e.key === 'Enter') { setFormData({...formData, hobbies: [...(formData.hobbies || []), e.currentTarget.value]}); e.currentTarget.value = ''; } }} />
        </div>
      </div>

      <div className="p-6 border-t bg-white flex justify-end gap-3 sticky bottom-0">
        <button onClick={onClose} className="px-6 py-2 text-sm font-bold text-gray-400">{t('cancel')}</button>
        <button onClick={handleSubmit} className="px-8 py-2 bg-blue-600 text-white rounded-full font-bold text-sm shadow-lg disabled:opacity-50" disabled={isSaving || !formData.firstName}>{isSaving ? t('processing') : t('save')}</button>
      </div>
    </div>
  );
};

