import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Contact, ContactType, Address } from '../types.ts';

interface StatsViewProps {
  contacts: Contact[];
  types: ContactType[];
  addresses: Address[];
  t: (key: any) => string;
}

const StatsView: React.FC<StatsViewProps> = ({ contacts, types, addresses, t }) => {
  const typeData = types.map(t_obj => ({
    name: t(t_obj.name),
    value: contacts.filter(c => c.typeId === t_obj.id).length,
    color: t_obj.color
  })).filter(d => d.value > 0).sort((a, b) => b.value - a.value);

  const cityCounts = contacts.reduce((acc: any, c) => {
    const addr = addresses.find(a => a.id === c.addressId);
    const city = addr?.city || t('Onbekend');
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});

  const cityData = Object.entries(cityCounts).map(([city, count]) => ({ city, count: count as number })).sort((a, b) => b.count - a.count).slice(0, 5);

  return (
    <div className="h-full w-full overflow-y-auto">
      <div className="p-8 max-w-7xl mx-auto space-y-10 pb-24">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
            <h3 className="text-xl font-bold text-gray-900 mb-6">{t('contactType')}</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={typeData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={5} dataKey="value">
                    {typeData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                  </Pie>
                  <Tooltip contentStyle={{ borderRadius: '1rem', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                  <Legend verticalAlign="bottom" height={36}/>
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Top Locaties</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={cityData}>
                  <XAxis dataKey="city" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
                  <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '1rem', border: 'none' }} />
                  <Bar dataKey="count" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StatsView;

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight, Gift } from 'lucide-react';
import { Contact, ContactType } from '../types.ts';

interface CalendarViewProps {
  contacts: Contact[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  language: 'nl' | 'en';
}

const CalendarView: React.FC<CalendarViewProps> = ({ contacts, types, onContactClick, language }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const translations = {
    nl: {
      months: ['Januari', 'Februari', 'Maart', 'April', 'Mei', 'Juni', 'Juli', 'Augustus', 'September', 'Oktober', 'November', 'December'],
      days: ['Ma', 'Di', 'Wo', 'Do', 'Vr', 'Za', 'Zo'],
      today: 'Vandaag',
      subtitle: 'Plan je sociale uitjes en verjaardagskaarten.'
    },
    en: {
      months: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
      days: ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'],
      today: 'Today',
      subtitle: 'Plan your social outings and birthday cards.'
    }
  };

  const t_cal = translations[language];
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const days = [];
  const totalDays = daysInMonth(year, month);
  const startOffset = (firstDayOfMonth(year, month) + 6) % 7; 

  for (let i = 0; i < startOffset; i++) days.push(null);
  for (let d = 1; d <= totalDays; d++) days.push(d);

  return (
    <div className="p-8 max-w-5xl mx-auto space-y-6 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <div><h2 className="text-3xl font-bold text-gray-900">{t_cal.months[month]} {year}</h2><p className="text-gray-500">{t_cal.subtitle}</p></div>
        <div className="flex gap-2">
          <button onClick={() => setCurrentDate(new Date(year, month - 1, 1))} className="p-2 border rounded-full"><ChevronRight className="rotate-180" size={20}/></button>
          <button onClick={() => setCurrentDate(new Date())} className="px-4 py-2 border rounded-xl font-bold text-sm">{t_cal.today}</button>
          <button onClick={() => setCurrentDate(new Date(year, month + 1, 1))} className="p-2 border rounded-full"><ChevronRight size={20}/></button>
        </div>
      </div>
      <div className="flex-1 bg-white rounded-3xl border border-gray-100 shadow-xl overflow-hidden flex flex-col">
        <div className="grid grid-cols-7 bg-gray-50 border-b">
          {t_cal.days.map(day => <div key={day} className="py-4 text-center text-xs font-black text-gray-400 uppercase tracking-widest">{day}</div>)}
        </div>
        <div className="flex-1 grid grid-cols-7 grid-rows-5 overflow-auto">
          {days.map((day, idx) => {
            const birthdayContacts = day ? contacts.filter(c => c.birthDate && new Date(c.birthDate).getDate() === day && new Date(c.birthDate).getMonth() === month) : [];
            return (
              <div key={idx} className={`min-h-[120px] p-2 border-r border-b border-gray-50 flex flex-col gap-1 transition-colors ${day ? 'hover:bg-blue-50/20' : 'bg-gray-50/30'}`}>
                {day && <><span className={`text-sm font-bold ${day === new Date().getDate() && month === new Date().getMonth() ? 'bg-blue-600 text-white w-7 h-7 flex items-center justify-center rounded-full' : 'text-gray-400'}`}>{day}</span>
                <div className="space-y-1">{birthdayContacts.map(c => <div key={c.id} onClick={() => onContactClick(c.id)} className="flex items-center gap-1.5 p-1.5 bg-amber-50 rounded-lg cursor-pointer hover:bg-amber-100 border border-amber-100"><span className="text-[10px] font-bold text-amber-800 truncate">{c.firstName}</span></div>)}</div></>}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Map as MapIcon, 
  Users, 
  LayoutDashboard, 
  Calendar, 
  BarChart3, 
  Plus, 
  Search, 
  Filter,
  LogOut,
  Bell,
  Settings,
  ChevronRight,
  ChevronLeft,
  Download,
  Upload,
  AlertTriangle,
  CheckCircle2,
  X,
  FileJson,
  Loader2,
  ShieldAlert,
  ExternalLink,
  Clock,
  Activity,
  Globe
} from 'lucide-react';
import { 
  auth, 
  db, 
  onAuthStateChanged, 
  signOut, 
  collection, 
  doc, 
  getDocs, 
  setDoc, 
  deleteDoc, 
  writeBatch 
} from "./firebase.ts";
import { Contact, Address, ContactType, ViewMode, Relation } from './types.ts';
import { DEFAULT_TYPES, INITIAL_CONTACTS, INITIAL_ADDRESSES } from './constants.tsx';
import { translations } from './translations.ts';
import MapView from './components/MapView.tsx';
import ContactList from './components/ContactList.tsx';
import Dashboard from './components/Dashboard.tsx';
import StatsView from './components/StatsView.tsx';
import ContactForm from './components/ContactForm.tsx';
import ContactDetails from './components/ContactDetails.tsx';
import CalendarView from './components/CalendarView.tsx';
import AuthScreen from './components/AuthScreen.tsx';
import PlanningView from './components/PlanningView.tsx';
import { compressImageBase64 } from './utils.ts';

const App: React.FC = () => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [isDataSyncing, setIsDataSyncing] = useState(false);
  const [hasPermissionError, setHasPermissionError] = useState(false);
  const [language, setLanguage] = useState<'nl' | 'en'>('nl');

  const [contacts, setContacts] = useState<Contact[]>([]);
  const [addresses, setAddresses] = useState<Address[]>([]);
  const [types, setTypes] = useState<ContactType[]>(DEFAULT_TYPES);
  const [relations, setRelations] = useState<Relation[]>([]);

  const [viewMode, setViewMode] = useState<ViewMode>('map');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editContact, setEditContact] = useState<Contact | null>(null);
  const [initialCoords, setInitialCoords] = useState<[number, number] | null>(null);
  const [initialAddressId, setInitialAddressId] = useState<string | null>(null);

  // Translation helper
  const t = (key: keyof typeof translations['nl']) => translations[language][key] || key;

  // Import states
  const [importPendingData, setImportPendingData] = useState<any>(null);
  const [showImportModal, setShowImportModal] = useState(false);
  const [importSuccess, setImportSuccess] = useState(false);
  const [importError, setImportError] = useState<string | null>(null);

  // Authentication observer
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user: any) => {
      setCurrentUser(user);
      setIsAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch data from Firestore when user logs in
  useEffect(() => {
    if (!currentUser) {
      setContacts([]);
      setAddresses([]);
      setRelations([]);
      setTypes(DEFAULT_TYPES);
      setHasPermissionError(false);
      return;
    }

    const fetchData = async () => {
      setIsDataSyncing(true);
      setHasPermissionError(false);
      try {
        const userRef = doc(db, 'users', currentUser.uid);
        const contactsSnap = await getDocs(collection(userRef, 'contacts'));
        const addressesSnap = await getDocs(collection(userRef, 'addresses'));
        const relationsSnap = await getDocs(collection(userRef, 'relations'));
        const typesSnap = await getDocs(collection(userRef, 'types'));

        const loadedContacts = contactsSnap.docs
          .map(d => d.data() as Contact)
          .filter(c => c && c.firstName);

        const loadedAddresses = addressesSnap.docs
          .map(d => d.data() as Address)
          .filter(a => a && a.street);

        const loadedRelations = relationsSnap.docs
          .map(d => d.data() as Relation)
          .filter(r => r && r.contactAId && r.contactBId);

        const loadedTypes = typesSnap.docs
          .map(d => d.data() as ContactType)
          .filter(t => t && t.name);

        setContacts(loadedContacts);
        setAddresses(loadedAddresses);
        setRelations(loadedRelations);

        const mergedTypes = [...DEFAULT_TYPES];
        loadedTypes.forEach(lt => {
          const idx = mergedTypes.findIndex(mt => mt.id === lt.id);
          if (idx > -1) {
            mergedTypes[idx] = lt;
          } else {
            mergedTypes.push(lt);
          }
        });
        setTypes(mergedTypes);

      } catch (err: any) {
        console.error("Error fetching Firestore data:", err);
        if (err.code === 'permission-denied') {
          setHasPermissionError(true);
        }
      } finally {
        setIsDataSyncing(false);
      }
    };

    fetchData();
  }, [currentUser]);

  const filteredContacts = useMemo(() => {
    const q = searchQuery.toLowerCase();
    return contacts.filter(c => {
      if (!c || typeof c.firstName !== 'string') return false;
      const addr = addresses.find(a => a.id === c.addressId);
      return (
        c.firstName.toLowerCase().includes(q) ||
        (c.lastName || '').toLowerCase().includes(q) ||
        (addr?.city || '').toLowerCase().includes(q) ||
        (addr?.street || '').toLowerCase().includes(q)
      );
    });
  }, [contacts, addresses, searchQuery]);

  const selectedContact = useMemo(() => 
    selectedContactId ? contacts.find(c => c.id === selectedContactId) : null
  , [selectedContactId, contacts]);

  const selectedAddress = useMemo(() => 
    selectedContact ? addresses.find(a => a.id === selectedContact.addressId) : null
  , [selectedContact, addresses]);

  const selectedType = useMemo(() => 
    selectedContact ? types.find(t => t.id === selectedContact.typeId) : null
  , [selectedContact, types]);

  const otherResidents = useMemo(() => 
    selectedContact ? contacts.filter(c => c.addressId === selectedContact.addressId && c.id !== selectedContact.id) : []
  , [selectedContact, contacts]);

  const handleAddContact = (coords?: [number, number], addressId?: string) => {
    setInitialCoords(coords || null);
    setInitialAddressId(addressId || null);
    setEditContact(null);
    setIsFormOpen(true);
  };

  const handleEditContact = (contact: Contact) => {
    setEditContact(contact);
    setInitialAddressId(null);
    setInitialCoords(null);
    setIsFormOpen(true);
  };

  const handleUpdateContact = async (updatedContact: Contact) => {
    if (!currentUser) return;
    setContacts(prev => prev.map(c => c.id === updatedContact.id ? updatedContact : c));
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      await setDoc(doc(userRef, 'contacts', updatedContact.id), updatedContact);
    } catch (err) {
      console.error("Firestore update failed", err);
    }
  };

  const handleDeleteContact = async (id: string) => {
    if (!currentUser) return;
    setSelectedContactId(null);
    setContacts(prev => prev.filter(c => c.id !== id));
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      await deleteDoc(doc(userRef, 'contacts', id));
      const relationsToDelete = relations.filter(r => r.contactAId === id || r.contactBId === id);
      for (const rel of relationsToDelete) {
        await deleteDoc(doc(userRef, 'relations', rel.id));
      }
    } catch (err) {
      console.error("Delete from Firestore failed", err);
    }
  };

  const handleSetMapAvatar = async (addressId: string, contactId: string) => {
    if (!currentUser) return;
    setAddresses(prev => prev.map(a => 
      a.id === addressId ? { ...a, mapAvatarId: contactId } : a
    ));
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      const addr = addresses.find(a => a.id === addressId);
      if (addr) {
        await setDoc(doc(userRef, 'addresses', addressId), { ...addr, mapAvatarId: contactId });
      }
    } catch (err) {
      console.error("Avatar update failed", err);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Logout failed", error);
    }
  };

  const saveContact = async (contact: Contact, address: Address, contactRelations: Relation[]) => {
    if (!currentUser) return;
    setAddresses(prev => {
      const exists = prev.find(a => a.id === address.id);
      return exists ? prev.map(a => a.id === address.id ? address : a) : [...prev, address];
    });
    setContacts(prev => {
      const exists = prev.find(c => c.id === contact.id);
      return exists ? prev.map(c => c.id === contact.id ? contact : c) : [...prev, contact];
    });
    setRelations(prev => {
      const otherRelations = prev.filter(r => r.contactAId !== contact.id && r.contactBId !== contact.id);
      return [...otherRelations, ...contactRelations];
    });
    try {
      const userRef = doc(db, 'users', currentUser.uid);
      const batch = writeBatch(db);
      batch.set(doc(userRef, 'addresses', address.id), address);
      batch.set(doc(userRef, 'contacts', contact.id), contact);
      for (const rel of contactRelations) {
        batch.set(doc(userRef, 'relations', rel.id), rel);
      }
      await batch.commit();
    } catch (err) {
      console.error("Firestore save failed", err);
    }
    setIsFormOpen(false);
  };

  const handleExportData = () => {
    const data = { contacts, addresses, types, relations, version: '2.2', exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mapcrm_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const data = JSON.parse(text);
        if (data && typeof data === 'object' && Array.isArray(data.contacts) && Array.isArray(data.addresses)) {
          setImportPendingData(data);
          setShowImportModal(true);
          setImportError(null);
        } else {
          setImportError('Ongeldige bestandsstructuur.');
        }
      } catch (err) {
        setImportError('Kan bestand niet lezen.');
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const executeImport = async () => {
    if (!importPendingData || !currentUser) return;
    setIsDataSyncing(true);
    try {
      const data = importPendingData;
      const userRef = doc(db, 'users', currentUser.uid);
      const batch = writeBatch(db);
      const sanitizedContacts = await Promise.all(data.contacts
        .filter((c: any) => c && c.firstName)
        .map(async (c: any) => {
          let photoUrl = c.photoUrl;
          if (photoUrl && photoUrl.startsWith('data:image')) {
            photoUrl = await compressImageBase64(photoUrl);
          }
          return {
            ...c,
            photoUrl,
            phones: Array.isArray(c.phones) ? c.phones : (c.phone ? [c.phone] : []),
            emails: Array.isArray(c.emails) ? c.emails : (c.email ? [c.email] : []),
            pets: Array.isArray(c.pets) ? c.pets : [],
            children: Array.isArray(c.children) ? c.children : [],
            socialLinks: c.socialLinks || {},
            hobbies: Array.isArray(c.hobbies) ? c.hobbies : [],
            interactions: Array.isArray(c.interactions) ? c.interactions : [],
            isFavorite: !!c.isFavorite,
            createdAt: c.createdAt || new Date().toISOString(),
            updatedAt: c.updatedAt || new Date().toISOString(),
          };
        })
      );
      for (const c of sanitizedContacts) batch.set(doc(userRef, 'contacts', c.id), c);
      for (const a of data.addresses) batch.set(doc(userRef, 'addresses', a.id), a);
      if (data.types) for (const t of data.types) batch.set(doc(userRef, 'types', t.id), t);
      if (data.relations) for (const r of data.relations) batch.set(doc(userRef, 'relations', r.id), r);
      await batch.commit();
      setContacts(sanitizedContacts);
      setAddresses(data.addresses);
      const mergedTypes = [...DEFAULT_TYPES];
      if (data.types) {
        data.types.forEach((lt: ContactType) => {
          const idx = mergedTypes.findIndex(mt => mt.id === lt.id);
          if (idx > -1) mergedTypes[idx] = lt;
          else mergedTypes.push(lt);
        });
      }
      setTypes(mergedTypes);
      if (data.relations) setRelations(data.relations);
      setSelectedContactId(null);
      setImportPendingData(null);
      setShowImportModal(false);
      setImportSuccess(true);
      setTimeout(() => setImportSuccess(false), 3000);
    } catch (err) {
      setImportError('Fout tijdens synchronisatie.');
    } finally {
      setIsDataSyncing(false);
    }
  };

  if (isAuthLoading) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-blue-50">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-200 animate-pulse">
            <Users size={28} />
          </div>
          <p className="text-blue-900 font-bold tracking-tight">{t('authenticating')}</p>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <AuthScreen language={language} onLanguageChange={setLanguage} />;
  }

  return (
    <div className="flex h-screen w-full bg-gray-50 text-gray-900 overflow-hidden">
      <aside 
        className={`${
          isSidebarOpen ? 'w-64' : 'w-20'
        } bg-white border-r border-gray-200 transition-all duration-300 flex flex-col z-50 shadow-sm`}
      >
        <div className="p-4 flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shrink-0 shadow-lg">
            <Users size={24} />
          </div>
          {isSidebarOpen && <h1 className="text-xl font-bold tracking-tight text-blue-900">MapCRM</h1>}
        </div>

        <nav className="flex-1 mt-6 px-2 space-y-1 overflow-y-auto">
          <NavItem 
            icon={<MapIcon size={20} />} 
            label={t('map')} 
            active={viewMode === 'map'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('map')} 
          />
          <NavItem 
            icon={<Users size={20} />} 
            label={t('contacts')} 
            active={viewMode === 'list'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('list')} 
          />
          <NavItem 
            icon={<LayoutDashboard size={20} />} 
            label={t('dashboard')} 
            active={viewMode === 'dashboard'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('dashboard')} 
          />
          <NavItem 
            icon={<Activity size={20} />} 
            label={t('planning')} 
            active={viewMode === 'planning'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('planning')} 
          />
          <NavItem 
            icon={<Calendar size={20} />} 
            label={t('birthdays')} 
            active={viewMode === 'calendar'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('calendar')} 
          />
          <NavItem 
            icon={<BarChart3 size={20} />} 
            label={t('stats')} 
            active={viewMode === 'stats'} 
            expanded={isSidebarOpen} 
            onClick={() => setViewMode('stats')} 
          />
        </nav>

        <div className="px-2 pt-4 border-t border-gray-100 flex flex-col gap-1">
          <NavItem 
            icon={<Download size={20} />} 
            label={t('export')} 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleExportData} 
          />
          <NavItem 
            icon={<Upload size={20} />} 
            label={t('import')} 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={() => fileInputRef.current?.click()} 
          />
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleImportData} 
            accept=".json" 
            className="hidden" 
          />
        </div>

        <div className="p-2 border-t border-gray-100 mt-2">
          <NavItem 
            icon={<LogOut size={20} />} 
            label={t('logout')} 
            active={false} 
            expanded={isSidebarOpen} 
            onClick={handleLogout} 
