import React, { useMemo } from 'react';
import { Gift, MapPin, Users, Heart, ArrowRight, UserPlus, Calendar } from 'lucide-react';
import { Contact, Address, ContactType } from '../types.ts';

interface DashboardProps {
  contacts: Contact[];
  addresses: Address[];
  types: ContactType[];
  onContactClick: (id: string) => void;
  onAddContact: () => void;
  t: (key: any) => string;
  theme?: string;
}

const Dashboard: React.FC<DashboardProps> = ({ contacts, addresses, types, onContactClick, onAddContact, t, theme }) => {
  const upcomingBirthdays = useMemo(() => {
    const today = new Date();
    return contacts
      .filter(c => c.birthDate)
      .map(c => {
        const bday = new Date(c.birthDate!);
        const currentYearBday = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
        const nextBday = currentYearBday < today 
          ? new Date(today.getFullYear() + 1, bday.getMonth(), bday.getDate())
          : currentYearBday;
        const diff = Math.ceil((nextBday.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        const age = nextBday.getFullYear() - bday.getFullYear();
        return { ...c, daysUntil: diff, nextAge: age };
      })
      .sort((a, b) => a.daysUntil - b.daysUntil)
      .slice(0, 8);
  }, [contacts]);

  const stats = [
    { label: t('totalContacts'), value: contacts.length, icon: <Users size={24} />, color: 'bg-blue-500' },
    { label: t('uniqueAddresses'), value: addresses.length, icon: <MapPin size={24} />, color: 'bg-emerald-500' },
    { label: t('favorites'), value: contacts.filter(c => c.isFavorite).length, icon: <Heart size={24} />, color: 'bg-red-500' },
    { label: t('birthdaysThisMonth'), value: contacts.filter(c => c.birthDate && new Date(c.birthDate).getMonth() === new Date().getMonth()).length, icon: <Gift size={24} />, color: 'bg-amber-500' },
  ];

  return (
    <div className={`h-full w-full overflow-y-auto ${theme === 'dark' ? 'bg-slate-950 text-slate-100' : 'bg-gray-50 text-gray-900'}`}>
      <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div>
          <h2 className="text-3xl font-bold mb-1">{t('welcomeBack')}</h2>
          <p className="text-gray-500">{t('welcomeSubtitle')}</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, i) => (
            <div key={i} className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100'} p-6 rounded-3xl shadow-sm border flex items-center gap-4 group transition-shadow`}>
              <div className={`p-3 rounded-2xl ${stat.color} text-white shadow-inner transition-transform group-hover:scale-110`}>{stat.icon}</div>
              <div>
                <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">{stat.label}</p>
                <p className="text-2xl font-black">{stat.value}</p>
              </div>
            </div>
          ))}
        </div>
        <div className="pb-12">
          <div className="space-y-6">
            <h3 className="text-xl font-bold flex items-center gap-2"><Gift className="text-amber-500" /> {t('upcomingBirthdays')}</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
              {upcomingBirthdays.length > 0 ? upcomingBirthdays.map(c => {
                const typeColor = types.find(t_obj => t_obj.id === c.typeId)?.color;
                return (
                  <div key={c.id} onClick={() => onContactClick(c.id)} className={`${theme === 'dark' ? 'bg-slate-900 border-slate-800 hover:border-blue-500' : 'bg-white border-gray-100 hover:border-blue-200'} p-4 rounded-3xl border shadow-sm flex items-center gap-4 cursor-pointer group transition-all`}>
                    <img src={c.photoUrl || `https://ui-avatars.com/api/?name=${c.firstName}+${c.lastName || ''}`} className="w-16 h-16 rounded-2xl object-cover border-4" style={{ borderColor: typeColor }} />
                    <div className="flex-1 min-w-0">
                      <p className="font-bold truncate group-hover:text-blue-500 transition-colors">{c.firstName} {c.lastName}</p>
                      <p className="text-xs text-gray-500 font-medium">{t('turning')} {c.nextAge} {t('yearsOld')}</p>
                      <span className={`text-[10px] px-2 py-0.5 rounded-full font-black uppercase inline-block mt-2 ${theme === 'dark' ? 'bg-amber-900/40 text-amber-400' : 'bg-amber-100 text-amber-700'}`}>
                        {t('inDays')} {c.daysUntil} {c.daysUntil === 1 ? t('day') : t('days')}
                      </span>
                    </div>
                  </div>
                );
              }) : (
                <div className={`col-span-full p-10 rounded-3xl border border-dashed flex flex-col items-center text-gray-400 ${theme === 'dark' ? 'bg-slate-900/50 border-slate-700' : 'bg-gray-50 border-gray-200'}`}>
                  <Calendar size={48} className="mb-2 opacity-20" />
                  <p>{t('noBirthdays')}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Contact, ContactType, Address } from '../types.ts';
import { Activity, User } from 'lucide-react';

interface StatsViewProps {
  contacts: Contact[];
  types: ContactType[];
  addresses: Address[];
  t: (key: any) => string;
  theme?: string;
}

const StatsView: React.FC<StatsViewProps> = ({ contacts, types, addresses, t, theme }) => {
  const isDark = theme === 'dark';

  const typeData = types.map(t_obj => ({
    name: t(t_obj.name as any),
    value: contacts.filter(c => c.typeId === t_obj.id).length,
    color: t_obj.color
  })).filter(d => d.value > 0).sort((a, b) => b.value - a.value);

  const cityCounts = contacts.reduce((acc: any, c) => {
    const addr = addresses.find(a => a.id === c.addressId);
    const city = addr?.city || t('Onbekend');
    acc[city] = (acc[city] || 0) + 1;
    return acc;
  }, {});

  const cityData = Object.entries(cityCounts).map(([city, count]) => ({ city, count: count as number })).sort((a, b) => b.count - a.count).slice(0, 5);

  const topInteractions180Data = useMemo(() => {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - 180);

    return contacts
      .map(c => {
        const recentInteractions = (c.interactions || []).filter(i => new Date(i.date) >= cutoff);
        return {
          ...c,
          interactionCount: recentInteractions.length
        };
      })
      .filter(c => c.interactionCount > 0)
      .sort((a, b) => b.interactionCount - a.interactionCount)
      .slice(0, 10);
  }, [contacts]);

  return (
    <div className={`h-full w-full overflow-y-auto ${isDark ? 'bg-slate-950 text-slate-100' : 'bg-gray-50 text-gray-900'}`}>
      <div className="p-8 max-w-7xl mx-auto space-y-10 pb-24">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className={`${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100'} p-8 rounded-3xl border shadow-sm`}>
            <h3 className="text-xl font-bold mb-6">{t('contactType')}</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={typeData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={5} dataKey="value">
                    {typeData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ 
                      borderRadius: '1rem', 
                      border: 'none', 
                      backgroundColor: isDark ? '#1e293b' : '#ffffff',
                      color: isDark ? '#f1f5f9' : '#0f172a',
                      boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' 
                    }} 
                  />
                  <Legend verticalAlign="bottom" height={36} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>
          <div className={`${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100'} p-8 rounded-3xl border shadow-sm`}>
            <h3 className="text-xl font-bold mb-6">{t('topLocations')}</h3>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={cityData}>
                  <XAxis dataKey="city" stroke={isDark ? "#475569" : "#94a3b8"} fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke={isDark ? "#475569" : "#94a3b8"} fontSize={12} tickLine={false} axisLine={false} />
                  <Tooltip 
                    cursor={{fill: isDark ? '#1e293b' : '#f8fafc'}} 
                    contentStyle={{ 
                      borderRadius: '1rem', 
                      border: 'none',
                      backgroundColor: isDark ? '#1e293b' : '#ffffff',
                      color: isDark ? '#f1f5f9' : '#0f172a'
                    }} 
                  />
                  <Bar dataKey="count" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className={`${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-gray-100'} lg:col-span-2 p-8 rounded-3xl border shadow-sm`}>
            <div className="flex items-center gap-3 mb-8">
              <div className={`p-2 rounded-xl ${isDark ? 'bg-blue-900/30 text-blue-400' : 'bg-blue-50 text-blue-600'}`}>
                <Activity size={20} />
              </div>
              <h3 className="text-xl font-bold">{t('topInteractions180')}</h3>
            </div>

